(window.CLAVE_TODO=window.CLAVE_TODO||{})[23]=[{"a":"Artículo 48","q":[{"i":"23-1","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los servicios de investigación privada, a cargo de detectives privados, consistirán en la realización de las averiguaciones que resulten necesarias para la obtención y aportación, por cuenta de terceros legitimados, de información y pruebas sobre conductas o hechos privados relacionados con los siguientes aspectos:","o":["Los relativos al ámbito económico, laboral, mercantil, financiero y, en general, a la vida personal, familiar o social, exceptuada la que se desarrolle en los domicilios o lugares reservados.","La obtención de información tendente a garantizar el normal desarrollo de las actividades que tengan lugar en ferias, hoteles, exposiciones, espectáculos, certámenes, convenciones, grandes superficies comerciales, locales públicos de gran concurrencia o ámbitos análogos.","La realización de averiguaciones y la obtención de información y pruebas relativas a delitos sólo perseguibles a instancia de parte por encargo de los sujetos legitimados en el proceso penal.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span><span class=\"ref-norma\">Art. 48 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de investigación privada, a cargo de detectives privados, consistirán en la realización de las averiguaciones que resulten necesarias para la obtención y aportación, por cuenta de terceros legitimados, de información y pruebas sobre conductas o hechos privados relacionados con los siguientes aspectos:\"</span>"},{"i":"23-22","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes opciones sobre los servicios de investigación privada es incorrecta?","o":["Los servicios de investigación privada se ejecutarán con respeto a los principios de licitud, necesidad, idoneidad y proporcionalidad.","En la prestación de los servicios de investigación, los detectives privados no podrán utilizar o hacer uso de medios, vehículos o distintivos que puedan confundirse con los de las Fuerzas y Cuerpos de Seguridad.","En todo caso, los despachos de detectives y los detectives privados encargados de las investigaciones velarán por los derechos de sus clientes con respeto a los de los sujetos investigados.","En ningún caso se podrá investigar la vida íntima de las personas que transcurra en sus domicilios u otros lugares reservados, ni podrán utilizarse en este tipo de servicios medios personales, materiales o técnicos de tal forma que atenten contra el derecho al honor, a la intimidad personal o familiar o a la propia imagen o al secreto de las comunicaciones o a la protección de datos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los servicios de investigación privada se ejecutarán con respeto a los principios de licitud, necesidad, idoneidad y proporcionalidad</mark></span><span class=\"ref-norma\">Art. 48 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de investigación privada se ejecutarán con respeto a los principios de razonabilidad, necesidad, idoneidad y proporcionalidad.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-63","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. Los servicios de investigación privada se ejecutarán con respeto a los principios de: señale la INCORRECTA:","o":["Razonabilidad","Reciprocidad","Necesidad","Proporcionalidad"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Reciprocidad</mark></span><span class=\"ref-norma\">Art. 48 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de investigación privada se ejecutarán con respeto a los principios de razonabilidad, necesidad, idoneidad y proporcionalidad.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1428","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. Los servicios de investigación privada, a cargo de detectives privados, consistirán en la realización de las averiguaciones necesarias para la obtención y aportación de información y pruebas sobre conductas o hechos privados. Se realizan por cuenta de:","o":["las partes del proceso.","terceros legitimados.","el Ministerio Fiscal.","los clientes de los despachos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">terceros legitimados</mark></span><span class=\"ref-norma\">Art.  48.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"por cuenta de terceros legitimados, de información y pruebas sobre conductas o hechos privados\"</span>Por cuenta de terceros legitimados."},{"i":"23-ia-1429","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. Entre los servicios de investigación privada están las averiguaciones relativas al ámbito económico, laboral, mercantil, financiero y, en general, a la vida personal, familiar o social, exceptuada:","o":["la que se desarrolle en los domicilios o lugares reservados.","la que se desarrolle en lugares públicos, en los términos que se determinen reglamentariamente.","la que afecte a menores de edad.","la que afecte a la salud de las personas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la que se desarrolle en los domicilios o lugares reservados</mark></span><span class=\"ref-norma\">Art.  48.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"exceptuada la que se desarrolle en los domicilios o lugares reservados\"</span>Se exceptúa la vida desarrollada en domicilios o lugares reservados."},{"i":"23-ia-1430","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. Entre los servicios de investigación privada está la realización de averiguaciones y la obtención de información y pruebas relativas a delitos sólo perseguibles a instancia de parte, por encargo de:","o":["las víctimas de los delitos, en todo caso.","los abogados de las partes.","el Ministerio Fiscal y las acusaciones particulares.","los sujetos legitimados en el proceso penal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los sujetos legitimados en el proceso penal</mark></span><span class=\"ref-norma\">Art.  48.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"por encargo de los sujetos legitimados en el proceso penal\"</span>Por encargo de los sujetos legitimados en el proceso penal."},{"i":"23-ia-1431","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. La aceptación del encargo de servicios de investigación privada por los despachos de detectives requerirá, en todo caso, la acreditación, por el solicitante, del:","o":["motivo de la investigación, de lo que se informará al Ministerio del Interior, salvo que la autoridad judicial disponga otra cosa.","interés económico del solicitante, mediante documento público.","interés legítimo alegado, de lo que se dejará constancia en el expediente de contratación e investigación.","consentimiento de la persona investigada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">interés legítimo alegado, de lo que se dejará constancia en el expediente de contratación e investigación</mark></span><span class=\"ref-norma\">Art.  48.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"requerirá, en todo caso, la acreditación, por el solicitante de los mismos, del interés legítimo alegado, de lo que se dejará constancia en el expediente de contratación e investigación que se abra\"</span>Interés legítimo alegado, que se deja en el expediente."},{"i":"23-ia-1432","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. En ningún caso se podrá investigar la vida íntima de las personas que transcurra en:","o":["sus domicilios, aunque sí en lugares reservados.","sus domicilios u otros lugares reservados.","lugares públicos o abiertos al público.","sus centros de trabajo y domicilios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sus domicilios u otros lugares reservados</mark></span><span class=\"ref-norma\">Art.  48.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"En ningún caso se podrá investigar la vida íntima de las personas que transcurra en sus domicilios u otros lugares reservados\"</span>Domicilios u otros lugares reservados."},{"i":"23-ia-1433","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de investigación privada. Los servicios de investigación privada se ejecutarán con respeto a los principios de:","o":["razonabilidad, necesidad, idoneidad y proporcionalidad.","legalidad, necesidad, idoneidad y proporcionalidad.","razonabilidad, necesidad, intervención mínima y proporcionalidad.","legalidad, congruencia, idoneidad y reserva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">razonabilidad, necesidad, idoneidad y proporcionalidad</mark></span><span class=\"ref-norma\">Art.  48.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de investigación privada se ejecutarán con respeto a los principios de razonabilidad, necesidad, idoneidad y proporcionalidad\"</span>Razonabilidad, necesidad, idoneidad y proporcionalidad."}]},{"a":"Artículo 54","q":[{"i":"23-2","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Qué tipo de planes establecerán las Fuerzas y Cuerpos de Seguridad competentes sobre las empresas, los despachos de detectives privados, el personal, los servicios, los establecimientos, los centros de formación, las medidas de seguridad y cualesquiera otras actividades o servicios regulados en esta ley?","o":["Establecerán planes anuales de inspección extraordinaria.","Establecerán planes anuales de inspección ordinaria.","Establecerán planes bianuales de inspección ordinaria.","Establecerán planes bianuales de inspección extraordinaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Establecerán planes anuales de inspección ordinaria</mark></span><span class=\"ref-norma\">Art. 54 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las Fuerzas y Cuerpos de Seguridad competentes establecerán planes anuales de inspección ordinaria sobre las empresas, los despachos de detectives privados, el personal, los servicios, los establecimientos, los centros de formación, las medidas de seguridad y cualesquiera otras actividades o servicios regulados en esta ley.\"</span>"},{"i":"23-40","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Qué finalidad tendrán las actuaciones de inspección?","o":["La sanción por la comisión de infracciones.","La detección de conductas contrarias a esta ley.","La comprobación del cumplimiento de la legislación aplicable.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La comprobación del cumplimiento de la legislación aplicable</mark></span><span class=\"ref-norma\">Art. 54 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las actuaciones de inspección se atendrán a los principios de injerencia mínima y proporcionalidad, y tendrán por finalidad la comprobación del cumplimiento de la legislación aplicable.\"</span>"},{"i":"23-59","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de inspección. Las actuaciones de inspección se atendrán a los principios de:","o":["Eficacia y proporcionalidad.","Eficacia y contradicción.","Injerencia mínima y proporcionalidad.","Cooperación leal y proporcionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Injerencia mínima y proporcionalidad</mark></span><span class=\"ref-norma\">Art. 54 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las actuaciones de inspección se atendrán a los principios de injerencia mínima y proporcionalidad, y tendrán por finalidad la comprobación del cumplimiento de la legislación aplicable.\"</span>"},{"i":"23-ia-1452","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de inspección. Las Fuerzas y Cuerpos de Seguridad competentes establecerán planes anuales de:","o":["control extraordinario sobre las empresas de seguridad y sus representantes.","inspección ordinaria sobre las empresas, los despachos de detectives privados, el personal, los servicios, los establecimientos, los centros de formación y las medidas de seguridad.","inspección ordinaria sobre las empresas y los despachos, con exclusión del personal, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","formación y control sobre el personal de seguridad privada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">inspección ordinaria sobre las empresas, los despachos de detectives privados, el personal, los servicios, los establecimientos, los centros de formación y las medidas de seguridad</mark></span><span class=\"ref-norma\">Art.  54.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"establecerán planes anuales de inspección ordinaria sobre las empresas, los despachos de detectives privados, el personal, los servicios, los establecimientos, los centros de formación, las medidas de seguridad\"</span>Planes anuales de inspección ordinaria."},{"i":"23-ia-1453","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de inspección. Las actuaciones de inspección se atendrán a los principios de:","o":["injerencia mínima y proporcionalidad.","legalidad y proporcionalidad, sin perjuicio de lo previsto en la normativa vigente.","injerencia mínima y reserva.","necesidad y proporcionalidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">injerencia mínima y proporcionalidad</mark></span><span class=\"ref-norma\">Art.  54.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las actuaciones de inspección se atendrán a los principios de injerencia mínima y proporcionalidad\"</span>Injerencia mínima y proporcionalidad."},{"i":"23-ia-1454","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de inspección. Cuando las actuaciones de inspección recaigan sobre los servicios de investigación privada, las actuaciones se limitarán a la comprobación de su existencia, sin entrar en su contenido, salvo que se encuentre relacionado con:","o":["una investigación judicial o con una denuncia del cliente.","una investigación policial o con la solicitud del investigado, en los términos que se determinen reglamentariamente.","un expediente sancionador exclusivamente.","una investigación judicial o policial o con un expediente sancionador."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una investigación judicial o policial o con un expediente sancionador</mark></span><span class=\"ref-norma\">Art.  54.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"salvo que se encuentre relacionado con una investigación judicial o policial o con un expediente sancionador\"</span>Solo si se relaciona con investigación judicial o policial o expediente sancionador."},{"i":"23-ia-1455","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de inspección. Las inspecciones se realizarán por el Cuerpo Nacional de Policía; por la Guardia Civil, en el caso de los guardas rurales y sus especialidades y centros y cursos de formación relativos a este personal; o, por:","o":["las policías locales competentes, salvo que la autoridad judicial disponga otra cosa.","las Delegaciones del Gobierno.","el cuerpo de policía autonómica competente.","la Inspección de Trabajo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el cuerpo de policía autonómica competente</mark></span><span class=\"ref-norma\">Art.  54.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o, por el cuerpo de policía autonómica competente\"</span>O por el cuerpo de policía autonómica competente."}]},{"a":"Artículo 55","q":[{"i":"23-3","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal que desempeñe funciones de seguridad privada. El ejercicio de funciones de seguridad privada para terceros careciendo de la habilitación o acreditación necesaria es una infracción:","o":["Grave.","Leve.","Menos grave.","Muy grave."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Muy grave</mark></span><span class=\"ref-norma\">Art. 58 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) El ejercicio de funciones de seguridad privada para terceros careciendo de la habilitación o acreditación necesaria.\"</span>"},{"i":"23-4","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes infracciones cometidas por las empresas que desarrollen actividades de seguridad privada, sus representantes legales, los despachos de detectives privados y las centrales de alarma de uso propio, es una infracción grave?","o":["La falta de comunicación por parte de empresas de seguridad informática de las incidencias relativas al sistema de cuya protección sean responsables cuando sea preceptivo.","La no realización de las revisiones anuales obligatorias de los sistemas o medidas de seguridad cuyo mantenimiento tuvieren contratado.","El empleo o utilización, en servicios de seguridad privada, de medidas o de medios personales, materiales o técnicos de forma que se atente contra el derecho al honor, a la intimidad personal o familiar o a la propia imagen o al secreto de las comunicaciones, siempre que no constituyan delito.","La prestación de servicios de seguridad privada sin formalizar los correspondientes contratos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La no realización de las revisiones anuales obligatorias de los sistemas o medidas de seguridad cuyo mantenimiento tuvieren contratado</mark></span><span class=\"ref-norma\">Art. 57 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"n) La no realización de las revisiones anuales obligatorias de los sistemas o medidas de seguridad cuyo mantenimiento tuvieren contratado.\"</span>"},{"i":"23-6","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las infracciones muy graves prescribirán:","o":["1 año.","2 años.","3 años.","4 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">2 años</mark></span><span class=\"ref-norma\">Art. 56 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las infracciones leves prescribirán a los seis meses, las graves al año y las muy graves a los dos años.\"</span>"},{"i":"23-7","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación de los detectives privados. ¿Qué carácter tendrán las investigaciones privadas?","o":["Reservado.","Público.","Secreto.","Confidencial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reservado</mark></span><span class=\"ref-norma\">Art. 58 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"l) La no realización del informe de investigación que preceptivamente deben elaborar los detectives privados o su no entrega al contratante del servicio, o la elaboración de informes paralelos.\"</span>"},{"i":"23-8","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes infracciones cometidas por una empresa que desarrolle actividades de seguridad privada es una infracción grave?","o":["El incumplimiento de las previsiones normativas sobre adquisición y uso de armas.","La retención de la documentación profesional del personal de seguridad privada, o de la acreditación del personal acreditado.","La negativa a facilitar cuando proceda, la información contenida en los contratos de seguridad privada.","La instalación o utilización de medios materiales o técnicos no homologados cuando la homologación sea preceptiva y sean susceptibles de causar grave daño a las personas o a los intereses generales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La retención de la documentación profesional del personal de seguridad privada, o de la acreditación del personal acreditado</mark></span><span class=\"ref-norma\">Art. 57 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) La retención de la documentación profesional del personal de seguridad privada, o de la acreditación del personal acreditado.\"</span>"},{"i":"23-9","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Señale la incorrecta sobre las infracciones cometidas por las empresas que desarrollen actividades de seguridad privada, sus representantes legales, los despachos de detectives privados y las centrales de alarma de uso propio.","o":["Es infracción muy grave la prestación de servicios de seguridad privada a terceros careciendo de autorización, o en su caso, sin haber presentado la declaración responsable.","Es infracción leve, en general, el incumplimiento de los trámites, condiciones o formalidades establecidos por esta ley, siempre que no constituya infracción grave o muy grave.","Es infracción muy grave la contratación o utilización, en servicios de seguridad privada, de personas que carecen de la habilitación o acreditación correspondiente.","Es infracción grave la prestación de servicios de seguridad privada con armas de fuego fuera de lo dispuesto en esta ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Es infracción grave la prestación de servicios de seguridad privada con armas de fuego fuera de lo dispuesto en esta ley</mark></span><span class=\"ref-norma\">Art. 57 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"g) La prestación de servicios de seguridad privada con armas de fuego fuera de lo dispuesto en esta ley.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-12","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones cometidas por los usuarios y centros de formación. La utilización de personal docente no acreditado en actividades de formación, es una infracción:","o":["Leve.","Menos grave.","Muy grave.","Grave."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Grave</mark></span><span class=\"ref-norma\">Art. 59 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"f) La utilización de personal docente no acreditado en actividades de formación.\"</span>"},{"i":"23-21","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes infracciones cometidas por el personal que desempeñe funciones de seguridad privada es incorrecta?","o":["La actuación sin el uniforme o indumentaria que reglamentariamente sean exigibles, o sin portar los distintivos o la documentación profesional, así como la correspondiente al arma de fuego utilizada en la prestación del servicio, es una infracción leve.","Es una infracción muy grave la negativa a prestar colaboración a las Fuerzas y Cuerpos de Seguridad, cuando sea procedente, en la investigación y persecución de actos delictivos, en el descubrimiento y detención de los delincuentes.","Es infracción leve la falta de diligencia en el cumplimiento de las respectivas funciones por parte del personal habilitado o acreditado.","La no identificación profesional, en el ejercicio de sus respectivas funciones, cuando fueren requeridos para ello por los ciudadanos, es una infracción grave."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Es infracción leve la falta de diligencia en el cumplimiento de las respectivas funciones por parte del personal habilitado o acreditado</mark></span><span class=\"ref-norma\">Art. 58 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"g) La falta de diligencia en el cumplimiento de las respectivas funciones por parte del personal habilitado o acreditado.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-42","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuándo prescriben las infracciones leves?","o":["3 meses.","6 meses.","2 años.","1 año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">6 meses</mark></span><span class=\"ref-norma\">Art. 56 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las infracciones leves prescribirán a los seis meses, las graves al año y las muy graves a los dos años.\"</span>"},{"i":"23-54","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los miembros de las Fuerzas y Cuerpos de Seguridad competentes podrán acordar excepcionalmente las siguientes medidas provisionales anteriores a la eventual incoación de un procedimiento sancionador, dando cuenta de ello inmediatamente a la autoridad competente:","o":["La retirada de la tarjeta de identificación profesional al personal de seguridad o de la acreditación al personal acreditado, cuando resulten detenidos por su implicación en la comisión de hechos delictivos.","El cese de la actividad docente en materia de seguridad privada, cuando se constate que los centros que la imparten, no hayan presentado la declaración responsable o el profesorado no tuviera la acreditación correspondiente.","La suspensión, parcial o total, de las actividades de los establecimientos que sean notoriamente vulnerables y no tengan en funcionamiento las medidas de seguridad obligatorias.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 55 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los miembros de las Fuerzas y Cuerpos de Seguridad competentes podrán acordar excepcionalmente las siguientes medidas provisionales anteriores a la eventual incoación de un procedimiento sancionador, dando cuenta de ello inmediatamente a la autoridad competente:\"</span>"},{"i":"23-64","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las medidas provisionales anteriores al procedimiento acordadas por las Fuerzas y Cuerpos de Seguridad habrán de ser ratificadas, modificadas o revocadas:","o":["En el plazo máximo de dos días.","En el plazo máximo de quince días.","En el plazo máximo de un mes.","En el plazo máximo de dos meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el plazo máximo de quince días</mark></span><span class=\"ref-norma\">Art. 55 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Estas medidas habrán de ser ratificadas, modificadas o revocadas en el plazo máximo de quince días.\"</span>"},{"i":"23-76","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes infracciones cometidas por los usuarios y centros de formación es una infracción muy grave?","o":["La utilización de personal docente no acreditado en actividades de formación.","El incumplimiento de las revisiones preceptivas de los sistemas o medidas de seguridad obligatorias que tengan instalados.","Obligar a personal habilitado contratado a realizar otras funciones distintas a aquellas para los que fue contratado.","La utilización de aparatos de alarma u otros dispositivos de seguridad no homologados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Obligar a personal habilitado contratado a realizar otras funciones distintas a aquellas para los que fue contratado</mark></span><span class=\"ref-norma\">Art. 59 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"k) Obligar a personal habilitado contratado a realizar otras funciones distintas a aquellas para las que fue contratado.\"</span>"},{"i":"23-87","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Por cuál de las siguientes infracciones cometidas por los usuarios y los centros de formación podrá imponerse la sanción de apercibimiento?","o":["La utilización de aparatos de alarma u otros dispositivos de seguridad no homologados.","El anormal funcionamiento de las medidas o sistemas de seguridad que se tengan instalados.","La utilización de personal docente no acreditado en actividades de formación.","La no comunicación al órgano competente de las modificaciones que afecten a cualquiera de los requisitos que dieron lugar a la autorización de los centros de formación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El anormal funcionamiento de las medidas o sistemas de seguridad que se tengan instalados</mark></span><span class=\"ref-norma\">Art. 59 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"b) El anormal funcionamiento de las medidas o sistemas de seguridad que se tengan instalados.\"</span>"},{"i":"23-88","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La contratación o utilización, en servicios de seguridad privada, de personas que carezcan de la habilitación o acreditación correspondiente se categoriza como una infracción:","o":["Muy grave.","Leve.","No comete ninguna infracción.","Grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Muy grave</mark></span><span class=\"ref-norma\">Art. 57 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"b) La contratación o utilización, en servicios de seguridad privada, de personas que carezcan de la habilitación o acreditación correspondiente.\"</span>"},{"i":"23-104","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La utilización, en el desempeño de funciones de seguridad privada, de personal de seguridad privada, con una antigüedad mínima de un año en la empresa, que no haya realizado los correspondientes cursos de actualización o especialización, no los haya superado, o no los haya realizado con la periodicidad que reglamentariamente se determine, es una infracción:","o":["Grave.","Leve.","No comete ninguna infracción.","Muy grave."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Grave</mark></span><span class=\"ref-norma\">Art. 57 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"h) La utilización, en el desempeño de funciones de seguridad privada, de personal de seguridad privada, con una antigüedad mínima de un año en la empresa, que no haya realizado los correspondientes cursos de actualización o especialización, no los haya superado, o no los haya realizado con la periodicidad que reglamentariamente se determine.\"</span>"},{"i":"23-109","p":"Ley 5/2014, de Seguridad Privada. ¿Cuál de las siguientes infracciones cometidas por el personal que desempeñe funciones de seguridad privada no es una infracción muy grave?","o":["La realización de actividades prohibidas sobre reuniones o manifestaciones.","La negativa a identificarse profesionalmente, en el ejercicio de sus respectivas funciones, ante la autoridad o sus agentes, cuando fueren requeridos para ello.","El ejercicio abusivo de sus funciones en relación con los ciudadanos.","La no identificación profesional, en el ejercicio de sus respectivas funciones, cuando fueren requeridos para ello por los ciudadanos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La no identificación profesional, en el ejercicio de sus respectivas funciones, cuando fueren requeridos para ello por los ciudadanos</mark></span><span class=\"ref-norma\">Art. 58 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"e) La no identificación profesional, en el ejercicio de sus respectivas funciones, cuando fueren requeridos para ello por los ciudadanos.\"</span>"},{"i":"23-110","p":"Ley 5/2014, de Seguridad Privada. Infracciones cometidas por el personal que desempeñe funciones de seguridad privada. La no cumplimentación, total o parcial, por parte de los técnicos acreditados, del documento justificativo de las revisiones obligatorias de los sistemas de seguridad conectados a centrales receptoras de alarmas, centros de control o de videovigilancia, es una infracción:","o":["Grave.","Muy grave.","Leve.","No comete ninguna infracción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Leve</mark></span><span class=\"ref-norma\">Art. 58 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"c) La no cumplimentación, total o parcial, por parte de los técnicos acreditados, del documento justificativo de las revisiones obligatorias de los sistemas de seguridad conectados a centrales receptoras de alarmas, centros de control o de videovigilancia.\"</span>"},{"i":"23-111","p":"Ley 5/2014, de Seguridad Privada. Infracciones cometidas por los usuarios y centros de formación. La negativa a prestar auxilio o colaboración a las Fuerzas y Cuerpos de Seguridad competentes en la realización de las funciones inspectoras de las medidas de seguridad, de los centros de formación y de los establecimientos obligados, es una infracción:","o":["Grave.","Leve.","No es infracción.","Muy grave."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Muy grave</mark></span><span class=\"ref-norma\">Art. 59 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) La negativa a prestar auxilio o colaboración a las Fuerzas y Cuerpos de Seguridad competentes en la realización de las funciones inspectoras de las medidas de seguridad, de los centros de formación y de los establecimientos obligados.\"</span>"},{"i":"23-112","p":"Ley 5/2014, de Seguridad Privada. Infracciones cometidas por los usuarios y los centros de formación. Señale la opción incorrecta en esta materia:","o":["Es una infracción muy grave la negativa a prestar auxilio o colaboración a las Fuerzas y Cuerpos de Seguridad competentes en la realización de las funciones inspectoras de las medidas de seguridad.","La impartición de los cursos de formación fuera de las instalaciones autorizadas de los centros de formación, es una infracción grave.","La entrada en funcionamiento, sin previa autorización, de centrales receptoras de alarmas de uso propio por parte de entidades públicas o privadas, es una infracción muy grave.","Es una infracción grave la utilización de aparatos o dispositivos de seguridad sin ajustarse a las normas que les sean aplicables o cuando su funcionamiento cause daños o perjuicios desproporcionados a terceros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Es una infracción grave la utilización de aparatos o dispositivos de seguridad sin ajustarse a las normas que les sean aplicables o cuando su funcionamiento cause daños o perjuicios desproporcionados a terceros</mark></span><span class=\"ref-norma\">Art. 59 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) La utilización de aparatos o dispositivos de seguridad sin ajustarse a las normas que los regulen, o cuando su funcionamiento cause daños o molestias desproporcionados a terceros.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-140","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Pueden incurrir en las infracciones tipificadas en la ley para las empresas que desarrollen actividades de seguridad privada, además de éstas:","o":["Sus representantes legales, los despachos de detectives privados y los centros de formación, conforme al procedimiento que reglamentariamente se establezca.","Los usuarios de servicios de seguridad privada y las centrales de alarma de uso propio.","Sus representantes legales, los despachos de detectives privados y las centrales de alarma de uso propio.","Sus representantes legales, el personal acreditado y las centrales de alarma de uso propio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sus representantes legales, los despachos de detectives privados y las centrales de alarma de uso propio</mark></span><span class=\"ref-norma\">Art. 57 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"Las empresas que desarrollen actividades de seguridad privada, sus representantes legales, los despachos de detectives privados y las centrales de alarma de uso propio, podrán incurrir en las siguientes infracciones\"</span>"},{"i":"23-ia-1501","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Los miembros de las Fuerzas y Cuerpos de Seguridad competentes podrán acordar excepcionalmente medidas provisionales anteriores a la eventual incoación de un procedimiento sancionador, dando cuenta de ello:","o":["inmediatamente a la autoridad competente.","en el plazo de cuarenta y ocho horas a la autoridad competente.","inmediatamente a la autoridad judicial.","en el plazo de quince días al órgano sancionador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">inmediatamente a la autoridad competente</mark></span><span class=\"ref-norma\">Art.  55.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"dando cuenta de ello inmediatamente a la autoridad competente\"</span>Inmediatamente a la autoridad competente."},{"i":"23-ia-1502","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Entre las medidas provisionales está la ocupación o precinto de vehículos, armas, material o equipos prohibidos, no homologados o que resulten peligrosos o perjudiciales, así como de los instrumentos y efectos de la infracción, en supuestos de:","o":["riesgo cierto para la seguridad pública o para las personas, en los términos que se determinen reglamentariamente.","peligro grave para el orden público o los bienes.","alteración de la seguridad ciudadana.","grave riesgo o peligro inminente para las personas o bienes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">grave riesgo o peligro inminente para las personas o bienes</mark></span><span class=\"ref-norma\">Art.  55.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en supuestos de grave riesgo o peligro inminente para las personas o bienes\"</span>Grave riesgo o peligro inminente para personas o bienes."},{"i":"23-ia-1503","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Entre las medidas provisionales está el cese de la actividad docente en materia de seguridad privada, cuando se constate que los centros que la imparten no hayan presentado la declaración responsable o:","o":["el profesorado no tuviera la titulación universitaria exigida.","no cuenten con licencia municipal de apertura.","el profesorado no tuviera la acreditación correspondiente.","los alumnos no estén habilitados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el profesorado no tuviera la acreditación correspondiente</mark></span><span class=\"ref-norma\">Art.  55.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o el profesorado no tuviera la acreditación correspondiente\"</span>O el profesorado carece de acreditación."},{"i":"23-ia-1504","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. La desconexión de los sistemas de alarma cuyo mal funcionamiento causare perjuicios a la seguridad pública o molestias a terceros se suplirá, cuando se trate de establecimientos obligados a contar con esta medida de seguridad, mediante:","o":["la instalación de un sistema alternativo homologado.","el establecimiento de un servicio permanente de vigilancia y protección privada.","la comunicación inmediata a las Fuerzas y Cuerpos de Seguridad, salvo que la autoridad judicial disponga otra cosa.","la suspensión temporal de la actividad del establecimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el establecimiento de un servicio permanente de vigilancia y protección privada</mark></span><span class=\"ref-norma\">Art.  55.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la desconexión se suplirá mediante el establecimiento de un servicio permanente de vigilancia y protección privada\"</span>Se sustituye por un servicio permanente de vigilancia y protección privada."},{"i":"23-ia-1505","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Podrá acordarse la retirada de la tarjeta de identificación profesional al personal de seguridad o de la acreditación al personal acreditado, cuando:","o":["resulten detenidos por su implicación en la comisión de hechos delictivos.","sean investigados por la comisión de infracciones muy graves, previo informe de la unidad policial competente.","hayan sido sancionados por infracción grave.","se les haya retirado el permiso de armas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">resulten detenidos por su implicación en la comisión de hechos delictivos</mark></span><span class=\"ref-norma\">Art.  55.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando resulten detenidos por su implicación en la comisión de hechos delictivos\"</span>Cuando resulten detenidos por hechos delictivos."},{"i":"23-ia-1506","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Se podrá acordar la suspensión, parcial o total, de las actividades de los establecimientos que:","o":["no hayan presentado la declaración responsable de apertura, sin perjuicio de lo previsto en la normativa vigente.","hayan sido sancionados por no adoptar medidas de seguridad.","se encuentren en zonas de especial riesgo.","sean notoriamente vulnerables y no tengan en funcionamiento las medidas de seguridad obligatorias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sean notoriamente vulnerables y no tengan en funcionamiento las medidas de seguridad obligatorias</mark></span><span class=\"ref-norma\">Art.  55.1.g · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La suspensión, parcial o total, de las actividades de los establecimientos que sean notoriamente vulnerables y no tengan en funcionamiento las medidas de seguridad obligatorias\"</span>Establecimientos notoriamente vulnerables sin las medidas obligatorias en funcionamiento."},{"i":"23-ia-1507","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Las medidas provisionales anteriores al procedimiento habrán de ser ratificadas, modificadas o revocadas en el plazo máximo de:","o":["diez días.","un mes.","quince días.","setenta y dos horas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">quince días</mark></span><span class=\"ref-norma\">Art.  55.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Estas medidas habrán de ser ratificadas, modificadas o revocadas en el plazo máximo de quince días\"</span>El plazo máximo es de quince días."},{"i":"23-ia-1508","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Las medidas provisionales quedarán sin efecto si, transcurrido el plazo de quince días, no se incoa el procedimiento sancionador o el acuerdo de incoación no contiene un pronunciamiento expreso acerca de las mismas. El órgano competente para ratificar, revocar o modificar las medidas provisionales será:","o":["el competente para resolver el procedimiento sancionador.","el competente para incoar el procedimiento sancionador.","la autoridad judicial.","el titular de la Delegación del Gobierno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el competente para incoar el procedimiento sancionador</mark></span><span class=\"ref-norma\">Art.  55.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El órgano competente para ratificar, revocar o modificar las medidas provisionales será el competente para incoar el procedimiento sancionador\"</span>Será el competente para incoar el procedimiento sancionador."},{"i":"23-ia-1509","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. La duración de las medidas provisionales, que deberá ser notificada a los interesados, no podrá exceder de:","o":["seis meses.","tres meses.","un año.","quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">seis meses</mark></span><span class=\"ref-norma\">Art.  55.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La duración de las medidas contempladas en el apartado 1, que deberá ser notificada a los interesados, no podrá exceder de seis meses\"</span>No puede exceder de seis meses."},{"i":"23-ia-1510","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas provisionales anteriores al procedimiento. Con independencia de las responsabilidades penales o administrativas a que hubiere lugar, los miembros de las Fuerzas y Cuerpos de Seguridad competentes se harán cargo de las armas que se porten o utilicen ilegalmente, siguiendo lo dispuesto al respecto en:","o":["la Ley de Enjuiciamiento Criminal.","el Reglamento de seguridad privada.","la Ley de Seguridad Ciudadana.","la normativa de armas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la normativa de armas</mark></span><span class=\"ref-norma\">Art.  55.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"siguiendo lo dispuesto al respecto en la normativa de armas\"</span>Conforme a la normativa de armas."},{"i":"23-ia-1511","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Clasificación y prescripción. Las infracciones de las normas contenidas en la Ley de Seguridad Privada podrán ser:","o":["leves y graves.","leves, menos graves y graves.","leves, graves y muy graves.","graves, muy graves y especialmente graves."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">leves, graves y muy graves</mark></span><span class=\"ref-norma\">Art.  56.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las infracciones de las normas contenidas en esta ley podrán ser leves, graves y muy graves\"</span>Leves, graves y muy graves."},{"i":"23-ia-1512","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Clasificación y prescripción. Las infracciones leves prescribirán a los seis meses, las graves:","o":["a los dos años y las muy graves a los tres años.","al año y las muy graves a los dos años.","al año y las muy graves a los tres años.","a los seis meses y las muy graves al año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al año y las muy graves a los dos años</mark></span><span class=\"ref-norma\">Art.  56.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las infracciones leves prescribirán a los seis meses, las graves al año y las muy graves a los dos años\"</span>Leves, seis meses; graves, un año; muy graves, dos años."},{"i":"23-ia-1513","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Clasificación y prescripción. En las infracciones derivadas de una actividad continuada, la fecha inicial del cómputo del plazo de prescripción será:","o":["la de la finalización de la actividad o la del último acto en que la infracción se consume.","la de la primera actuación infractora.","la del conocimiento de la infracción por la autoridad competente, en los términos que se determinen reglamentariamente.","la de incoación del procedimiento sancionador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la de la finalización de la actividad o la del último acto en que la infracción se consume</mark></span><span class=\"ref-norma\">Art.  56.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la fecha inicial del cómputo será la de la finalización de la actividad o la del último acto en que la infracción se consume\"</span>La de finalización de la actividad o del último acto de consumación."},{"i":"23-ia-1514","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Clasificación y prescripción. La prescripción se interrumpirá por la iniciación, con conocimiento del interesado, del procedimiento sancionador, volviendo a correr el plazo si el expediente permaneciera paralizado durante:","o":["tres meses por causa imputable a la Administración.","un año por causa no imputable al interesado.","dos meses por causa no imputable a aquellos contra quienes se dirija, salvo que la autoridad judicial disponga otra cosa.","seis meses por causa no imputable a aquellos contra quienes se dirija."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seis meses por causa no imputable a aquellos contra quienes se dirija</mark></span><span class=\"ref-norma\">Art.  56.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"volviendo a correr el plazo si el expediente permaneciera paralizado durante seis meses por causa no imputable a aquellos contra quienes se dirija\"</span>Seis meses de paralización no imputable al interesado."},{"i":"23-ia-1515","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Señale la conducta que constituye infracción MUY GRAVE de las empresas que desarrollen actividades de seguridad privada:","o":["La carencia o falta de cumplimentación de cualquiera de los libros-registro obligatorios, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","La falta de diligencia en la cumplimentación de los libros-registro obligatorios.","La prestación de servicios de seguridad privada a terceros careciendo de autorización o, en su caso, sin haber presentado la declaración responsable.","La retención de la documentación profesional del personal de seguridad privada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La prestación de servicios de seguridad privada a terceros careciendo de autorización o, en su caso, sin haber presentado la declaración responsable</mark></span><span class=\"ref-norma\">Art.  57.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La prestación de servicios de seguridad privada a terceros careciendo de autorización o, en su caso, sin haber presentado la declaración responsable\"</span>La prestación sin autorización o sin declaración responsable es muy grave; las demás son graves o leves."},{"i":"23-ia-1516","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas de seguridad la contratación o utilización, en servicios de seguridad privada, de personas que:","o":["carezcan de la formación de actualización exigible.","carezcan de la habilitación o acreditación correspondiente.","no hayan sido dadas de alta en el Registro Nacional, en los términos que se determinen reglamentariamente.","no hayan superado los cursos de especialización."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">carezcan de la habilitación o acreditación correspondiente</mark></span><span class=\"ref-norma\">Art.  57.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La contratación o utilización, en servicios de seguridad privada, de personas que carezcan de la habilitación o acreditación correspondiente\"</span>Personas sin habilitación o acreditación."},{"i":"23-ia-1517","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. La instalación o utilización de medios materiales o técnicos no homologados cuando la homologación sea preceptiva constituye infracción muy grave cuando sean susceptibles de causar:","o":["grave daño a las personas o a los intereses generales.","daño a las personas o a los bienes protegidos, salvo que la autoridad judicial disponga otra cosa.","perjuicio a la seguridad pública.","grave riesgo para el orden público."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">grave daño a las personas o a los intereses generales</mark></span><span class=\"ref-norma\">Art.  57.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y sean susceptibles de causar grave daño a las personas o a los intereses generales\"</span>Si pueden causar grave daño a personas o intereses generales."},{"i":"23-ia-1518","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas la negativa a facilitar, cuando proceda, la información contenida en:","o":["los contratos de seguridad privada y en los libros de contabilidad de la empresa, previo informe de la unidad policial competente.","los libros-registro y en los expedientes de personal.","los informes de investigación privada y en las cuentas anuales.","los contratos de seguridad privada, en los libros-registro o el acceso a los informes de investigación privada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los contratos de seguridad privada, en los libros-registro o el acceso a los informes de investigación privada</mark></span><span class=\"ref-norma\">Art.  57.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La negativa a facilitar, cuando proceda, la información contenida en los contratos de seguridad privada, en los libros-registro o el acceso a los informes de investigación privada\"</span>Contratos, libros-registro e informes de investigación privada."},{"i":"23-ia-1519","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas la negativa a prestar auxilio o colaboración a las Fuerzas y Cuerpos de Seguridad en la investigación y persecución de actos delictivos; en el descubrimiento y detención de los delincuentes; o en:","o":["la realización de planes de seguridad y prevención del delito, sin perjuicio de lo previsto en la normativa vigente.","la comunicación de incidencias y falsas alarmas.","la realización de las funciones inspectoras o de control que les correspondan.","la prevención de infracciones administrativas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la realización de las funciones inspectoras o de control que les correspondan</mark></span><span class=\"ref-norma\">Art.  57.1.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o en la realización de las funciones inspectoras o de control que les correspondan\"</span>O en las funciones inspectoras o de control."},{"i":"23-ia-1520","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas la falta de transmisión a las Fuerzas y Cuerpos de Seguridad competentes de las alarmas reales que se registren en las centrales receptoras de alarmas privadas, incluidas las de uso propio, así como:","o":["la transmisión de falsas alarmas por negligencia.","el retraso en la transmisión de las mismas, cuando estas conductas no estén justificadas.","la falta de verificación previa de las alarmas recibidas, en los términos que se determinen reglamentariamente.","el retraso en la transmisión superior a quince minutos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el retraso en la transmisión de las mismas, cuando estas conductas no estén justificadas</mark></span><span class=\"ref-norma\">Art.  57.1.n · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como el retraso en la transmisión de las mismas, cuando estas conductas no estén justificadas\"</span>También el retraso injustificado en la transmisión."},{"i":"23-ia-1521","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas:","o":["la prestación de servicios de seguridad privada sin formalizar los correspondientes contratos.","la prestación de servicios de seguridad sin comunicar correctamente los contratos.","la prestación de servicios de seguridad privada sin cumplir lo estipulado en el contrato.","la prestación de servicios en condiciones distintas a las previstas en la comunicación del contrato."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la prestación de servicios de seguridad privada sin formalizar los correspondientes contratos</mark></span><span class=\"ref-norma\">Art.  57.1.p · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La prestación de servicios de seguridad privada sin formalizar los correspondientes contratos\"</span>Sin formalizar contratos es muy grave; incumplir o comunicar mal el contrato son graves."},{"i":"23-ia-1522","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas la comisión de una tercera infracción grave o de una grave y otra muy grave en el período de:","o":["un año, habiendo sido sancionado por las anteriores.","tres años, habiendo recaído sanción por las anteriores.","dos años, aunque no se haya sancionado por las anteriores.","dos años, habiendo sido sancionado por las anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos años, habiendo sido sancionado por las anteriores</mark></span><span class=\"ref-norma\">Art.  57.1.s · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La comisión de una tercera infracción grave o de una grave y otra muy grave en el período de dos años, habiendo sido sancionado por las anteriores\"</span>Tres graves o grave y muy grave en dos años, con sanción por las anteriores."},{"i":"23-ia-1523","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción muy grave de las empresas la prestación de actividades ajenas a las de seguridad privada, excepto:","o":["las de formación del personal, salvo que la autoridad judicial disponga otra cosa.","las de investigación privada.","las compatibles previstas en la ley.","las de seguridad informática."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las compatibles previstas en la ley</mark></span><span class=\"ref-norma\">Art.  57.1.t · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La prestación de actividades ajenas a las de seguridad privada, excepto las compatibles previstas en el artículo 6 de la presente ley\"</span>Excepto las actividades compatibles."},{"i":"23-ia-1524","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas:","o":["la instalación de medios no homologados susceptibles de causar grave daño a las personas, previo informe de la unidad policial competente.","la instalación o utilización de medios materiales o técnicos no homologados, cuando la homologación sea preceptiva.","la negativa a facilitar la información contenida en los contratos de seguridad privada.","la prestación de servicios con armas de fuego fuera de lo dispuesto en la ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la instalación o utilización de medios materiales o técnicos no homologados, cuando la homologación sea preceptiva</mark></span><span class=\"ref-norma\">Art.  57.2.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La instalación o utilización de medios materiales o técnicos no homologados, cuando la homologación sea preceptiva\"</span>Sin la nota de grave daño es infracción grave."},{"i":"23-ia-1525","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas:","o":["la retención de la documentación profesional del personal de seguridad privada, o de la acreditación del personal acreditado.","la utilización de personal sin habilitación ni acreditación, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","la negativa a identificarse ante la autoridad.","la contratación de instructores de tiro sin habilitación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la retención de la documentación profesional del personal de seguridad privada, o de la acreditación del personal acreditado</mark></span><span class=\"ref-norma\">Art.  57.2.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La retención de la documentación profesional del personal de seguridad privada, o de la acreditación del personal acreditado\"</span>Retener la documentación profesional del personal es grave."},{"i":"23-ia-1526","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas la prestación de servicios de seguridad privada sin comunicar correctamente los correspondientes contratos al Ministerio del Interior o al órgano autonómico competente, o en los casos en que la comunicación se haya producido:","o":["fuera del plazo de diez días.","con posterioridad a la finalización del servicio.","sin firma del cliente.","con posterioridad al inicio del servicio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con posterioridad al inicio del servicio</mark></span><span class=\"ref-norma\">Art.  57.2.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o en los casos en que la comunicación se haya producido con posterioridad al inicio del servicio\"</span>La comunicación posterior al inicio del servicio."},{"i":"23-ia-1527","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas la falta de sustitución ante:","o":["la baja médica del personal de seguridad privada durante el servicio, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","la ausencia del jefe de seguridad en el servicio.","el abandono o la omisión injustificados del servicio por parte del personal de seguridad privada, dentro de la jornada laboral establecida.","el cese del contrato con el cliente durante la jornada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el abandono o la omisión injustificados del servicio por parte del personal de seguridad privada, dentro de la jornada laboral establecida</mark></span><span class=\"ref-norma\">Art.  57.2.g · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La falta de sustitución ante el abandono o la omisión injustificados del servicio por parte del personal de seguridad privada, dentro de la jornada laboral establecida\"</span>Falta de sustitución ante abandono u omisión injustificados del servicio."},{"i":"23-ia-1528","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas la utilización de personal de seguridad privada, con una antigüedad mínima de un año en la empresa, que:","o":["no haya renovado la tarjeta de identidad profesional, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","no haya realizado los correspondientes cursos de actualización o especialización, no los haya superado, o no los haya realizado con la periodicidad que reglamentariamente se determine.","no haya superado el período de prueba.","no haya realizado el curso de formación previa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no haya realizado los correspondientes cursos de actualización o especialización, no los haya superado, o no los haya realizado con la periodicidad que reglamentariamente se determine</mark></span><span class=\"ref-norma\">Art.  57.2.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con una antigüedad mínima de un año en la empresa, que no haya realizado los correspondientes cursos de actualización o especialización, no los haya superado, o no los haya realizado con la periodicidad que reglamentariamente se determine\"</span>Antigüedad mínima de un año y sin cursos de actualización o especialización."},{"i":"23-ia-1529","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas la comunicación de una o más falsas alarmas por:","o":["negligencia, deficiente funcionamiento o falta de verificación previa.","negligencia o dolo del operador.","falta de personal o de medios técnicos, previo informe de la unidad policial competente.","error de los usuarios del sistema."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">negligencia, deficiente funcionamiento o falta de verificación previa</mark></span><span class=\"ref-norma\">Art.  57.2.j · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La comunicación de una o más falsas alarmas por negligencia, deficiente funcionamiento o falta de verificación previa\"</span>Falsas alarmas por negligencia, deficiente funcionamiento o falta de verificación previa."},{"i":"23-ia-1530","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas:","o":["el incumplimiento de la periodicidad de las revisiones obligatorias de los sistemas cuyo mantenimiento tuvieren contratado, sin perjuicio de lo previsto en la normativa vigente.","la falta de diligencia en la cumplimentación de los libros-registro obligatorios.","el incumplimiento de los trámites o formalidades establecidos por la ley.","la no realización de las revisiones anuales obligatorias de los sistemas o medidas de seguridad cuyo mantenimiento tuvieren contratado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la no realización de las revisiones anuales obligatorias de los sistemas o medidas de seguridad cuyo mantenimiento tuvieren contratado</mark></span><span class=\"ref-norma\">Art.  57.2.n · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La no realización de las revisiones anuales obligatorias de los sistemas o medidas de seguridad cuyo mantenimiento tuvieren contratado\"</span>No realizar las revisiones es grave; incumplir su periodicidad es leve."},{"i":"23-ia-1531","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción grave de las empresas la actuación de vigilantes de seguridad en el exterior de las instalaciones, inmuebles o propiedades de cuya vigilancia o protección estuvieran encargadas con motivo de la prestación de servicios de tal naturaleza:","o":["sin autorización previa del órgano competente.","sin comunicación a las Fuerzas y Cuerpos de Seguridad.","fuera de los supuestos legalmente previstos.","fuera del horario autorizado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">fuera de los supuestos legalmente previstos</mark></span><span class=\"ref-norma\">Art.  57.2.u · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"fuera de los supuestos legalmente previstos\"</span>Fuera de los supuestos legalmente previstos."},{"i":"23-ia-1532","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Señale la conducta que constituye infracción LEVE de las empresas:","o":["La carencia o falta de cumplimentación de cualquiera de los libros-registro obligatorios.","La utilización en los servicios de seguridad privada de vehículos, uniformes o distintivos con apariencia o semejanza a los de las Fuerzas y Cuerpos de Seguridad o de las Fuerzas Armadas.","La prestación de servicios con uniformes que no reúnan las características reglamentarias, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","La apertura de delegaciones sin la autorización necesaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La utilización en los servicios de seguridad privada de vehículos, uniformes o distintivos con apariencia o semejanza a los de las Fuerzas y Cuerpos de Seguridad o de las Fuerzas Armadas</mark></span><span class=\"ref-norma\">Art.  57.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La utilización en los servicios de seguridad privada de vehículos, uniformes o distintivos con apariencia o semejanza a los de las Fuerzas y Cuerpos de Seguridad o de las Fuerzas Armadas\"</span>La semejanza con los de las Fuerzas y Cuerpos es leve para las empresas."},{"i":"23-ia-1533","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de las empresas. Constituye infracción leve de las empresas:","o":["la falta de diligencia en la cumplimentación de los libros-registro obligatorios.","la carencia de los libros-registro obligatorios.","la falta de comunicación de todo cambio relativo a su forma jurídica, previo informe de la unidad policial competente.","la falta de comunicación de las altas y bajas de personal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la falta de diligencia en la cumplimentación de los libros-registro obligatorios</mark></span><span class=\"ref-norma\">Art.  57.3.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La falta de diligencia en la cumplimentación de los libros-registro obligatorios\"</span>La falta de diligencia es leve; la carencia o falta de cumplimentación es grave."},{"i":"23-ia-1534","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Señale la conducta que constituye infracción MUY GRAVE del personal de seguridad privada:","o":["La falta de respeto al honor o a la dignidad de las personas.","La falta de diligencia en el cumplimiento de las respectivas funciones, sin perjuicio de lo previsto en la normativa vigente.","El trato incorrecto o desconsiderado con los ciudadanos.","El ejercicio de funciones de seguridad privada para terceros careciendo de la habilitación o acreditación necesaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El ejercicio de funciones de seguridad privada para terceros careciendo de la habilitación o acreditación necesaria</mark></span><span class=\"ref-norma\">Art.  58.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El ejercicio de funciones de seguridad privada para terceros careciendo de la habilitación o acreditación necesaria\"</span>Sin habilitación o acreditación es muy grave."},{"i":"23-ia-1535","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción muy grave del personal de seguridad privada la negativa a identificarse profesionalmente, en el ejercicio de sus funciones, ante:","o":["los ciudadanos, cuando fueren requeridos para ello.","los usuarios del servicio, cuando fueren requeridos para ello, en los términos que se determinen reglamentariamente.","la Autoridad o sus agentes, cuando fueren requeridos para ello.","los jefes de seguridad, cuando fueren requeridos para ello."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Autoridad o sus agentes, cuando fueren requeridos para ello</mark></span><span class=\"ref-norma\">Art.  58.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La negativa a identificarse profesionalmente, en el ejercicio de sus respectivas funciones, ante la Autoridad o sus agentes, cuando fueren requeridos para ello\"</span>Ante la Autoridad o sus agentes es muy grave; ante ciudadanos es grave."},{"i":"23-ia-1536","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción muy grave del personal de seguridad privada:","o":["la omisión de datos obligatorios en el informe de investigación.","la realización de investigaciones sobre delitos perseguibles de oficio o la falta de denuncia a la autoridad competente de los delitos que conozcan los detectives privados en el ejercicio de sus funciones.","la realización de investigaciones sin interés legítimo del solicitante, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","la elaboración de informes de investigación fuera de plazo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la realización de investigaciones sobre delitos perseguibles de oficio o la falta de denuncia a la autoridad competente de los delitos que conozcan los detectives privados en el ejercicio de sus funciones</mark></span><span class=\"ref-norma\">Art.  58.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La realización de investigaciones sobre delitos perseguibles de oficio o la falta de denuncia a la autoridad competente de los delitos que conozcan los detectives privados en el ejercicio de sus funciones\"</span>Investigar delitos perseguibles de oficio o no denunciarlos es muy grave."},{"i":"23-ia-1537","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción muy grave del personal de seguridad privada el abandono o la omisión injustificados del servicio:","o":["dentro de la jornada laboral establecida.","durante más de una hora.","sin comunicarlo al jefe de seguridad, en los términos que se determinen reglamentariamente.","en servicios con armas de fuego."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dentro de la jornada laboral establecida</mark></span><span class=\"ref-norma\">Art.  58.1.j · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El abandono o la omisión injustificados del servicio por parte del personal de seguridad privada, dentro de la jornada laboral establecida\"</span>Dentro de la jornada laboral establecida."},{"i":"23-ia-1538","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción muy grave del personal de seguridad privada la no realización del informe de investigación que preceptivamente deben elaborar los detectives privados o su no entrega al contratante del servicio, o:","o":["la entrega del informe fuera de plazo.","la omisión parcial de datos en el informe.","la conservación indebida de copias del informe.","la elaboración de informes paralelos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la elaboración de informes paralelos</mark></span><span class=\"ref-norma\">Art.  58.1.l · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o la elaboración de informes paralelos\"</span>También la elaboración de informes paralelos."},{"i":"23-ia-1539","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción grave del personal de seguridad privada:","o":["el ejercicio de funciones de seguridad privada careciendo de habilitación, salvo que la autoridad judicial disponga otra cosa.","el ejercicio abusivo de sus funciones en relación con los ciudadanos.","la realización de funciones de seguridad privada que excedan de la habilitación obtenida.","la negativa a prestar auxilio a las Fuerzas y Cuerpos de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la realización de funciones de seguridad privada que excedan de la habilitación obtenida</mark></span><span class=\"ref-norma\">Art.  58.2.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La realización de funciones de seguridad privada que excedan de la habilitación obtenida\"</span>Exceder la habilitación es grave."},{"i":"23-ia-1540","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción grave del personal de seguridad privada la no identificación profesional, en el ejercicio de sus funciones, cuando fueren requeridos para ello por:","o":["la Autoridad o sus agentes.","los ciudadanos.","los jueces y tribunales.","las Fuerzas y Cuerpos de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los ciudadanos</mark></span><span class=\"ref-norma\">Art.  58.2.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La no identificación profesional, en el ejercicio de sus respectivas funciones, cuando fueren requeridos para ello por los ciudadanos\"</span>Por los ciudadanos."},{"i":"23-ia-1541","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción grave del personal de seguridad privada:","o":["la retención de la documentación personal en contra de lo previsto para los controles de identidad de los vigilantes.","la negativa a facilitar el acceso a las instalaciones.","la falta de actualización de los datos personales.","la retención del arma reglamentaria fuera del servicio, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la retención de la documentación personal en contra de lo previsto para los controles de identidad de los vigilantes</mark></span><span class=\"ref-norma\">Art.  58.2.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La retención de la documentación personal en contra de lo previsto en el artículo 32.1.b)\"</span>Retener la documentación personal es grave."},{"i":"23-ia-1542","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción grave del personal de seguridad privada:","o":["la falta de uniformidad en el servicio.","la omisión de la tarjeta de identidad profesional.","el incumplimiento de las normas de tenencia de armas, en los términos que se determinen reglamentariamente.","la negativa a realizar los cursos de formación permanente a los que vienen obligados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la negativa a realizar los cursos de formación permanente a los que vienen obligados</mark></span><span class=\"ref-norma\">Art.  58.2.i · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La negativa a realizar los cursos de formación permanente a los que vienen obligados\"</span>La negativa a los cursos de formación permanente es grave."},{"i":"23-ia-1543","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones del personal. Constituye infracción leve del personal de seguridad privada:","o":["la falta de respeto al honor o a la dignidad de las personas.","la falta de diligencia en el cumplimiento de las funciones.","el trato incorrecto o desconsiderado con los ciudadanos.","la negativa a identificarse ante los ciudadanos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el trato incorrecto o desconsiderado con los ciudadanos</mark></span><span class=\"ref-norma\">Art.  58.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El trato incorrecto o desconsiderado con los ciudadanos\"</span>El trato incorrecto o desconsiderado es leve."},{"i":"23-ia-1544","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de los usuarios y centros de formación. Constituye infracción muy grave de los usuarios de servicios de seguridad privada:","o":["el anormal funcionamiento de las medidas de seguridad obligatorias adoptadas, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","la contratación o utilización a sabiendas de los servicios de empresas de seguridad o despachos de detectives carentes de la autorización específica o declaración responsable.","la utilización de aparatos de alarma no homologados.","el incumplimiento de las revisiones preceptivas de los sistemas obligatorios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la contratación o utilización a sabiendas de los servicios de empresas de seguridad o despachos de detectives carentes de la autorización específica o declaración responsable</mark></span><span class=\"ref-norma\">Art.  59.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La contratación o utilización a sabiendas de los servicios de empresas de seguridad o despachos de detectives carentes de la autorización específica o declaración responsable\"</span>Contratar a sabiendas sin autorización o declaración responsable es muy grave."},{"i":"23-ia-1545","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de los usuarios y centros de formación. Constituye infracción muy grave la entrada en funcionamiento, sin previa autorización, de:","o":["centrales receptoras de alarmas de uso propio por parte de entidades públicas o privadas.","centrales receptoras de alarmas ajenas por empresas de seguridad, sin perjuicio de lo previsto en la normativa vigente.","centros de formación sin declaración responsable.","despachos de detectives sin habilitación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">centrales receptoras de alarmas de uso propio por parte de entidades públicas o privadas</mark></span><span class=\"ref-norma\">Art.  59.1.j · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La entrada en funcionamiento, sin previa autorización, de centrales receptoras de alarmas de uso propio por parte de entidades públicas o privadas\"</span>Centrales receptoras de alarmas de uso propio."},{"i":"23-ia-1546","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de los usuarios y centros de formación. Constituye infracción grave de los usuarios de seguridad privada el incumplimiento de la obligación de situar al frente de la seguridad integral de la entidad, empresa o grupo empresarial a:","o":["un jefe de seguridad habilitado.","un responsable de seguridad designado por la autoridad, en los términos que se determinen reglamentariamente.","un vigilante de seguridad de empresa.","un director de seguridad, en contra de lo previsto en la ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un director de seguridad, en contra de lo previsto en la ley</mark></span><span class=\"ref-norma\">Art.  59.2.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El incumplimiento, por parte de los usuarios de seguridad privada, de la obligación de situar al frente de la seguridad integral de la entidad, empresa o grupo empresarial a un director de seguridad\"</span>Es grave no situar a un director de seguridad."},{"i":"23-ia-1547","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de los usuarios y centros de formación. Constituye infracción grave de los centros de formación:","o":["impartir cursos sin haber presentado la declaración responsable.","la falta de adecuación de los cursos a lo previsto reglamentariamente en cuanto a duración y contenido, salvo que la autoridad judicial disponga otra cosa.","la impartición de los cursos de formación fuera de las instalaciones autorizadas de los centros de formación.","la utilización de personal docente carente de acreditación en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la impartición de los cursos de formación fuera de las instalaciones autorizadas de los centros de formación</mark></span><span class=\"ref-norma\">Art.  59.2.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La impartición de los cursos de formación fuera de las instalaciones autorizadas de los centros de formación\"</span>Impartir cursos fuera de las instalaciones autorizadas es grave."},{"i":"23-ia-1548","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Infracciones de los usuarios y centros de formación. Constituye infracción leve de los usuarios de seguridad privada:","o":["el anormal funcionamiento de las medidas obligatorias cuando ocasionen perjuicios a la seguridad pública.","el anormal funcionamiento de las medidas o sistemas de seguridad que se tengan instalados.","el incumplimiento de las revisiones preceptivas.","la utilización de aparatos de alarma no homologados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el anormal funcionamiento de las medidas o sistemas de seguridad que se tengan instalados</mark></span><span class=\"ref-norma\">Art.  59.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El anormal funcionamiento de las medidas o sistemas de seguridad que se tengan instalados\"</span>El anormal funcionamiento sin perjuicios a terceros es leve."}]},{"a":"Artículo 39","q":[{"i":"23-5","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Forma de prestación de los servicios de seguridad privada. Señale la opción incorrecta.","o":["Los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada deberán estar homologados por el Ministerio del Interior.","En todo caso, los vehículos, uniformes y distintivos utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada no podrán inducir a confusión con los de las Fuerzas y Cuerpos de Seguridad, ni con los de las Fuerzas Armadas.","Previo el otorgamiento de las correspondientes licencias, se desarrollarán con armas de fuego los servicios de seguridad privada que se determinen por ley.","Los vehículos, uniformes y distintivos utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada se ajustarán a las características que reglamentariamente se determinen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Previo el otorgamiento de las correspondientes licencias, se desarrollarán con armas de fuego los servicios de seguridad privada que se determinen por ley</mark></span><span class=\"ref-norma\">Art. 39 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Previo el otorgamiento de las correspondientes licencias, sólo se desarrollarán con armas de fuego los servicios de seguridad privada contemplados en el artículo 40 y los que reglamentariamente se determinen.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-29","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes opciones sobre la forma de prestación de los servicios de seguridad privada es incorrecta?","o":["Las armas adecuadas para realizar los servicios de seguridad se podrán portar en todo momento, dentro y fuera de servicio, sin excepciones.","El personal de seguridad privada, durante la prestación de los servicios de seguridad privada, portará la tarjeta de identidad profesional y, en su caso, la documentación correspondiente al arma de fuego.","Las armas adecuadas para realizar los servicios de seguridad sólo se podrán portar estando de servicio, con las salvedades que se establezcan reglamentariamente.","En todo caso, los vehículos, uniformes y distintivos no podrán inducir a confusión con los de las Fuerzas y Cuerpos de Seguridad, ni con los de las Fuerzas Armadas, y se ajustarán a las características que reglamentariamente se determinen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las armas adecuadas para realizar los servicios de seguridad se podrán portar en todo momento, dentro y fuera de servicio, sin excepciones</mark></span><span class=\"ref-norma\">Art. 39 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las armas adecuadas para realizar los servicios de seguridad sólo se podrán portar estando de servicio, con las salvedades que se establezcan reglamentariamente.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-31","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Por quién deberán estar homologados los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada?","o":["Por el Ministerio de Defensa.","Por el régimen autonómico que sea competente.","Por el Ministerio del Interior.","Todas las opciones anteriores son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por el Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 39 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada deberán estar homologados por el Ministerio del Interior.\"</span>"},{"i":"23-80","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Por quién deberán estar homologados los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada?","o":["Por el Ministerio de Defensa.","Por el órgano autonómico que sea competente.","Por el Ministerio del Interior.","Por el Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por el Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 39 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada deberán estar homologados por el Ministerio del Interior.\"</span>"},{"i":"23-132","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada deberán estar homologados por:","o":["La Dirección General de Seguridad.","El Ministerio del Interior.","La Dirección General de la Policía.","La Dirección General de la Guardia Civil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 39 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada deberán estar homologados por el Ministerio del Interior.\"</span>"},{"i":"23-ia-1352","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Forma de prestación. Los medios utilizados por las empresas de seguridad en la prestación de los servicios de seguridad privada deberán estar homologados por el Ministerio del Interior. En todo caso, los vehículos, uniformes y distintivos no podrán inducir a confusión con:","o":["los de las Fuerzas y Cuerpos de Seguridad, ni con los de otras empresas de seguridad.","los de las Fuerzas y Cuerpos de Seguridad, ni con los de las Fuerzas Armadas.","los de las policías locales y la Guardia Civil.","los de los servicios de emergencias y protección civil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los de las Fuerzas y Cuerpos de Seguridad, ni con los de las Fuerzas Armadas</mark></span><span class=\"ref-norma\">Art.  39.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no podrán inducir a confusión con los de las Fuerzas y Cuerpos de Seguridad, ni con los de las Fuerzas Armadas\"</span>No pueden confundirse con los de las Fuerzas y Cuerpos de Seguridad ni con los de las Fuerzas Armadas."},{"i":"23-ia-1353","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Forma de prestación. El personal de seguridad privada uniformado, constituido por los vigilantes de seguridad y de explosivos y por los guardas rurales y sus especialidades, prestará sus servicios vistiendo el uniforme y ostentando el distintivo del cargo, y portando los medios de defensa reglamentarios, que:","o":["no incluirán armas de fuego.","podrán incluir armas de fuego en servicios de transporte.","incluirán armas de fuego en todo caso.","no incluirán armas de fuego ni defensas extensibles."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no incluirán armas de fuego</mark></span><span class=\"ref-norma\">Art.  39.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"portando los medios de defensa reglamentarios, que no incluirán armas de fuego\"</span>Los medios de defensa reglamentarios no incluyen armas de fuego."},{"i":"23-ia-1354","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Forma de prestación. Las armas adecuadas para realizar los servicios de seguridad sólo se podrán portar:","o":["estando de servicio, sin excepción alguna.","durante el servicio y en los trayectos de ida y vuelta al domicilio.","con licencia, aun fuera del servicio, con las salvedades reglamentarias, en los términos que se determinen reglamentariamente.","estando de servicio, con las salvedades que se establezcan reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">estando de servicio, con las salvedades que se establezcan reglamentariamente</mark></span><span class=\"ref-norma\">Art.  39.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las armas adecuadas para realizar los servicios de seguridad sólo se podrán portar estando de servicio, con las salvedades que se establezcan reglamentariamente\"</span>Solo en servicio, con las salvedades reglamentarias."},{"i":"23-ia-1355","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Forma de prestación. Salvo en los casos expresamente previstos en la ley y lo que se determine reglamentariamente, los vigilantes de seguridad ejercerán sus funciones:","o":["en el interior y en las inmediaciones de los inmuebles que vigilen, salvo que la autoridad judicial disponga otra cosa.","en el interior de los inmuebles y en las vías públicas adyacentes.","en el interior de los inmuebles o de las propiedades de cuya vigilancia estuvieran encargados.","en cualquier lugar donde presten servicio por orden de la empresa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en el interior de los inmuebles o de las propiedades de cuya vigilancia estuvieran encargados</mark></span><span class=\"ref-norma\">Art.  39.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"los vigilantes de seguridad ejercerán sus funciones en el interior de los inmuebles o de las propiedades de cuya vigilancia estuvieran encargados\"</span>En el interior de los inmuebles o propiedades que vigilen."},{"i":"23-ia-1356","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Forma de prestación. El personal de seguridad privada, durante la prestación de los servicios, portará:","o":["la tarjeta de identidad profesional y el contrato de trabajo.","la tarjeta de identidad profesional y, en su caso, la documentación correspondiente al arma de fuego.","la habilitación del Ministerio del Interior y la licencia de armas, en todo caso, previo informe de la unidad policial competente.","el documento nacional de identidad y la tarjeta de identidad profesional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la tarjeta de identidad profesional y, en su caso, la documentación correspondiente al arma de fuego</mark></span><span class=\"ref-norma\">Art.  39.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"portará la tarjeta de identidad profesional y, en su caso, la documentación correspondiente al arma de fuego\"</span>Tarjeta de identidad profesional y, en su caso, documentación del arma de fuego."}]},{"a":"Artículo 42","q":[{"i":"23-10","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Qué nombre reciben los servicios que consisten en el ejercicio de la vigilancia a través de sistemas de cámaras o videocámaras, fijas o móviles, capaces de captar y grabar imágenes y sonidos, incluido cualquier medio técnico o sistema que permita los mismos tratamientos que éstas?","o":["Servicios de operación.","Servicios de videovigilancia.","Servicios de seguridad.","Servicios de movimentación de cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Servicios de videovigilancia</mark></span><span class=\"ref-norma\">Art. 42 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Servicios de videovigilancia.\"</span>"},{"i":"23-51","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sobre los servicios de videovigilancia: señale la INCORRECTA.","o":["En ningún caso, se podrán utilizar cámaras o videocámaras con fines de seguridad privada para tomar imágenes y sonidos de vías y espacios públicos o de acceso público.","Los servicios de videovigilancia consisten en el ejercicio de la vigilancia a través de sistemas de cámaras o videocámaras, fijas o móviles, capaces de captar y grabar imágenes y sonidos, incluido cualquier medio técnico o sistema que permita los mismos tratamientos que éstas.","No tendrán la consideración de servicio de videovigilancia la utilización de cámaras o videocámaras cuyo objeto principal sea la comprobación del estado de instalaciones o bienes, el control de accesos a aparcamientos y garajes o las actividades que se desarrollan desde los centros de control y otros puntos, zonas o áreas de las autopistas de peaje.","Cuando la finalidad de estas actuaciones sea prevenir infracciones y evitar daños a las personas o bienes objeto de protección o impedir accesos o intrusiones, serán prestados necesariamente por vigilantes de seguridad o, en su caso, por guardas rurales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En ningún caso, se podrán utilizar cámaras o videocámaras con fines de seguridad privada para tomar imágenes y sonidos de vías y espacios públicos o de acceso público</mark></span><span class=\"ref-norma\">Art. 42 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No se podrán utilizar cámaras o videocámaras con fines de seguridad privada para tomar imágenes y sonidos de vías y espacios públicos o de acceso público salvo en los supuestos y en los términos y condiciones previstos en su normativa específica, previa autorización administrativa por el órgano competente en cada caso.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1412","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. Cuando la finalidad de los servicios de videovigilancia sea prevenir infracciones y evitar daños a las personas o bienes objeto de protección o impedir accesos no autorizados, serán prestados necesariamente por:","o":["operadores de seguridad exclusivamente.","vigilantes de seguridad o, en su caso, por guardas rurales.","vigilantes de seguridad, con exclusión de los guardas rurales.","vigilantes de seguridad o por operadores de seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">vigilantes de seguridad o, en su caso, por guardas rurales</mark></span><span class=\"ref-norma\">Art.  42.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"serán prestados necesariamente por vigilantes de seguridad o, en su caso, por guardas rurales\"</span>Los presta un vigilante de seguridad o, en su caso, un guarda rural."},{"i":"23-ia-1413","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. No tendrá la consideración de servicio de videovigilancia la utilización de cámaras cuyo objeto principal sea la comprobación del estado de instalaciones o bienes, el control de accesos a aparcamientos y garajes, o las actividades que se desarrollan desde los centros de control de las autopistas de peaje. Estas funciones podrán realizarse por:","o":["personal distinto del de seguridad privada.","personal habilitado como operador de seguridad.","personal de seguridad privada, con autorización previa.","personal de las empresas de seguridad con declaración responsable."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">personal distinto del de seguridad privada</mark></span><span class=\"ref-norma\">Art.  42.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Estas funciones podrán realizarse por personal distinto del de seguridad privada\"</span>Puede hacerlo personal distinto del de seguridad privada."},{"i":"23-ia-1414","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. No se podrán utilizar cámaras o videocámaras con fines de seguridad privada para tomar imágenes y sonidos de vías y espacios públicos o de acceso público salvo en los supuestos y en los términos previstos en su normativa específica, previa autorización administrativa. Su utilización en el interior de los domicilios requerirá:","o":["autorización judicial.","la comunicación a las Fuerzas y Cuerpos de Seguridad.","autorización del órgano competente y consentimiento del titular.","el consentimiento del titular."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el consentimiento del titular</mark></span><span class=\"ref-norma\">Art.  42.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Su utilización en el interior de los domicilios requerirá el consentimiento del titular\"</span>Requiere el consentimiento del titular."},{"i":"23-ia-1415","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. Las cámaras de videovigilancia que formen parte de medidas de seguridad obligatorias o de sistemas de recepción, verificación y, en su caso, respuesta y transmisión de alarmas:","o":["requerirán autorización administrativa para su instalación.","requerirán comunicación previa a las Fuerzas y Cuerpos de Seguridad, salvo que la autoridad judicial disponga otra cosa.","no requerirán autorización administrativa para su instalación, empleo o utilización.","solo requerirán autorización si captan vías públicas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no requerirán autorización administrativa para su instalación, empleo o utilización</mark></span><span class=\"ref-norma\">Art.  42.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no requerirán autorización administrativa para su instalación, empleo o utilización\"</span>No requieren autorización administrativa."},{"i":"23-ia-1416","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. Las grabaciones realizadas por los sistemas de videovigilancia no podrán destinarse a un uso distinto del de su finalidad. Cuando se encuentren relacionadas con hechos delictivos o que afecten a la seguridad ciudadana, se aportarán:","o":["a requerimiento de la autoridad judicial exclusivamente.","de propia iniciativa o a su requerimiento, a las Fuerzas y Cuerpos de Seguridad competentes.","en el plazo de setenta y dos horas, a las Fuerzas y Cuerpos de Seguridad, previo informe de la unidad policial competente.","a las Fuerzas y Cuerpos de Seguridad, solo previo requerimiento escrito."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de propia iniciativa o a su requerimiento, a las Fuerzas y Cuerpos de Seguridad competentes</mark></span><span class=\"ref-norma\">Art.  42.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se aportarán, de propia iniciativa o a su requerimiento, a las Fuerzas y Cuerpos de Seguridad competentes\"</span>De propia iniciativa o a requerimiento de las Fuerzas y Cuerpos de Seguridad."},{"i":"23-ia-1417","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. La monitorización, grabación, tratamiento y registro de imágenes y sonidos por parte de los sistemas de videovigilancia estará sometida a la normativa de protección de datos, y especialmente a los principios de:","o":["proporcionalidad, idoneidad e intervención mínima.","necesidad, proporcionalidad y minimización, sin perjuicio de lo previsto en la normativa vigente.","legalidad, proporcionalidad y reserva.","idoneidad, necesidad e intervención mínima."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">proporcionalidad, idoneidad e intervención mínima</mark></span><span class=\"ref-norma\">Art.  42.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"especialmente a los principios de proporcionalidad, idoneidad e intervención mínima\"</span>Proporcionalidad, idoneidad e intervención mínima."}]},{"a":"Artículo 46","q":[{"i":"23-11","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las empresas de seguridad encargadas de la prestación de las medidas de seguridad que les sean contratadas, ¿de qué serán responsables?","o":["De su correcta instalación, mantenimiento y funcionamiento.","De su correcta adopción, instalación y mantenimiento.","De su correcta instalación, adopción y funcionamiento.","De su correcta adopción, funcionamiento y mantenimiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De su correcta instalación, mantenimiento y funcionamiento</mark></span><span class=\"ref-norma\">Art. 46 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Servicios de instalación y mantenimiento.\"</span>"},{"i":"23-15","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los servicios de instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas, centros de control o de videovigilancia, consistirán en la ejecución, por ______ de todas aquellas operaciones de instalación y mantenimiento de dichos aparatos, equipos, dispositivos o sistemas, que resulten necesarias para su correcto funcionamiento y el buen cumplimiento de su finalidad, previa elaboración, por ______ del preceptivo proyecto de instalación, cuyas características se determinarán reglamentariamente.","o":["Técnicos acreditados / técnicos acreditados.","Técnicos acreditados / ingenieros acreditados.","Ingenieros acreditados / técnicos acreditados.","Ingenieros acreditados / ingenieros acreditados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Técnicos acreditados / ingenieros acreditados</mark></span><span class=\"ref-norma\">Disposición transitoria tercera · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Ingenieros y técnicos de las empresas de seguridad.\"</span>"},{"i":"23-25","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los servicios de instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas, centros de control o de videovigilancia, deberán someterse a revisiones preventivas con la periodicidad y forma que se determine:","o":["Reglamentariamente.","Por orden ministerial.","Por real decreto.","Por ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span><span class=\"ref-norma\">Art. 5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"f) La instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia.\"</span>"},{"i":"23-ia-1423","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de instalación y mantenimiento. Los servicios de instalación y mantenimiento de sistemas de seguridad conectados a centrales receptoras de alarmas consistirán en la ejecución, por técnicos acreditados, de las operaciones necesarias, previa elaboración, por ingenieros acreditados, del preceptivo:","o":["informe de viabilidad, cuyo contenido fijará el Ministerio del Interior.","estudio de riesgos, que se comunicará a las Fuerzas y Cuerpos de Seguridad, en los términos que se determinen reglamentariamente.","proyecto de instalación, cuyas características se determinarán reglamentariamente.","plan de seguridad, que se inscribirá en el Registro Nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">proyecto de instalación, cuyas características se determinarán reglamentariamente</mark></span><span class=\"ref-norma\">Art.  46.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"previa elaboración, por ingenieros acreditados, del preceptivo proyecto de instalación, cuyas características se determinarán reglamentariamente\"</span>Proyecto de instalación elaborado por ingenieros acreditados."},{"i":"23-ia-1424","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de instalación y mantenimiento. Los sistemas de seguridad conectados a centrales receptoras de alarmas deberán someterse a:","o":["inspecciones anuales por las Fuerzas y Cuerpos de Seguridad, salvo que la autoridad judicial disponga otra cosa.","revisiones preventivas con la periodicidad y forma que se determine reglamentariamente.","revisiones obligatorias cada dos años.","certificación de organismos acreditados cada cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">revisiones preventivas con la periodicidad y forma que se determine reglamentariamente</mark></span><span class=\"ref-norma\">Art.  46.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Estos sistemas deberán someterse a revisiones preventivas con la periodicidad y forma que se determine reglamentariamente\"</span>Revisiones preventivas con la periodicidad reglamentaria."}]},{"a":"Artículo 41","q":[{"i":"23-13","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los servicios de vigilancia y protección de bienes, establecimientos, lugares y eventos, tanto públicos como privados, podrán prestarse fuera de los edificios, de las instalaciones o propiedades a proteger sin necesidad de autorización previa, incluso en vías o espacios públicos o de uso común, en los siguientes supuestos: Señale la opción incorrecta.","o":["La vigilancia y protección sobre acciones de manipulación o utilización de bienes, maquinaria o equipos valiosos que hayan de tener lugar en las vías o espacios públicos o de uso común.","La retirada y reposición de fondos en cajeros automáticos, así como la prestación de servicios de vigilancia y protección de los mismos durante las citadas operaciones, o en las de reparación de averías.","Los desplazamientos al exterior de los inmuebles objeto de protección para la realización de actividades indirectamente relacionadas con las funciones de vigilancia y seguridad de dichos inmuebles.","La vigilancia y protección de los medios de transporte y de sus infraestructuras."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los desplazamientos al exterior de los inmuebles objeto de protección para la realización de actividades indirectamente relacionadas con las funciones de vigilancia y seguridad de dichos inmuebles</mark></span><span class=\"ref-norma\">Art. 41 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"c) Los desplazamientos al exterior de los inmuebles objeto de protección para la realización de actividades directamente relacionadas con las funciones de vigilancia y seguridad de dichos inmuebles.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-30","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de los siguientes servicios de vigilancia y protección podrán desarrollarse por guardas rurales?","o":["La vigilancia de estos servicios o instalaciones de organismos públicos.","La vigilancia perimetral de centros penitenciarios.","La vigilancia perimetral de centros de internamiento de extranjeros.","La participación en la prestación de servicios encomendados a la seguridad pública, complementando la acción policial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La participación en la prestación de servicios encomendados a la seguridad pública, complementando la acción policial</mark></span><span class=\"ref-norma\">Art. 41 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) La participación en la prestación de servicios encomendados a la seguridad pública, complementando la acción policial.\"</span>"},{"i":"23-34","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los servicios de vigilancia y protección de bienes, establecimientos, lugares y eventos, tanto públicos como privados, podrán prestarse fuera de los edificios, de las instalaciones o propiedades a proteger sin necesidad de autorización previa, incluso en vías o espacios públicos o de uso común, en los siguientes supuestos: Señale la opción incorrecta.","o":["La operación de datos de vigilancia estructurada, consistentes en la visita intermitente y programada a los diferentes puestos de vigilancia establecidos o a los distintos lugares objeto de protección.","Las situaciones en que ello viniera exigido por razones humanitarias.","La persecución de quienes sean sorprendidos en flagrante delito, en relación con las personas o bienes objeto de su vigilancia y protección.","La vigilancia y protección sobre acciones de manipulación o utilización de bienes, maquinaria o equipos valiosos que hayan de tener lugar en las vías o espacios públicos o de uso común."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La operación de datos de vigilancia estructurada, consistentes en la visita intermitente y programada a los diferentes puestos de vigilancia establecidos o a los distintos lugares objeto de protección</mark></span><span class=\"ref-norma\">Art. 41 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"e) Los servicios de ronda o de vigilancia discontinua, consistentes en la visita intermitente y programada a los diferentes puestos de vigilancia establecidos o a los distintos lugares objeto de protección.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-60","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Requerirán autorización previa por parte del órgano competente los siguientes servicios de vigilancia y protección, que se prestarán en coordinación, cuando proceda, con las Fuerzas y Cuerpos de Seguridad, y de acuerdo con sus instrucciones: señale la INCORRECTA:","o":["La vigilancia en polígonos industriales y urbanizaciones delimitados, incluidas sus vías o espacios de uso común.","La vigilancia en complejos o parques comerciales y de ocio que se encuentren delimitados.","La vigilancia en acontecimientos culturales, deportivos o cualquier otro evento de interés social que se desarrolle en vías o espacios privados, en coordinación, en su caso, con las Fuerzas y Cuerpos de Seguridad.","La vigilancia y protección en recintos y espacios abiertos que se encuentren delimitados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La vigilancia en acontecimientos culturales, deportivos o cualquier otro evento de interés social que se desarrolle en vías o espacios privados, en coordinación, en su caso, con las Fuerzas y Cuerpos de Seguridad</mark></span><span class=\"ref-norma\">Art. 41 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"c) La vigilancia en acontecimientos culturales, deportivos o cualquier otro evento de relevancia social que se desarrolle en vías o espacios públicos o de uso común, en coordinación, en todo caso, con las Fuerzas y Cuerpos de Seguridad.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-83","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Requerirán autorización previa por parte del órgano competente los siguientes servicios de vigilancia y protección, que se prestarán en coordinación, cuando proceda, con las Fuerzas y Cuerpos de Seguridad, y de acuerdo con sus instrucciones: señale la INCORRECTA.","o":["La vigilancia en polígonos industriales y urbanizaciones delimitados, incluidas sus vías o espacios de uso común.","La vigilancia en complejos o parques comerciales y de ocio que se encuentren delimitados.","La vigilancia en acontecimientos culturales, deportivos o cualquier otro evento de relevancia social que se desarrolle en vías o espacios públicos o de uso común, en coordinación, en su caso, con las Fuerzas y Cuerpos de Seguridad.","La vigilancia y protección en recintos y espacios abiertos que no se encuentren delimitados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La vigilancia y protección en recintos y espacios abiertos que no se encuentren delimitados</mark></span><span class=\"ref-norma\">Art. 41 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) La vigilancia y protección en recintos y espacios abiertos que se encuentren delimitados.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1406","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Los servicios de vigilancia y protección se prestarán por vigilantes de seguridad o, en su caso, por guardas rurales, que desempeñarán sus funciones, con carácter general, en el interior de los edificios, de las instalaciones o propiedades a proteger. No obstante, podrán prestarse fuera de estos espacios sin necesidad de autorización previa, incluso en vías o espacios públicos o de uso común, en determinados supuestos, como:","o":["la vigilancia en polígonos industriales y urbanizaciones delimitados.","la vigilancia en complejos o parques comerciales y de ocio delimitados.","la vigilancia en acontecimientos culturales o deportivos en vías públicas.","la retirada y reposición de fondos en cajeros automáticos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la retirada y reposición de fondos en cajeros automáticos</mark></span><span class=\"ref-norma\">Art.  41.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La retirada y reposición de fondos en cajeros automáticos, así como la prestación de servicios de vigilancia y protección de los mismos durante las citadas operaciones\"</span>Los cajeros no requieren autorización previa; los demás sí."},{"i":"23-ia-1407","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Los servicios de ronda o de vigilancia discontinua, que pueden prestarse fuera de los edificios sin autorización previa, consisten en:","o":["la vigilancia permanente de varios puestos desde un vehículo.","la visita aleatoria a los lugares objeto de protección, sin programación previa, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","la visita intermitente y programada a los diferentes puestos de vigilancia establecidos o a los distintos lugares objeto de protección.","la presencia continuada en el perímetro del inmueble protegido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la visita intermitente y programada a los diferentes puestos de vigilancia establecidos o a los distintos lugares objeto de protección</mark></span><span class=\"ref-norma\">Art.  41.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"consistentes en la visita intermitente y programada a los diferentes puestos de vigilancia establecidos o a los distintos lugares objeto de protección\"</span>Visita intermitente y programada."},{"i":"23-ia-1408","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Podrán prestarse fuera de los edificios sin autorización previa los servicios de vigilancia y protección consistentes en la persecución de quienes sean sorprendidos en flagrante delito:","o":["en las inmediaciones del inmueble objeto de su vigilancia.","en relación con las personas o bienes objeto de su vigilancia y protección.","en cualquier lugar, siempre que se avise a las Fuerzas y Cuerpos de Seguridad.","en relación con los bienes, pero no con las personas protegidas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en relación con las personas o bienes objeto de su vigilancia y protección</mark></span><span class=\"ref-norma\">Art.  41.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La persecución de quienes sean sorprendidos en flagrante delito, en relación con las personas o bienes objeto de su vigilancia y protección\"</span>En relación con las personas o bienes objeto de su vigilancia y protección."},{"i":"23-ia-1409","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Requerirán autorización previa por parte del órgano competente, entre otros, los servicios de vigilancia y protección en:","o":["polígonos industriales y urbanizaciones delimitados, incluidas sus vías o espacios de uso común.","las operaciones de retirada y reposición de fondos en cajeros, previo informe de la unidad policial competente.","los medios de transporte y sus infraestructuras.","los desplazamientos al exterior de los inmuebles protegidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">polígonos industriales y urbanizaciones delimitados, incluidas sus vías o espacios de uso común</mark></span><span class=\"ref-norma\">Art.  41.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La vigilancia en polígonos industriales y urbanizaciones delimitados, incluidas sus vías o espacios de uso común\"</span>Polígonos industriales y urbanizaciones delimitados."},{"i":"23-ia-1410","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. La vigilancia en acontecimientos culturales, deportivos o cualquier otro evento de relevancia social que se desarrolle en vías o espacios públicos o de uso común requiere autorización previa y se realizará:","o":["bajo el mando directo de las Fuerzas y Cuerpos de Seguridad, sin perjuicio de lo previsto en la normativa vigente.","previo informe de la Junta Local de Seguridad.","sin armas y con uniformidad reglamentaria.","en coordinación, en todo caso, con las Fuerzas y Cuerpos de Seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en coordinación, en todo caso, con las Fuerzas y Cuerpos de Seguridad</mark></span><span class=\"ref-norma\">Art.  41.2.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en coordinación, en todo caso, con las Fuerzas y Cuerpos de Seguridad\"</span>En coordinación, en todo caso, con las Fuerzas y Cuerpos de Seguridad."},{"i":"23-ia-1411","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de vigilancia y protección. Cuando así se decida por el órgano competente, y cumpliendo estrictamente las órdenes e instrucciones de las Fuerzas y Cuerpos de Seguridad, podrán prestarse, entre otros, los servicios de:","o":["vigilancia de polígonos industriales y complejos comerciales, en los términos que se determinen reglamentariamente.","protección de personas en vías públicas.","vigilancia perimetral de centros penitenciarios y de centros de internamiento de extranjeros.","videovigilancia en espacios públicos abiertos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">vigilancia perimetral de centros penitenciarios y de centros de internamiento de extranjeros</mark></span><span class=\"ref-norma\">Art.  41.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La vigilancia perimetral de centros penitenciarios. b) La vigilancia perimetral de centros de internamiento de extranjeros\"</span>Vigilancia perimetral de prisiones y centros de internamiento de extranjeros."}]},{"a":"Artículo 40","q":[{"i":"23-14","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cómo se determinarán aquellos supuestos en los que, valoradas circunstancias tales como localización, valor de los objetos a proteger, concentración del riesgo, peligrosidad, nocturnidad, zonas rústicas o cinegéticas, u otras de análoga significación, podrá autorizarse la prestación de los servicios de seguridad privada portando armas de fuego?","o":["Por ley.","Mediante real decreto.","Reglamentariamente.","Por orden ministerial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span><span class=\"ref-norma\">Art. 40 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Reglamentariamente se determinarán aquellos supuestos en los que, valoradas circunstancias tales como localización, valor de los objetos a proteger, concentración del riesgo, peligrosidad, nocturnidad, zonas rústicas o cinegéticas, u otras de análoga significación, podrá autorizarse la prestación de los servicios de seguridad privada portando armas de fuego.\"</span>"},{"i":"23-58","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios con armas de fuego. Los siguientes servicios de seguridad privada se prestarán con armas de fuego en los términos que reglamentariamente se determinen: señale la INCORRECTA:","o":["Los de vigilancia y protección del almacenamiento, recuento, clasificación y transporte de dinero, valores y objetos valiosos.","Los de vigilancia y protección de fábricas y depósitos o transporte de armas, cartuchería metálica y explosivos.","Los de vigilancia y protección de buques mercantes y buques pesqueros que naveguen bajo bandera española en aguas en las que exista grave riesgo para la seguridad de las personas o de los bienes.","Cuando por sus características y circunstancias lo requieran, los de vigilancia y protección personalizada en centros penitenciarios, centros de internamiento de extranjeros, establecimientos militares u otros edificios o instalaciones de organismos públicos, incluidas las infraestructuras críticas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando por sus características y circunstancias lo requieran, los de vigilancia y protección personalizada en centros penitenciarios, centros de internamiento de extranjeros, establecimientos militares u otros edificios o instalaciones de organismos públicos, incluidas las infraestructuras críticas</mark></span><span class=\"ref-norma\">Art. 40 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) Cuando por sus características y circunstancias lo requieran, los de vigilancia y protección perimetral en centros penitenciarios, centros de internamiento de extranjeros, establecimientos militares u otros edificios o instalaciones de organismos públicos, incluidas las infraestructuras críticas.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1401","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios con armas de fuego. Señale el servicio que NO se presta con armas de fuego en los términos que reglamentariamente se determinen:","o":["Los de vigilancia y protección de polígonos industriales y urbanizaciones delimitadas.","Los de vigilancia y protección del almacenamiento, recuento, clasificación y transporte de dinero, valores y objetos valiosos.","Los de vigilancia y protección de fábricas y depósitos o transporte de armas, cartuchería metálica y explosivos.","Los de vigilancia y protección en buques mercantes y buques pesqueros que naveguen bajo bandera española en aguas en las que exista grave riesgo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los de vigilancia y protección de polígonos industriales y urbanizaciones delimitadas</mark></span><span class=\"ref-norma\">Art.  40.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los de vigilancia y protección del almacenamiento, recuento, clasificación y transporte de dinero, valores y objetos valiosos\"</span>La vigilancia de polígonos industriales no figura entre los servicios con armas de fuego del precepto."},{"i":"23-ia-1402","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios con armas de fuego. Se prestarán con armas de fuego los servicios de vigilancia y protección en buques mercantes y buques pesqueros que naveguen bajo bandera española en aguas en las que exista:","o":["riesgo cierto de ataques piratas a la tripulación.","peligro de abordaje en alta mar.","grave riesgo para la navegación y para la tripulación, en los términos que se determinen reglamentariamente.","grave riesgo para la seguridad de las personas o de los bienes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">grave riesgo para la seguridad de las personas o de los bienes</mark></span><span class=\"ref-norma\">Art.  40.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en aguas en las que exista grave riesgo para la seguridad de las personas o de los bienes\"</span>Aguas con grave riesgo para la seguridad de las personas o de los bienes."},{"i":"23-ia-1403","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios con armas de fuego. Cuando por sus características y circunstancias lo requieran, se prestarán con armas de fuego los de vigilancia y protección perimetral en centros penitenciarios, centros de internamiento de extranjeros, establecimientos militares u otros edificios o instalaciones de organismos públicos, incluidas:","o":["las sedes de los órganos constitucionales.","las dependencias de las Fuerzas y Cuerpos de Seguridad.","las infraestructuras críticas.","las embajadas y consulados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las infraestructuras críticas</mark></span><span class=\"ref-norma\">Art.  40.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"incluidas las infraestructuras críticas\"</span>Incluidas las infraestructuras críticas."},{"i":"23-ia-1404","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios con armas de fuego. Podrá autorizarse la prestación de los servicios de verificación personal de alarmas portando armas de fuego, cuando sea necesario para garantizar:","o":["la protección de los bienes custodiados, atendiendo a su valor y a su ubicación, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","la seguridad del personal que los presta, atendiendo a la naturaleza de dicho servicio, al objeto de la protección o a otras circunstancias.","la seguridad de los usuarios y terceros, atendiendo a la peligrosidad del lugar.","la eficacia del servicio, atendiendo a la hora y a la zona de prestación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la seguridad del personal que los presta, atendiendo a la naturaleza de dicho servicio, al objeto de la protección o a otras circunstancias</mark></span><span class=\"ref-norma\">Art.  40.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando sea necesario para garantizar la seguridad del personal que los presta, atendiendo a la naturaleza de dicho servicio, al objeto de la protección o a otras circunstancias que incidan en aquélla\"</span>Para garantizar la seguridad del personal que presta el servicio."},{"i":"23-ia-1405","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios con armas de fuego. El personal de seguridad privada sólo podrá portar el arma de fuego cuando esté de servicio, y podrá acceder con ella al lugar donde se desarrolle éste, salvo que:","o":["legalmente se establezca lo contrario.","lo prohíba el titular del inmueble, sin perjuicio de lo previsto en la normativa vigente.","lo ordene el jefe de seguridad.","se trate de lugares públicos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">legalmente se establezca lo contrario</mark></span><span class=\"ref-norma\">Art.  40.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y podrá acceder con ella al lugar donde se desarrolle éste, salvo que legalmente se establezca lo contrario\"</span>Salvo que legalmente se establezca lo contrario."}]},{"a":"Artículo 64","q":[{"i":"23-16","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Para la graduación de las sanciones, los órganos competentes tendrán en cuenta:","o":["La gravedad y trascendencia del hecho.","El posible perjuicio para el interés público.","La situación de riesgo creada o mantenida para personas o bienes.","Todas las anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores son correctas</mark></span><span class=\"ref-norma\">Art. 64 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"los órganos competentes tendrán en cuenta la gravedad y trascendencia del hecho, el posible perjuicio para el interés público, la situación de riesgo creada o mantenida para personas o bienes, la reincidencia, la intencionalidad\"</span>"},{"i":"23-ia-1601","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Graduación de las sanciones. Para la graduación de las sanciones, los órganos competentes tendrán en cuenta la gravedad y trascendencia del hecho, el posible perjuicio para el interés público, la situación de riesgo creada o mantenida para personas o bienes, la reincidencia, la intencionalidad, el volumen de actividad de la empresa y:","o":["la capacidad económica del infractor.","la colaboración del infractor con la Administración.","el beneficio obtenido por el infractor.","el número de trabajadores del infractor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la capacidad económica del infractor</mark></span><span class=\"ref-norma\">Art.  64 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y la capacidad económica del infractor\"</span>Cierra la lista la capacidad económica del infractor."}]},{"a":"Artículo 52","q":[{"i":"23-17","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas de seguridad. ¿Cómo se denominan aquellas medidas, dirigidas a evitar o poner término a cualquier tipo de amenaza, peligro o ataque deliberado, mediante la disposición, programación o planificación de cometidos, funciones o tareas formalizadas o ejecutadas por personas?","o":["Medidas de seguridad preventiva.","Medidas de seguridad planificada.","Medidas de seguridad estructuradas.","Medidas de seguridad organizativas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Medidas de seguridad organizativas</mark></span><span class=\"ref-norma\">Art. 52.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"De seguridad organizativa, dirigidas a evitar o poner término a cualquier tipo de amenaza, peligro o ataque deliberado, mediante la disposición, programación o planificación de cometidos, funciones o tareas formalizadas o ejecutadas por personas\"</span>"},{"i":"23-24","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de control de las empresas, despachos de detectives, de sus servicios o actuaciones y de su personal y medios en materia de seguridad privada. Señale la opción incorrecta.","o":["Toda persona que tuviera conocimiento de irregularidades cometidas en el ámbito de la seguridad privada estará obligada a denunciarlas ante las autoridades o funcionarios competentes, a efectos del posible ejercicio de las actuaciones de control y sanción correspondiente.","En el ejercicio de las funciones de control, los miembros de las Fuerzas y Cuerpos de Seguridad competentes podrán requerir la información pertinente y adoptar las medidas provisionales que resulten necesarias.","Corresponde a las Fuerzas y Cuerpos de Seguridad competentes, en el ejercicio de las funciones de control de las empresas, despachos de detectives, de sus servicios o actuaciones y de su personal y medios en materia de seguridad privada, el cumplimiento de las órdenes e instrucciones que se impartan por los órganos a los que se refieren los artículos 12 y 13.","El acceso por los órganos que tengan atribuida la competencia de control se limitará a los datos necesarios para la realización de la misma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Toda persona que tuviera conocimiento de irregularidades cometidas en el ámbito de la seguridad privada estará obligada a denunciarlas ante las autoridades o funcionarios competentes, a efectos del posible ejercicio de las actuaciones de control y sanción correspondiente</mark></span><span class=\"ref-norma\">Art. 53 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Toda persona que tuviera conocimiento de irregularidades cometidas en el ámbito de la seguridad privada podrá denunciarlas ante las autoridades o funcionarios competentes, a efectos del posible ejercicio de las actuaciones de control y sanción correspondientes.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-27","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas de seguridad. ¿Cómo se regularán las características, elementos y finalidades de las medidas de seguridad de cualquier tipo, quien quiera que los utilice?","o":["Reglamentariamente.","Por ley.","Por real decreto.","Mediante orden ministerial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span><span class=\"ref-norma\">Art. 52 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las características, elementos y finalidades de las medidas de seguridad de cualquier tipo, quien quiera que los utilice, se regularán reglamentariamente de acuerdo con lo previsto, en cuanto a sus grados y características, en las normas que contienen especificaciones técnicas para una actividad o producto.\"</span>"},{"i":"23-48","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas de seguridad. ¿Cuáles son las medidas de seguridad física?","o":["Aquéllas cuya funcionalidad consiste en impedir o dificultar el acceso a determinados lugares o bienes mediante la interposición de cualquier tipo de barreras físicas.","Aquéllas orientadas a detectar o advertir cualquier tipo de amenaza, peligro, presencia o intento de asalto o intrusión que pudiera producirse, mediante la actuación de cualquier tipo de dispositivos electrónicos.","Aquéllas cuyo objeto es la protección y salvaguarda de la integridad, confidencialidad y disponibilidad de los sistemas de información y comunicación y de la información en ellos contenida.","Aquéllas dirigidas a evitar o poner término a cualquier tipo de amenaza, peligro o ataque deliberado, mediante la disposición, programación o planificación de cometidos, funciones o tareas formalizadas o ejecutadas por personas tales como la creación, existencia y funcionamiento de departamentos de seguridad o la elaboración y aplicación de todo tipo de planes de seguridad, así como cualesquiera otras de similar naturaleza que puedan adoptarse."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Aquéllas cuya funcionalidad consiste en impedir o dificultar el acceso a determinados lugares o bienes mediante la interposición de cualquier tipo de barreras físicas</mark></span><span class=\"ref-norma\">Art. 52 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) De seguridad física, cuya funcionalidad consiste en impedir o dificultar el acceso a determinados lugares o bienes mediante la interposición de cualquier tipo de barreras físicas.\"</span>"},{"i":"23-ia-1444","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas. Las medidas de seguridad cuya funcionalidad consiste en impedir o dificultar el acceso a determinados lugares o bienes mediante la interposición de cualquier tipo de barreras físicas son medidas de seguridad:","o":["electrónica.","física.","organizativa.","personal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">física</mark></span><span class=\"ref-norma\">Art.  52.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"De seguridad física, cuya funcionalidad consiste en impedir o dificultar el acceso a determinados lugares o bienes mediante la interposición de cualquier tipo de barreras físicas\"</span>Son las medidas de seguridad física."},{"i":"23-ia-1445","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas. Las medidas de seguridad orientadas a detectar o advertir cualquier tipo de amenaza, peligro, presencia o intento de asalto o intrusión, mediante la activación de cualquier tipo de dispositivos electrónicos son medidas de seguridad:","o":["electrónica.","física.","informática.","organizativa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">electrónica</mark></span><span class=\"ref-norma\">Art.  52.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"De seguridad electrónica, orientadas a detectar o advertir cualquier tipo de amenaza, peligro, presencia o intento de asalto o intrusión\"</span>Son medidas de seguridad electrónica."},{"i":"23-ia-1446","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas. Las medidas de seguridad informática tienen por objeto la protección y salvaguarda de:","o":["la confidencialidad, trazabilidad y disponibilidad de las redes y de los datos personales, en los términos que se determinen reglamentariamente.","la integridad, autenticidad y confidencialidad de la información de los usuarios.","la disponibilidad y trazabilidad de los sistemas de información y comunicación.","la integridad, confidencialidad y disponibilidad de los sistemas de información y comunicación, y de la información en ellos contenida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la integridad, confidencialidad y disponibilidad de los sistemas de información y comunicación, y de la información en ellos contenida</mark></span><span class=\"ref-norma\">Art.  52.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuyo objeto es la protección y salvaguarda de la integridad, confidencialidad y disponibilidad de los sistemas de información y comunicación, y de la información en ellos contenida\"</span>Integridad, confidencialidad y disponibilidad de los sistemas y de la información."},{"i":"23-ia-1447","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas. Las medidas de seguridad organizativa están dirigidas a evitar o poner término a cualquier tipo de amenaza, peligro o ataque deliberado, mediante la disposición, programación o planificación de cometidos, funciones o tareas formalizadas o ejecutadas por personas, tales como:","o":["la contratación de vigilantes de seguridad y la instalación de alarmas.","la formación del personal y la designación de un jefe de seguridad.","la creación, existencia y funcionamiento de departamentos de seguridad o la elaboración y aplicación de todo tipo de planes de seguridad.","la elaboración de protocolos de actuación y la contratación de auditorías, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la creación, existencia y funcionamiento de departamentos de seguridad o la elaboración y aplicación de todo tipo de planes de seguridad</mark></span><span class=\"ref-norma\">Art.  52.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"tales como la creación, existencia y funcionamiento de departamentos de seguridad o la elaboración y aplicación de todo tipo de planes de seguridad\"</span>Departamentos de seguridad y planes de seguridad."},{"i":"23-ia-1448","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Tipos de medidas. Las medidas de seguridad, medios materiales y sistemas de alarma deberán contar con la evaluación de los organismos de certificación acreditados en el momento de su instalación y tendrán vigencia indefinida, salvo:","o":["revisión negativa o modificación del inmueble protegido.","deterioro o instalación de un nuevo sistema, que deberá ser conforme a la homologación que le resulte aplicable.","deterioro o cambio de titularidad del establecimiento.","revocación de la homologación por el Ministerio del Interior, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">deterioro o instalación de un nuevo sistema, que deberá ser conforme a la homologación que le resulte aplicable</mark></span><span class=\"ref-norma\">Art.  52.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"tendrán vigencia indefinida, salvo deterioro o instalación de un nuevo sistema, que deberá ser conforme a la homologación que le resulte aplicable\"</span>Vigencia indefinida salvo deterioro o instalación de un nuevo sistema."},{"i":"23-ia-1449","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de control. Corresponde a las Fuerzas y Cuerpos de Seguridad competentes en el ejercicio de las funciones de control de las empresas, despachos de detectives, de sus servicios o actuaciones y de su personal y medios en materia de seguridad privada:","o":["el cumplimiento de las órdenes e instrucciones que se impartan por los órganos a los que se refieren los artículos sobre competencias de la Administración General del Estado y de las comunidades autónomas.","el cumplimiento de las instrucciones del Ministerio de Justicia en esta materia, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","la determinación de los planes de control y de los criterios de actuación.","la propuesta de las sanciones que correspondan a los infractores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el cumplimiento de las órdenes e instrucciones que se impartan por los órganos a los que se refieren los artículos sobre competencias de la Administración General del Estado y de las comunidades autónomas</mark></span><span class=\"ref-norma\">Art.  53.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"el cumplimiento de las órdenes e instrucciones que se impartan por los órganos a los que se refieren los artículos 12 y 13\"</span>Ejecutan las órdenes e instrucciones de los órganos competentes."},{"i":"23-ia-1450","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de control. Cuando en el ejercicio de las actuaciones de control se detectase la posible comisión de una infracción administrativa, se instará a la autoridad competente para la incoación del correspondiente procedimiento sancionador. Si se tratara de la posible comisión de un hecho delictivo, se pondrá:","o":["en el plazo de cuarenta y ocho horas a disposición del Ministerio Fiscal.","inmediatamente en conocimiento del Ministerio del Interior.","en conocimiento de la autoridad judicial una vez concluido el procedimiento administrativo.","inmediatamente en conocimiento de la autoridad judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">inmediatamente en conocimiento de la autoridad judicial</mark></span><span class=\"ref-norma\">Art.  53.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Si se tratara de la posible comisión de un hecho delictivo, se pondrá inmediatamente en conocimiento de la autoridad judicial\"</span>Inmediatamente a la autoridad judicial."},{"i":"23-ia-1451","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actuaciones de control. Toda persona que tuviera conocimiento de irregularidades cometidas en el ámbito de la seguridad privada podrá:","o":["comunicarlas a las empresas afectadas para su subsanación.","denunciarlas ante el Ministerio del Interior exclusivamente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","denunciarlas ante las autoridades o funcionarios competentes, a efectos del posible ejercicio de las actuaciones de control y sanción correspondientes.","denunciarlas solo si es usuario de seguridad privada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">denunciarlas ante las autoridades o funcionarios competentes, a efectos del posible ejercicio de las actuaciones de control y sanción correspondientes</mark></span><span class=\"ref-norma\">Art.  53.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrá denunciarlas ante las autoridades o funcionarios competentes, a efectos del posible ejercicio de las actuaciones de control y sanción correspondientes\"</span>Cualquier persona puede denunciar ante autoridades o funcionarios competentes."}]},{"a":"Artículo 49","q":[{"i":"23-18","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Qué se hará constar en los informes de investigación de los detectives privados?","o":["Información directamente relacionada con el objeto y finalidad de la investigación contratada.","Referencias, informaciones o datos que hayan podido averiguarse relativos al cliente o al sujeto investigado.","Los de carácter personal especialmente protegidos, que resulten necesarios o que no guarden directa relación con dicho objeto y finalidad ni con el interés legítimo alegado para la contratación.","Todas las opciones anteriores son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Información directamente relacionada con el objeto y finalidad de la investigación contratada</mark></span><span class=\"ref-norma\">Art. 49 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"En el informe de investigación únicamente se hará constar información directamente relacionada con el objeto y finalidad de la investigación contratada, sin incluir en él referencias, informaciones o datos que hayan podido averiguarse relativos al cliente o al sujeto investigado, en particular los de carácter personal especialmente protegidos, que no resulten necesarios o que no guarden directa relación con dicho objeto y finalidad ni con el interés legítimo alegado para la contratación.\"</span>"},{"i":"23-19","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación. ¿Qué se hará constar en el informe de investigación que elaboran los detectives privados?","o":["Únicamente información directamente relacionada con el objeto y finalidad de la investigación contratada.","Además, las referencias, informaciones o datos relativos al cliente o al sujeto investigado, aunque no guarden relación con el objeto de la investigación.","Los datos de carácter personal especialmente protegidos, aunque no guarden directa relación con dicho objeto y finalidad ni con el interés legítimo alegado.","Todas las opciones anteriores son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Únicamente información directamente relacionada con el objeto y finalidad de la investigación contratada</mark></span><span class=\"ref-norma\">Art. 49 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"En el informe de investigación únicamente se hará constar información directamente relacionada con el objeto y finalidad de la investigación contratada, sin incluir en él referencias, informaciones o datos que hayan podido averiguarse relativos al cliente o al sujeto investigado, en particular los de carácter personal especialmente protegidos, que no resulten necesarios o que no guarden directa relación con dicho objeto y finalidad ni con el interés legítimo alegado para la contratación.\"</span>"},{"i":"23-50","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación. ¿Cuánto tiempo deberán conservarse archivados los informes de investigación de los detectives privados?","o":["Al menos durante 2 años.","Al menos durante 3 años.","Al menos durante 5 años.","Al menos durante 4 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al menos durante 3 años</mark></span><span class=\"ref-norma\">Art. 49 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los informes de investigación deberán conservarse archivados, al menos, durante tres años, sin perjuicio de lo dispuesto en el artículo 16.3 de la Ley Orgánica 15/1999, de 13 de diciembre, de protección de datos de carácter personal.\"</span>"},{"i":"23-65","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación. Por cada servicio que les sea contratado, los despachos o los detectives privados encargados del asunto deberán elaborar un único informe en el que reflejarán: señale la INCORRECTA:","o":["El número de registro asignado al servicio.","Los detectives intervinientes.","Los datos de la persona que encarga y contrata el servicio.","El tiempo de inicio y fin de la investigación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El tiempo de inicio y fin de la investigación</mark></span><span class=\"ref-norma\">Art. 49.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"un único informe en el que reflejarán el número de registro asignado al servicio, los datos de la persona que encarga y contrata el servicio, el objeto de la contratación, los medios, los resultados, los detectives intervinientes y las actuaciones realizadas\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1434","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación. Por cada servicio que les sea contratado, los despachos o los detectives privados encargados del asunto deberán elaborar:","o":["un informe parcial cada mes y otro final.","un informe por cada detective interviniente.","un único informe, que se remitirá a las Fuerzas y Cuerpos de Seguridad, previo informe de la unidad policial competente.","un único informe, en las condiciones y plazos que reglamentariamente se establezcan."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un único informe, en las condiciones y plazos que reglamentariamente se establezcan</mark></span><span class=\"ref-norma\">Art.  49.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"deberán elaborar un único informe en el que reflejarán el número de registro asignado al servicio\"</span>Un único informe por servicio."},{"i":"23-ia-1435","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación. Los informes de investigación deberán conservarse archivados, al menos, durante tres años. Las imágenes y los sonidos grabados durante las investigaciones se destruirán:","o":["un año después de su finalización, salvo que el cliente solicite su conservación, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","cinco años después de su finalización, en todo caso.","tres años después de su finalización, salvo que estén relacionadas con un procedimiento judicial, una investigación policial o un procedimiento sancionador.","tres años después de la entrega del informe al cliente, en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">tres años después de su finalización, salvo que estén relacionadas con un procedimiento judicial, una investigación policial o un procedimiento sancionador</mark></span><span class=\"ref-norma\">Art.  49.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las imágenes y los sonidos grabados durante las investigaciones se destruirán tres años después de su finalización, salvo que estén relacionadas con un procedimiento judicial, una investigación policial o un procedimiento sancionador\"</span>Tres años tras su finalización, salvo procedimiento judicial, policial o sancionador."},{"i":"23-ia-1436","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Informes de investigación. Las investigaciones privadas tendrán carácter reservado y los datos obtenidos a través de las mismas solo se podrán poner a disposición del cliente o, en su caso, de los órganos judiciales y policiales, en este último supuesto únicamente para:","o":["una investigación judicial o para un procedimiento administrativo.","una investigación policial o para un procedimiento sancionador.","una investigación policial o para un procedimiento judicial.","la prevención de delitos o para un procedimiento sancionador."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una investigación policial o para un procedimiento sancionador</mark></span><span class=\"ref-norma\">Art.  49.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en este último supuesto únicamente para una investigación policial o para un procedimiento sancionador\"</span>Para una investigación policial o un procedimiento sancionador."}]},{"a":"Artículo 20","q":[{"i":"23-20","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. En relación a la inscripción Registral:","o":["Toda empresa de seguridad privada autorizada o que, en su caso, haya presentado la correspondiente declaración responsable será inscrita de oficio en el Registro Nacional de Seguridad Privada y en el correspondiente registro autónomo.","Toda empresa de seguridad privada pendiente de autorización o que, en su caso, haya presentado la correspondiente declaración responsable será inscrita de oficio en el Registro Nacional de Seguridad Privada o en el correspondiente registro autónomo.","Toda empresa de seguridad privada autorizada o que, en su caso, haya presentado la correspondiente declaración responsable será inscrita de oficio en el Registro Nacional de Seguridad Privada o en el correspondiente registro autónomo.","Toda empresa de seguridad privada autorizada siempre que, haya presentado la correspondiente declaración responsable será inscrita a instancia de parte en el Registro Nacional de Seguridad Privada o en el correspondiente registro autónomo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Toda empresa de seguridad privada autorizada o que, en su caso, haya presentado la correspondiente declaración responsable será inscrita de oficio en el Registro Nacional de Seguridad Privada o en el correspondiente registro autónomo</mark></span><span class=\"ref-norma\">Art. 20 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Toda empresa de seguridad privada autorizada o que, en su caso, haya presentado la correspondiente declaración responsable será inscrita de oficio en el Registro Nacional de Seguridad Privada o en el correspondiente registro autonómico.\"</span>"},{"i":"23-94","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. No podrá inscribirse en el Registro Nacional de Seguridad Privada o en el correspondiente registro autonómico ninguna empresa cuya denominación: Señale la incorrecta.","o":["Conduzca, o pueda inducir a error o confusión, con la de otra ya inscrita.","Conduzca, o pueda inducir a error o confusión, con la de órganos o dependencias de las administraciones públicas.","Conduzca o pueda inducir a confusión con una marca anterior registrada para actividades idénticas o semejantes, sin excepciones.","Conduzca o pueda inducir a confusión con una marca anterior registrada para actividades idénticas o semejantes, salvo que se solicite por el titular de la misma o con su consentimiento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Conduzca o pueda inducir a confusión con una marca anterior registrada para actividades idénticas o semejantes, sin excepciones</mark></span><span class=\"ref-norma\">Art. 20 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No podrá inscribirse en el Registro Nacional de Seguridad Privada o en el correspondiente registro autonómico ninguna empresa cuya denominación coincida, o pueda inducir a error o confusión, con la de otra ya inscrita o con la de órganos o dependencias de las administraciones públicas, o cuando coincida o pueda inducir a confusión con una marca anterior registrada para actividades idénticas o semejantes, salvo que se solicite por el titular de la misma o con su consentimiento.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1222","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Inscripción registral. No podrá inscribirse en el Registro Nacional de Seguridad Privada ninguna empresa cuya denominación coincida, o pueda inducir a error o confusión, con la de otra ya inscrita o con la de órganos o dependencias de las administraciones públicas, o con una marca anterior registrada para actividades idénticas o semejantes, salvo que:","o":["la nueva empresa tenga ámbito territorial distinto, sin perjuicio de lo previsto en la normativa vigente.","se acredite su uso anterior a la inscripción.","lo autorice el Ministerio del Interior.","se solicite por el titular de la misma o con su consentimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se solicite por el titular de la misma o con su consentimiento</mark></span><span class=\"ref-norma\">Art.  20.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"salvo que se solicite por el titular de la misma o con su consentimiento\"</span>Solo si lo solicita el titular de la marca o con su consentimiento."},{"i":"23-ia-1223","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. Las empresas de seguridad deben comunicar al Registro Nacional o autonómico del lugar donde presten servicios:","o":["las altas, bajas y sanciones del personal de seguridad privada de que dispongan.","las altas y bajas del personal de seguridad privada, trimestralmente.","las altas y bajas del personal de seguridad privada de que dispongan y las incidencias concretas relacionadas con los servicios que prestan.","las incidencias concretas de los servicios, pero no las altas y bajas de personal, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las altas y bajas del personal de seguridad privada de que dispongan y las incidencias concretas relacionadas con los servicios que prestan</mark></span><span class=\"ref-norma\">Art.  21.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"las altas y bajas del personal de seguridad privada de que dispongan y las incidencias concretas relacionadas con los servicios que prestan\"</span>Altas y bajas del personal e incidencias de los servicios."},{"i":"23-ia-1224","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. Las empresas de seguridad privada deben comunicar al Registro Nacional o autonómico correspondiente todo cambio que se produzca en cuanto a su forma jurídica, denominación, número de identificación fiscal, domicilio, delegaciones, ámbito territorial de actuación, representantes legales, estatutos, titularidad de las acciones y participaciones sociales, y:","o":["toda variación del volumen de facturación y del número de trabajadores, previo informe de la unidad policial competente.","toda variación que sobrevenga en la composición de los órganos de administración, gestión, representación y dirección.","toda modificación de los contratos de seguros suscritos.","toda variación de las instalaciones y medios técnicos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">toda variación que sobrevenga en la composición de los órganos de administración, gestión, representación y dirección</mark></span><span class=\"ref-norma\">Art.  21.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y toda variación que sobrevenga en la composición de los órganos de administración, gestión, representación y dirección de las empresas\"</span>También las variaciones en la composición de los órganos de administración y dirección."},{"i":"23-ia-1225","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. Las empresas de seguridad privada deben garantizar la formación y actualización profesional de su personal. El mantenimiento de la aptitud en el uso de las armas de fuego se hará:","o":["con la participación de instructores de tiro habilitados.","en los campos de tiro de las Fuerzas y Cuerpos de Seguridad.","con la participación de armeros autorizados.","en los centros de formación de seguridad privada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con la participación de instructores de tiro habilitados</mark></span><span class=\"ref-norma\">Art.  21.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El mantenimiento de la aptitud en el uso de las armas de fuego se hará con la participación de instructores de tiro habilitados\"</span>Con instructores de tiro habilitados."},{"i":"23-ia-1226","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. Las empresas de seguridad privada deberán presentar cada año al Ministerio del Interior o al órgano autonómico competente un informe sobre sus actividades y el resumen de las cuentas anuales, debidamente auditadas:","o":["en todo caso.","cuando lo solicite la Administración.","si superan una determinada facturación.","cuando sea preceptivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuando sea preceptivo</mark></span><span class=\"ref-norma\">Art.  21.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"debidamente auditadas cuando sea preceptivo\"</span>Auditadas cuando sea preceptivo."},{"i":"23-ia-1227","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. El Ministerio del Interior y los órganos autonómicos competentes darán cuenta del funcionamiento del sector a las Cortes Generales y a los Parlamentos autonómicos correspondientes:","o":["semestralmente.","cada dos años.","anualmente.","cuando se lo soliciten."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">anualmente</mark></span><span class=\"ref-norma\">Art.  21.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"darán cuenta del funcionamiento del sector a las Cortes Generales y a los Parlamentos autonómicos correspondientes respectivamente, anualmente\"</span>La rendición de cuentas es anual."}]},{"a":"Artículo 69","q":[{"i":"23-23","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Publicidad de las sanciones. Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra: Señale la correcta.","o":["Riesgo para la seguridad de los usuarios o ciudadanos.","Reincidencia en infracciones de naturaleza análoga.","Acreditada intencionalidad.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 71 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos, reincidencia en infracciones de naturaleza análoga o acreditada intencionalidad.\"</span>"},{"i":"23-45","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. Las medidas cautelares, que deberán ser congruentes con la naturaleza de la presunta infracción y proporcionadas a la gravedad de la misma, podrán consistir en:","o":["La ocupación o precinto de vehículos, armas, material o equipo prohibido, no homologado o que resulte peligroso o perjudicial, así como de los instrumentos y efectos de la infracción.","La retirada preventiva de las autorizaciones, habilitaciones, permisos o licencias, o la suspensión, en su caso, de la eficacia de las declaraciones responsables.","La suspensión de la habilitación del personal de seguridad privada y, en su caso, de la tramitación del procedimiento para el otorgamiento de aquélla, mientras dure la instrucción de expedientes por infracciones graves o muy graves en materia de seguridad privada.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 69 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Dichas medidas, que deberán ser congruentes con la naturaleza de la presunta infracción y proporcionadas a la gravedad de la misma, podrán consistir en:\"</span>"},{"i":"23-49","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuándo el órgano que haya ordenado la incoación del procedimiento sancionador podrá adoptar las medidas cautelares necesarias para garantizar su adecuada instrucción, así como para evitar la continuación de la infracción o asegurar el pago de la sanción, en el caso de que ésta fuese pecuniaria, y el cumplimiento de la misma en los demás supuestos?","o":["Después de las diligencias previas del procedimiento.","Iniciado el procedimiento sancionador.","Antes de iniciar el procedimiento sancionador.","Finalizado el procedimiento sancionador."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Iniciado el procedimiento sancionador</mark></span><span class=\"ref-norma\">Art. 69.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Iniciado el procedimiento sancionador, el órgano que haya ordenado su incoación podrá adoptar las medidas cautelares necesarias para garantizar su adecuada instrucción\"</span>"},{"i":"23-67","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ejecutoriedad. Las sanciones impuestas serán inmediatamente ejecutivas desde que la resolución adquiera firmeza en vía administrativa. En los casos de suspensión temporal y extinción de la eficacia de autorizaciones, habilitaciones o declaraciones responsables y prohibición del ejercicio de la representación legal de las empresas, la autoridad sancionadora señalará un plazo de ejecución suficiente, que ______ oyendo al sancionado y a los terceros que pudieran resultar directamente afectados:","o":["No podrá ser inferior a quince días hábiles ni superior a dos meses.","No podrá ser inferior a quince días hábiles ni superior a un mes.","No podrá ser inferior a cinco días hábiles ni superior a dos meses.","No podrá ser inferior a diez días hábiles ni superior a dos meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No podrá ser inferior a quince días hábiles ni superior a dos meses</mark></span><span class=\"ref-norma\">Art. 70 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Cuando la sanción sea de naturaleza pecuniaria y no se haya previsto plazo para satisfacerla, la autoridad que la impuso lo señalará, sin que pueda ser inferior a quince ni superior a treinta días hábiles, pudiendo acordarse el fraccionamiento del pago.\"</span>"},{"i":"23-70","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Publicidad de las sanciones. Señale la CORRECTA:","o":["Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas responsables de infracciones muy graves podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente, con independencia de que concurra o no riesgo para la seguridad de los usuarios.","Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, aunque no concurra riesgo para la seguridad de los usuarios o ciudadanos.","Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, aunque no concurra riesgo para la seguridad de los usuarios o ciudadanos.","Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos</mark></span><span class=\"ref-norma\">Art. 71 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos, reincidencia en infracciones de naturaleza análoga o acreditada intencionalidad.\"</span>"},{"i":"23-71","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. ¿Cuál de las siguientes medidas cautelares podrá tener una duración superior a un año?","o":["La ocupación o precinto de vehículos, armas, material o equipo prohibido, no homologado o que resulte peligroso o perjudicial, así como de los instrumentos y efectos de la infracción.","La retirada preventiva de las autorizaciones, habilitaciones, permisos o licencias, o la suspensión, en su caso, de la eficacia de las declaraciones responsables.","La suspensión de la habilitación del personal de seguridad privada y, en su caso, de la tramitación del procedimiento para el otorgamiento de aquélla, mientras dure la instrucción de expedientes por infracciones graves o muy graves en materia de seguridad privada.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La ocupación o precinto de vehículos, armas, material o equipo prohibido, no homologado o que resulte peligroso o perjudicial, así como de los instrumentos y efectos de la infracción</mark></span><span class=\"ref-norma\">Art. 69 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) La ocupación o precinto de vehículos, armas, material o equipo prohibido, no homologado o que resulte peligroso o perjudicial, así como de los instrumentos y efectos de la infracción.\"</span>"},{"i":"23-77","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra:","o":["Riesgo para la seguridad de los usuarios o ciudadanos.","Reincidencia en infracciones de naturaleza análoga.","Acreditada intencionalidad.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 71 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos, reincidencia en infracciones de naturaleza análoga o acreditada intencionalidad.\"</span>"},{"i":"23-107","p":"Ley 5/2014, de Seguridad Privada. Publicidad de las sanciones. Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra:","o":["Riesgo para la seguridad de los usuarios o ciudadanos.","Reincidencia en infracciones de naturaleza análoga.","Acreditada intencionalidad.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 71 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sanciones, así como los nombres, apellidos, denominación o razón social de las personas físicas o jurídicas responsables de la comisión de infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos, reincidencia en infracciones de naturaleza análoga o acreditada intencionalidad.\"</span>"},{"i":"23-128","p":"La Ley 5/2014, de 4 de abril, de Seguridad Privada. El procedimiento caducará transcurridos ______ desde su incoación sin que se haya notificado la resolución, debiendo, no obstante, tenerse en cuenta en el cómputo las posibles paralizaciones por causas imputables al interesado o la suspensión que debiera acordarse por la existencia de un procedimiento judicial penal, cuando concurra identidad de sujeto, hecho y fundamento, hasta la finalización de éste.","o":["6 meses","12 meses","3 meses","9 meses"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">6 meses</mark></span><span class=\"ref-norma\">Art. 69 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El procedimiento caducará transcurridos seis meses desde su incoación sin que se haya notificado la resolución, debiendo, no obstante, tenerse en cuenta en el cómputo las posibles paralizaciones por causas imputables al interesado o la suspensión que debiera acordarse por la existencia de un procedimiento judicial penal, cuando concurra identidad de sujeto, hecho y fundamento, hasta la finalización de éste.\"</span>"},{"i":"23-ia-1615","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. El ejercicio de la potestad sancionadora en materia de seguridad privada se regirá por lo dispuesto en la Ley del Procedimiento Administrativo Común de las Administraciones Públicas, la Ley de Régimen Jurídico del Sector Público y sus disposiciones de desarrollo, sin perjuicio de:","o":["lo dispuesto en la Ley de Enjuiciamiento Criminal, previo informe de la unidad policial competente.","las competencias de las comunidades autónomas.","las especialidades que se regulan en el título del régimen sancionador.","lo previsto reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las especialidades que se regulan en el título del régimen sancionador</mark></span><span class=\"ref-norma\">Art.  69.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sin perjuicio de las especialidades que se regulan en este título\"</span>Sin perjuicio de las especialidades del título."},{"i":"23-ia-1616","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. El procedimiento sancionador en materia de seguridad privada caducará transcurridos seis meses desde su incoación sin que se haya notificado la resolución, debiendo, no obstante, tenerse en cuenta en el cómputo:","o":["las paralizaciones imputables a la Administración y la suspensión por recursos del interesado.","las posibles paralizaciones por causas imputables al interesado o la suspensión que debiera acordarse por la existencia de un procedimiento judicial penal.","las posibles paralizaciones imputables al interesado, pero no la existencia de un procedimiento penal, sin perjuicio de lo previsto en la normativa vigente.","la suspensión por procedimientos contencioso-administrativos en curso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las posibles paralizaciones por causas imputables al interesado o la suspensión que debiera acordarse por la existencia de un procedimiento judicial penal</mark></span><span class=\"ref-norma\">Art.  69.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"debiendo, no obstante, tenerse en cuenta en el cómputo las posibles paralizaciones por causas imputables al interesado o la suspensión que debiera acordarse por la existencia de un procedimiento judicial penal\"</span>Paralizaciones imputables al interesado y suspensión por procedimiento penal."},{"i":"23-ia-1617","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. Iniciado el procedimiento sancionador, el órgano que haya ordenado su incoación podrá adoptar las medidas cautelares necesarias para garantizar su adecuada instrucción, así como para evitar la continuación de la infracción o:","o":["asegurar el pago de la sanción, en el caso de que ésta fuese pecuniaria, y el cumplimiento de la misma en los demás supuestos.","asegurar la reparación de los daños causados a terceros, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","garantizar la custodia de las pruebas obtenidas.","evitar la prescripción de la infracción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">asegurar el pago de la sanción, en el caso de que ésta fuese pecuniaria, y el cumplimiento de la misma en los demás supuestos</mark></span><span class=\"ref-norma\">Art.  69.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o asegurar el pago de la sanción, en el caso de que ésta fuese pecuniaria, y el cumplimiento de la misma en los demás supuestos\"</span>Asegurar el pago o el cumplimiento de la sanción."},{"i":"23-ia-1618","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. Señale la medida que NO es una de las medidas cautelares que pueden adoptarse una vez iniciado el procedimiento sancionador:","o":["La retirada preventiva de las autorizaciones, habilitaciones, permisos o licencias, o la suspensión de la eficacia de las declaraciones responsables.","La ocupación o precinto de vehículos, armas, material o equipo prohibido, no homologado o que resulte peligroso o perjudicial.","La suspensión de la habilitación del personal de seguridad privada mientras dure la instrucción de expedientes por infracciones graves o muy graves.","La clausura definitiva del establecimiento infractor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La clausura definitiva del establecimiento infractor</mark></span><span class=\"ref-norma\">Art.  69.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La ocupación o precinto de vehículos, armas, material o equipo prohibido, no homologado o que resulte peligroso o perjudicial, así como de los instrumentos y efectos de la infracción\"</span>La clausura definitiva no figura entre las medidas cautelares."},{"i":"23-ia-1619","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Régimen jurídico. Las medidas cautelares consistentes en la retirada preventiva de autorizaciones o la suspensión de la habilitación del personal no podrán tener una duración superior a:","o":["seis meses.","dos años.","un año.","tres meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un año</mark></span><span class=\"ref-norma\">Art.  69.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no podrán tener una duración superior a un año\"</span>No pueden superar un año."},{"i":"23-ia-1620","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ejecutoriedad. Las sanciones impuestas serán inmediatamente ejecutivas desde que la resolución adquiera firmeza:","o":["en vía judicial.","en vía administrativa.","por haber transcurrido el plazo de recurso de alzada.","por la notificación al interesado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en vía administrativa</mark></span><span class=\"ref-norma\">Art.  70.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sanciones impuestas serán inmediatamente ejecutivas desde que la resolución adquiera firmeza en vía administrativa\"</span>Desde que sea firme en vía administrativa."},{"i":"23-ia-1621","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ejecutoriedad. Cuando la sanción sea de naturaleza pecuniaria y no se haya previsto plazo para satisfacerla, la autoridad que la impuso lo señalará, sin que pueda ser inferior a quince ni superior a:","o":["treinta días hábiles, pudiendo acordarse el fraccionamiento del pago.","treinta días naturales, sin posibilidad de fraccionamiento.","sesenta días hábiles, pudiendo acordarse el aplazamiento.","veinte días hábiles, pudiendo acordarse el fraccionamiento del pago, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">treinta días hábiles, pudiendo acordarse el fraccionamiento del pago</mark></span><span class=\"ref-norma\">Art.  70.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sin que pueda ser inferior a quince ni superior a treinta días hábiles, pudiendo acordarse el fraccionamiento del pago\"</span>Entre quince y treinta días hábiles, con posible fraccionamiento."},{"i":"23-ia-1622","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ejecutoriedad. En los casos de suspensión temporal y extinción de la eficacia de autorizaciones, habilitaciones o declaraciones responsables y prohibición del ejercicio de la representación legal de las empresas, la autoridad sancionadora señalará un plazo de ejecución suficiente, que no podrá ser inferior a quince días hábiles ni superior a:","o":["un mes, oyendo al sancionado.","treinta días hábiles, oyendo al sancionado y a terceros afectados, sin perjuicio de lo previsto en la normativa vigente.","tres meses, oyendo al sancionado y a sus representantes.","dos meses, oyendo al sancionado y a los terceros que pudieran resultar directamente afectados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos meses, oyendo al sancionado y a los terceros que pudieran resultar directamente afectados</mark></span><span class=\"ref-norma\">Art.  70.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que no podrá ser inferior a quince días hábiles ni superior a dos meses, oyendo al sancionado y a los terceros que pudieran resultar directamente afectados\"</span>Entre quince días hábiles y dos meses, con audiencia del sancionado y de terceros afectados."},{"i":"23-ia-1623","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Publicidad de las sanciones. Las sanciones por infracciones muy graves, cuando hayan adquirido firmeza en vía administrativa, podrán ser hechas públicas, en virtud de acuerdo de la autoridad competente para su imposición, siempre que concurra riesgo para la seguridad de los usuarios o ciudadanos, reincidencia en infracciones de naturaleza análoga o:","o":["reiteración en el último año.","grave perjuicio para el interés público.","acreditada intencionalidad.","especial relevancia de la empresa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">acreditada intencionalidad</mark></span><span class=\"ref-norma\">Art.  71 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"reincidencia en infracciones de naturaleza análoga o acreditada intencionalidad\"</span>O acreditada intencionalidad."}]},{"a":"Artículo 22","q":[{"i":"23-26","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los representantes de las empresas de seguridad privada, que se inscribirán en el Registro Nacional de Seguridad Privada o en el correspondiente registro autonómico, deberán... señale la incorrecta.","o":["Ser personas físicas residentes en el territorio de alguno de los Estados miembros de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo.","Carecer de antecedentes penales por delitos fraudulentos.","Carecer de antecedentes penales por delitos dolosos.","No haber sido separados del servicio en las Fuerzas Armadas o en las Fuerzas y Cuerpos de Seguridad, ni haber ejercido funciones de control de las entidades o servicios de seguridad, vigilancia o investigación privadas, ni de su personal o medios, como miembros de las Fuerzas y Cuerpos de Seguridad, en los dos años anteriores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Carecer de antecedentes penales por delitos fraudulentos</mark></span><span class=\"ref-norma\">Art. 22 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"b) Carecer de antecedentes penales por delitos dolosos.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-81","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. A los efectos de esta ley, se entenderá por ______ de las empresas de seguridad privada todo aquel que asuma o realice las tareas de dirección, administración, gestión y representación, o cualquiera de ellas, en nombre de aquéllas.","o":["Administrador legal.","Jefe de seguridad.","Representante legal.","Director de seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Representante legal</mark></span><span class=\"ref-norma\">Art. 22 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"A los efectos de esta ley, se entenderá por representante legal de las empresas de seguridad privada todo aquel que asuma o realice las tareas de dirección, administración, gestión y representación, o cualquiera de ellas, en nombre de aquéllas.\"</span>"},{"i":"23-91","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Para la obtención de las habilitaciones profesionales indicadas en el artículo anterior, los aspirantes habrán de reunir los siguientes requisitos generales. Señale la INCORRECTA:","o":["Carecer de antecedentes penales por delitos.","No haber sido sancionado en los dos o cuatro años anteriores por infracción grave o muy grave, respectivamente, en materia de seguridad privada.","No haber sido separado del servicio en las Fuerzas y Cuerpos de Seguridad o en las Fuerzas Armadas españolas o del país de su nacionalidad o procedencia en los dos años anteriores.","No haber sido condenado por intromisión ilegítima en el ámbito de protección del derecho al honor, a la intimidad personal y familiar o a la propia imagen, vulneración del secreto de las comunicaciones o de otros derechos fundamentales en los cinco años anteriores a la solicitud."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Carecer de antecedentes penales por delitos</mark></span><span class=\"ref-norma\">Art. 22 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"b) Carecer de antecedentes penales por delitos dolosos.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1228","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Representantes legales. Se entenderá por representante legal de las empresas de seguridad privada:","o":["todo aquel que asuma las tareas de dirección y representación en nombre de la empresa, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","todo aquel que asuma o realice las tareas de dirección, administración, gestión y representación, o cualquiera de ellas, en nombre de aquéllas.","quien ostente la titularidad de la mayoría del capital social de la empresa.","todo aquel que figure como administrador en el Registro Mercantil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">todo aquel que asuma o realice las tareas de dirección, administración, gestión y representación, o cualquiera de ellas, en nombre de aquéllas</mark></span><span class=\"ref-norma\">Art.  22.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"todo aquel que asuma o realice las tareas de dirección, administración, gestión y representación, o cualquiera de ellas, en nombre de aquéllas\"</span>Cualquiera de las tareas de dirección, administración, gestión y representación."},{"i":"23-ia-1229","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Representantes legales. Señale el requisito que NO han de cumplir los representantes legales de las empresas de seguridad privada:","o":["Poseer la nacionalidad española.","Carecer de antecedentes penales por delitos dolosos.","Ser personas físicas residentes en el territorio de alguno de los Estados miembros de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo.","No haber sido sancionados en los dos o cuatro años anteriores por infracción grave o muy grave, respectivamente, en materia de seguridad privada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Poseer la nacionalidad española</mark></span><span class=\"ref-norma\">Art.  22.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Ser personas físicas residentes en el territorio de alguno de los Estados miembros de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo\"</span>Se exige residencia en la UE o EEE, no nacionalidad española."},{"i":"23-ia-1230","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Representantes legales. Los representantes legales de las empresas de seguridad privada no deben haber sido separados del servicio en las Fuerzas Armadas o en las Fuerzas y Cuerpos de Seguridad, ni haber ejercido funciones de control de las entidades o servicios de seguridad, vigilancia o investigación privadas, como miembros de las Fuerzas y Cuerpos de Seguridad, en:","o":["los cinco años anteriores.","los tres años anteriores.","el año anterior.","los dos años anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los dos años anteriores</mark></span><span class=\"ref-norma\">Art.  22.2.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"como miembros de las Fuerzas y Cuerpos de Seguridad, en los dos años anteriores\"</span>El plazo es de dos años."},{"i":"23-ia-1231","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Representantes legales. Los representantes legales de las empresas de seguridad privada no deben haber sido administrador de hecho o de derecho o apoderado general, en los diez años anteriores, en una empresa que haya sido:","o":["declarada en concurso de acreedores, o sancionada por infracción muy grave.","sancionada por infracción grave o muy grave, o condenada por delito doloso.","declarada en concurso calificado como culpable, o condenada mediante sentencia firme por determinados delitos.","declarada en concurso calificado como culpable, aunque no haya sido condenada por delito alguno, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">declarada en concurso calificado como culpable, o condenada mediante sentencia firme por determinados delitos</mark></span><span class=\"ref-norma\">Art.  22.2.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No haber sido administrador de hecho o de derecho o apoderado general, en los diez años anteriores, en una empresa que haya sido declarada en concurso calificado como culpable, o condenada mediante sentencia firme por delitos de insolvencia punible\"</span>Diez años anteriores; concurso calificado como culpable o condena firme por determinados delitos."},{"i":"23-ia-1232","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Representantes legales. Los representantes legales de las empresas de seguridad privada serán responsables del cumplimiento de:","o":["las obligaciones laborales respecto de su personal.","las obligaciones generales impuestas a las mismas.","los requisitos de inscripción en el Registro Nacional.","las obligaciones de colaboración con las Fuerzas y Cuerpos de Seguridad exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las obligaciones generales impuestas a las mismas</mark></span><span class=\"ref-norma\">Art.  22.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"serán responsables del cumplimiento de las obligaciones generales impuestas a las mismas\"</span>Responden de las obligaciones generales."}]},{"a":"Artículo 60","q":[{"i":"23-28","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las autoridades competentes podrán imponer, por la comisión de infracciones graves, las siguientes sanciones:","o":["Suspensión temporal de la declaración responsable del centro de formación por un plazo de entre seis meses y un año.","Multa de 300 a 3.000 euros.","La clausura, desde seis meses y un día a dos años, de los establecimientos que no tengan en funcionamiento las medidas de seguridad obligatorias.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Suspensión temporal de la declaración responsable del centro de formación por un plazo de entre seis meses y un año</mark></span><span class=\"ref-norma\">Art. 63 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"b) Suspensión temporal de la declaración responsable del centro de formación por un plazo de entre seis meses y un año.\"</span>"},{"i":"23-33","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las autoridades competentes podrán imponer, por la comisión de las infracciones tipificadas en el artículo 57, las siguientes sanciones por la comisión de infracciones leves: señale la incorrecta.","o":["Apercibimiento.","Cierre temporal de las empresas y cese de la actividad durante 4 meses.","Multa de 300 a 3.000 euros.","Las opciones A y B son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cierre temporal de las empresas y cese de la actividad durante 4 meses</mark></span><span class=\"ref-norma\">Art. 61.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Por la comisión de infracciones leves: a) Apercibimiento. b) Multa de 300 a 3.000 euros\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-113","p":"Ley 5/2014, de Seguridad Privada. Sanciones a los usuarios y a los centros de formación. ¿Qué sanción se podrá imponer por la comisión de una infracción grave?","o":["Multa de 6.000 a 15.000 euros.","Cierre del centro de formación, que comportará la prohibición de volver a presentar la declaración responsable para su apertura por un plazo de entre uno y dos años, y cancelación de la inscripción en el registro correspondiente.","La clausura, desde seis meses y un día a dos años, de los establecimientos que no tengan en funcionamiento las medidas de seguridad obligatorias.","Ninguna de las opciones anteriores es correcta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ninguna de las opciones anteriores es correcta</mark></span><span class=\"ref-norma\">Art. 63 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Sanciones a usuarios y centros de formación.\"</span>"},{"i":"23-115","p":"Ley 5/2014, de Seguridad Privada. Las disposiciones reglamentarias de desarrollo ____ especificaciones o graduaciones en el cuadro de las infracciones y sanciones establecidas en esta ley que [...] contribuyan a la más correcta identificación de las conductas o a la más precisa determinación de las mismas.","o":["Podrán introducir.","Decisión limitada.","No podrán introducir.","Excepcionalmente podrán introducir."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrán introducir</mark></span><span class=\"ref-norma\">Art. 60 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las disposiciones reglamentarias de desarrollo podrán introducir especificaciones o graduaciones en el cuadro de las infracciones y sanciones establecidas en esta ley que, sin constituir nuevas infracciones o sanciones, ni alterar la naturaleza o límites de las que en ella se contemplan, contribuyan a la más correcta identificación de las conductas o a la más precisa determinación de las sanciones correspondientes.\"</span>"},{"i":"23-ia-1549","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Colaboración reglamentaria. Las disposiciones reglamentarias de desarrollo podrán introducir especificaciones o graduaciones en el cuadro de las infracciones y sanciones que, sin constituir nuevas infracciones o sanciones, ni alterar:","o":["la naturaleza o límites de las que en ella se contemplan, contribuyan a la más correcta identificación de las conductas o a la más precisa determinación de las sanciones.","la tipificación de las infracciones muy graves, contribuyan a una mayor seguridad jurídica, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","los plazos de prescripción, contribuyan a la más precisa identificación de las conductas.","la cuantía de las multas, contribuyan a una mejor determinación de las conductas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la naturaleza o límites de las que en ella se contemplan, contribuyan a la más correcta identificación de las conductas o a la más precisa determinación de las sanciones</mark></span><span class=\"ref-norma\">Art.  60 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"ni alterar la naturaleza o límites de las que en ella se contemplan, contribuyan a la más correcta identificación de las conductas o a la más precisa determinación de las sanciones correspondientes\"</span>No pueden alterar la naturaleza o límites de las infracciones y sanciones legales."},{"i":"23-ia-1550","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a las empresas. Por la comisión de infracciones muy graves de las empresas de seguridad privada, las autoridades competentes podrán imponer una multa de:","o":["20.001 a 100.000 euros, en los términos que se determinen reglamentariamente.","6.001 a 30.000 euros.","3.001 a 30.000 euros.","30.001 a 600.000 euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">30.001 a 600.000 euros</mark></span><span class=\"ref-norma\">Art.  61.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 30.001 a 600.000 euros\"</span>La multa por infracciones muy graves de las empresas es de 30.001 a 600.000 euros."},{"i":"23-ia-1551","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a las empresas. Entre las sanciones por infracciones muy graves de las empresas figura la extinción de la autorización, o cierre de la empresa o despacho en los casos de declaración responsable, que comportará la prohibición de volver a obtenerla o presentarla, respectivamente, por un plazo de:","o":["entre seis meses y un año, y cancelación de la inscripción, salvo que la autoridad judicial disponga otra cosa.","entre dos y cinco años, y cancelación de la inscripción.","entre uno y dos años, y cancelación de la inscripción en el registro correspondiente.","de hasta dos años, sin cancelación de la inscripción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">entre uno y dos años, y cancelación de la inscripción en el registro correspondiente</mark></span><span class=\"ref-norma\">Art.  61.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que comportará la prohibición de volver a obtenerla o presentarla, respectivamente, por un plazo de entre uno y dos años, y cancelación de la inscripción en el registro correspondiente\"</span>Prohibición de entre uno y dos años y cancelación de la inscripción."},{"i":"23-ia-1552","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a las empresas. Por la comisión de infracciones graves de las empresas de seguridad privada, las autoridades competentes podrán imponer una multa de:","o":["1.001 a 6.000 euros.","3.001 a 30.000 euros.","3.001 a 20.000 euros, previo informe de la unidad policial competente.","6.001 a 30.000 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">3.001 a 30.000 euros</mark></span><span class=\"ref-norma\">Art.  61.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 3.001 a 30.000 euros\"</span>3.001 a 30.000 euros."},{"i":"23-ia-1553","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a las empresas. Por infracciones graves de las empresas puede imponerse la suspensión temporal de la autorización o de la declaración responsable por un plazo de:","o":["entre seis meses y un año.","entre uno y dos años.","entre tres y seis meses, sin perjuicio de lo previsto en la normativa vigente.","de hasta seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entre seis meses y un año</mark></span><span class=\"ref-norma\">Art.  61.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Suspensión temporal de la autorización o de la declaración responsable por un plazo de entre seis meses y un año\"</span>Entre seis meses y un año."},{"i":"23-ia-1554","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a las empresas. Por la comisión de infracciones leves de las empresas de seguridad privada pueden imponerse apercibimiento o multa de:","o":["300 a 1.000 euros.","601 a 3.000 euros.","1.001 a 3.000 euros.","300 a 3.000 euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">300 a 3.000 euros</mark></span><span class=\"ref-norma\">Art.  61.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 300 a 3.000 euros\"</span>300 a 3.000 euros."},{"i":"23-ia-1555","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones al personal. Por la comisión de infracciones muy graves del personal de seguridad privada pueden imponerse multa de 6.001 a 30.000 euros y:","o":["suspensión de la habilitación por un plazo de entre seis meses y un año.","extinción de la habilitación, con prohibición de volver a obtenerla por un plazo de entre dos y cinco años, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","extinción de la habilitación, con prohibición de volver a obtenerla por un plazo de entre uno y dos años, y cancelación de la inscripción en el Registro Nacional.","retirada de la tarjeta de identidad profesional por un plazo de entre uno y dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">extinción de la habilitación, con prohibición de volver a obtenerla por un plazo de entre uno y dos años, y cancelación de la inscripción en el Registro Nacional</mark></span><span class=\"ref-norma\">Art.  62.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Extinción de la habilitación, que comportará la prohibición de volver a obtenerla por un plazo de entre uno y dos años, y cancelación de la inscripción en el Registro Nacional\"</span>Extinción de la habilitación, prohibición de entre uno y dos años y cancelación de la inscripción."},{"i":"23-ia-1556","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones al personal. Por la comisión de infracciones graves del personal de seguridad privada pueden imponerse una multa de:","o":["3.001 a 30.000 euros y suspensión temporal de la habilitación por un plazo de entre uno y dos años, previo informe de la unidad policial competente.","1.001 a 6.000 euros y suspensión temporal de la habilitación por un plazo de entre seis meses y un año.","1.001 a 6.000 euros y suspensión temporal de la habilitación de hasta seis meses.","601 a 6.000 euros y prohibición de ejercer funciones por un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">1.001 a 6.000 euros y suspensión temporal de la habilitación por un plazo de entre seis meses y un año</mark></span><span class=\"ref-norma\">Art.  62.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 1.001 a 6.000 euros. b) Suspensión temporal de la habilitación por un plazo de entre seis meses y un año\"</span>Multa de 1.001 a 6.000 euros y suspensión de seis meses a un año."},{"i":"23-ia-1557","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones al personal. Por la comisión de infracciones leves del personal de seguridad privada pueden imponerse apercibimiento o multa de:","o":["300 a 1.000 euros.","300 a 3.000 euros, sin perjuicio de lo previsto en la normativa vigente.","100 a 1.000 euros.","601 a 1.000 euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">300 a 1.000 euros</mark></span><span class=\"ref-norma\">Art.  62.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 300 a 1.000 euros\"</span>300 a 1.000 euros."},{"i":"23-ia-1558","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a usuarios y centros de formación. Por la comisión de infracciones muy graves de los usuarios y centros de formación pueden imponerse una multa de:","o":["30.001 a 600.000 euros, en los términos que se determinen reglamentariamente.","6.001 a 30.000 euros.","10.001 a 100.000 euros.","20.001 a 100.000 euros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">20.001 a 100.000 euros</mark></span><span class=\"ref-norma\">Art.  63.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 20.001 a 100.000 euros\"</span>20.001 a 100.000 euros."},{"i":"23-ia-1559","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a usuarios y centros de formación. Por infracciones muy graves de los usuarios puede imponerse la clausura de los establecimientos que no tengan en funcionamiento las medidas de seguridad obligatorias:","o":["de seis meses a un año.","desde un mes y un día a seis meses, salvo que la autoridad judicial disponga otra cosa.","desde seis meses y un día a dos años.","desde un año y un día a tres años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">desde seis meses y un día a dos años</mark></span><span class=\"ref-norma\">Art.  63.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La clausura, desde seis meses y un día a dos años, de los establecimientos que no tengan en funcionamiento las medidas de seguridad obligatorias\"</span>Desde seis meses y un día a dos años."},{"i":"23-ia-1560","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Sanciones a usuarios y centros de formación. Por la comisión de infracciones graves de los usuarios y centros de formación puede imponerse una multa de:","o":["3.001 a 30.000 euros, previo informe de la unidad policial competente.","3.001 a 20.000 euros.","1.001 a 6.000 euros.","6.001 a 20.000 euros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">3.001 a 20.000 euros</mark></span><span class=\"ref-norma\">Art.  63.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Multa de 3.001 a 20.000 euros\"</span>3.001 a 20.000 euros."},{"i":"23-ia-1634","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Plazos de adecuación. Para la obtención de la certificación exigida a las empresas de seguridad que presten servicios en los sectores estratégicos de infraestructuras críticas, la ley establece un plazo de adecuación de:","o":["dos años.","tres meses.","seis meses.","un año."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año</mark></span><span class=\"ref-norma\">Disp. transitoria 4.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Un año para la obtención de la certificación prevista en el artículo 19.4\"</span>Un año."}]},{"a":"Artículo 51","q":[{"i":"23-32","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Quién podrá ordenar que los titulares de establecimientos o instalaciones industriales, comerciales y de servicios y los organizadores de eventos adopten las medidas de seguridad que reglamentariamente se establezcan?","o":["El Ministerio de Defensa.","El Consejo de Ministros.","El Alcalde del municipio donde radiquen los establecimientos o instalaciones industriales, comerciales y de servicios y los organizadores de eventos.","El Ministerio del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 51 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El Ministerio del Interior o, en su caso, el órgano autonómico competente podrá ordenar que los titulares de establecimientos o instalaciones industriales, comerciales y de servicios y los organizadores de eventos adopten las medidas de seguridad que reglamentariamente se establezcan.\"</span>"},{"i":"23-68","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Medidas de seguridad privada. Adopción de medidas. Señale la INCORRECTA:","o":["Las personas físicas o jurídicas, públicas o privadas, podrán dotarse de medidas de seguridad privada dirigidas a la protección de personas y bienes y al aseguramiento del normal desarrollo de sus actividades personales o empresariales.","Las sedes y delegaciones de las empresas de seguridad privada vinculadas a la operativa de seguridad y los despachos de detectives privados y sus sucursales estarán obligados a adoptar las medidas de seguridad que se establezcan mediante orden del Ministerio del Interior.","El Ministerio del Interior, en su caso, el órgano autonómico competente podrá ordenar que los titulares de establecimientos o instalaciones industriales, comerciales y de servicios y los organizadores de eventos adopten las medidas de seguridad que reglamentariamente se establezcan.","Cuando se considerase necesaria la implantación de dichas medidas en órganos u organismos públicos, el órgano competente formulará la correspondiente propuesta y, previo acuerdo con el órgano administrativo o entidad de los que dependan las instalaciones o locales necesitados de protección, dictará la resolución procedente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las sedes y delegaciones de las empresas de seguridad privada vinculadas a la operativa de seguridad y los despachos de detectives privados y sus sucursales estarán obligados a adoptar las medidas de seguridad que se establezcan mediante orden del Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 51 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sedes y delegaciones de las empresas de seguridad privada vinculadas a la operativa de seguridad y los despachos de detectives privados y sus sucursales estarán obligados a adoptar las medidas de seguridad que se establezcan reglamentariamente.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1439","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Adopción de medidas. Reglamentariamente se determinarán los establecimientos e instalaciones industriales, comerciales y de servicios y los eventos que resulten obligados a adoptar medidas de seguridad, con la finalidad de prevenir la comisión de actos delictivos contra ellos o por:","o":["su valor económico o su ubicación en zonas de riesgo.","su carácter público o su especial concentración de personas.","generar riesgos directos para terceros o ser especialmente vulnerables.","generar riesgos para el medio ambiente o ser infraestructuras críticas, sin perjuicio de lo previsto en la normativa vigente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">generar riesgos directos para terceros o ser especialmente vulnerables</mark></span><span class=\"ref-norma\">Art.  51.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con la finalidad de prevenir la comisión de actos delictivos contra ellos o por generar riesgos directos para terceros o ser especialmente vulnerables\"</span>Por generar riesgos directos a terceros o ser especialmente vulnerables."},{"i":"23-ia-1440","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Adopción de medidas. El Ministerio del Interior o, en su caso, el órgano autonómico competente podrá ordenar a los titulares de establecimientos o instalaciones y a los organizadores de eventos que adopten las medidas de seguridad. El órgano competente formulará la propuesta y, previa audiencia del titular u organizador, resolverá:","o":["en el plazo de un mes.","motivadamente.","previo informe de las Fuerzas y Cuerpos de Seguridad.","mediante resolución ejecutiva inmediata."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">motivadamente</mark></span><span class=\"ref-norma\">Art.  51.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"previa audiencia del titular u organizador, resolverá motivadamente\"</span>Previa audiencia, resuelve motivadamente."},{"i":"23-ia-1441","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Adopción de medidas. La celebración de eventos y la apertura o funcionamiento de establecimientos e instalaciones y de empresas de seguridad y sus delegaciones y despachos de detectives y sus sucursales estará condicionada a:","o":["la efectiva implantación de las medidas de seguridad que resulten obligatorias en cada caso.","la autorización previa del órgano competente en materia de seguridad privada, en los términos que se determinen reglamentariamente.","la inscripción en el Registro Nacional de Seguridad Privada.","el informe favorable de las Fuerzas y Cuerpos de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la efectiva implantación de las medidas de seguridad que resulten obligatorias en cada caso</mark></span><span class=\"ref-norma\">Art.  51.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"estará condicionada a la efectiva implantación de las medidas de seguridad que resulten obligatorias en cada caso\"</span>Condicionada a la efectiva implantación de las medidas obligatorias."},{"i":"23-ia-1442","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Adopción de medidas. Los órganos competentes podrán eximir de la implantación de medidas de seguridad obligatorias cuando:","o":["el titular lo solicite y acredite carecer de medios, salvo que la autoridad judicial disponga otra cosa.","el establecimiento cuente con medidas equivalentes.","se trate de eventos de duración inferior a un día.","las circunstancias que concurran en el caso concreto las hicieren innecesarias o improcedentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las circunstancias que concurran en el caso concreto las hicieren innecesarias o improcedentes</mark></span><span class=\"ref-norma\">Art.  51.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando las circunstancias que concurran en el caso concreto las hicieren innecesarias o improcedentes\"</span>Cuando fueran innecesarias o improcedentes en el caso concreto."},{"i":"23-ia-1443","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Adopción de medidas. Las empresas de seguridad encargadas de la prestación de las medidas de seguridad que les sean contratadas serán responsables de su correcta instalación, mantenimiento y funcionamiento, sin perjuicio de la responsabilidad en que puedan incurrir:","o":["las Fuerzas y Cuerpos de Seguridad si no comunicaron las anomalías.","sus empleados exclusivamente, si cualquier anomalía les fuera imputable, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","sus empleados o los titulares de los establecimientos, instalaciones u organizadores obligados, si cualquier anomalía en su funcionamiento les fuera imputable.","los usuarios finales de los sistemas en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sus empleados o los titulares de los establecimientos, instalaciones u organizadores obligados, si cualquier anomalía en su funcionamiento les fuera imputable</mark></span><span class=\"ref-norma\">Art.  51.7 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sin perjuicio de la responsabilidad en que puedan incurrir sus empleados o los titulares de los establecimientos, instalaciones u organizadores obligados, si cualquier anomalía en su funcionamiento les fuera imputable\"</span>Sin perjuicio de la responsabilidad de empleados o titulares si la anomalía les fuera imputable."}]},{"a":"Artículo 50","q":[{"i":"23-35","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Deber de reserva de los detectives privados. ¿Cómo se podrá acceder al contenido de las investigaciones realizadas por los detectives privados?","o":["Sólo mediante requerimiento judicial o solicitud policial relacionada con el ejercicio de sus funciones en el curso de una investigación criminal o de un procedimiento sancionador.","Sólo mediante requerimiento judicial.","Sólo a mediante solicitud judicial relacionada con el ejercicio de sus funciones en el curso de una investigación criminal o de un procedimiento sancionador.","Sólo a solicitud del cliente o mediante requerimiento judicial o solicitud judicial relacionada con el ejercicio de sus funciones en el curso de una investigación criminal o de un procedimiento sancionador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sólo mediante requerimiento judicial o solicitud policial relacionada con el ejercicio de sus funciones en el curso de una investigación criminal o de un procedimiento sancionador</mark></span><span class=\"ref-norma\">Art. 50 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Sólo mediante requerimiento judicial o solicitud policial relacionada con el ejercicio de sus funciones en el curso de una investigación criminal o de un procedimiento sancionador se podrá acceder al contenido de las investigaciones realizadas por los detectives privados.\"</span>"},{"i":"23-43","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Deber de reserva profesional de los detectives privados: señale la opción CORRECTA.","o":["Sólo mediante requerimiento judicial se podrá acceder al contenido de las investigaciones realizadas por los detectives privados.","Los detectives privados están obligados a guardar reserva sobre las investigaciones que realicen.","Los detectives privados no podrán facilitar datos o informaciones sobre las investigaciones que realicen más que a las personas que tengan un interés y a los órganos judiciales y policiales competentes para el ejercicio de sus funciones.","Todas las opciones anteriores son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los detectives privados están obligados a guardar reserva sobre las investigaciones que realicen</mark></span><span class=\"ref-norma\">Art. 50 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los detectives privados están obligados a guardar reserva sobre las investigaciones que realicen, y no podrán facilitar datos o informaciones sobre éstas más que a las personas que se las encomendaron y a los órganos judiciales y policiales competentes para el ejercicio de sus funciones.\"</span>"},{"i":"23-ia-1437","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Deber de reserva profesional. Los detectives privados están obligados a guardar reserva sobre las investigaciones que realicen, y no podrán facilitar datos o informaciones sobre éstas más que a:","o":["las personas que se las encomendaron y a los órganos judiciales y policiales competentes para el ejercicio de sus funciones.","las personas que se las encomendaron y al Ministerio Fiscal.","las personas que se las encomendaron, con carácter exclusivo, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","los órganos judiciales y al Ministerio del Interior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las personas que se las encomendaron y a los órganos judiciales y policiales competentes para el ejercicio de sus funciones</mark></span><span class=\"ref-norma\">Art.  50.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no podrán facilitar datos o informaciones sobre éstas más que a las personas que se las encomendaron y a los órganos judiciales y policiales competentes para el ejercicio de sus funciones\"</span>Solo al cliente y a los órganos judiciales y policiales competentes."},{"i":"23-ia-1438","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Deber de reserva profesional. Sólo mediante requerimiento judicial o solicitud policial relacionada con el ejercicio de sus funciones en el curso de una investigación criminal o de un procedimiento sancionador se podrá acceder:","o":["a la existencia de las investigaciones realizadas por los despachos de detectives.","a los libros-registro de los despachos de detectives.","a los contratos de servicios de investigación privada.","al contenido de las investigaciones realizadas por los detectives privados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al contenido de las investigaciones realizadas por los detectives privados</mark></span><span class=\"ref-norma\">Art.  50.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se podrá acceder al contenido de las investigaciones realizadas por los detectives privados\"</span>Para acceder al contenido de las investigaciones."}]},{"a":"Artículo 43","q":[{"i":"23-36","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La prestación de servicios de protección personal sólo podrá realizarse previa autorización del Ministerio del Interior o del órgano autonómico competente, conforme se disponga:","o":["Por ley;","Mediante real decreto.","Reglamentariamente.","Por orden ministerial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span><span class=\"ref-norma\">Art. 43 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La prestación de estos servicios sólo podrá realizarse previa autorización del Ministerio del Interior o del órgano autonómico competente, conforme se disponga reglamentariamente.\"</span>"},{"i":"23-84","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de protección personal. Señale la CORRECTA:","o":["Los servicios de protección personal, a cargo de escoltas privados, consistirán en el acompañamiento, custodia, resguardo, defensa y protección de la libertad, vida e integridad física de personas o grupos de personas determinadas.","La prestación de servicios de protección personal se realizará con independencia del lugar donde se encuentre la persona protegida, excluido su tránsito o circulación por las vías públicas.","Los escoltas privados podrán realizar identificaciones, restricciones de la circulación o detenciones en todo caso.","La prestación de estos servicios sólo podrá realizarse previa comunicación al Ministerio del Interior, conforme se disponga por orden ministerial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los servicios de protección personal, a cargo de escoltas privados, consistirán en el acompañamiento, custodia, resguardo, defensa y protección de la libertad, vida e integridad física de personas o grupos de personas determinadas</mark></span><span class=\"ref-norma\">Art. 43 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de protección personal, a cargo de escoltas privados, consistirán en el acompañamiento, custodia, resguardo, defensa y protección de la libertad, vida e integridad física de personas o grupos de personas determinadas.\"</span>"},{"i":"23-ia-1418","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de protección personal. La prestación de servicios de protección personal se realizará con independencia del lugar donde se encuentre la persona protegida, sin que se puedan realizar identificaciones, restricciones de la circulación, o detenciones, salvo en caso de:","o":["agresión o intento de agresión a la persona protegida, en los términos que se determinen reglamentariamente.","orden de las Fuerzas y Cuerpos de Seguridad.","delito flagrante en cualquier circunstancia.","flagrante delito relacionado con el objeto de su protección."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">flagrante delito relacionado con el objeto de su protección</mark></span><span class=\"ref-norma\">Art.  43.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"salvo en caso de flagrante delito relacionado con el objeto de su protección\"</span>Solo en flagrante delito relacionado con el objeto de su protección."},{"i":"23-ia-1419","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de protección personal. La prestación de los servicios de protección personal sólo podrá realizarse previa:","o":["comunicación al Ministerio del Interior o al órgano autonómico competente, salvo que la autoridad judicial disponga otra cosa.","declaración responsable de la empresa de seguridad.","autorización del Ministerio del Interior o del órgano autonómico competente.","autorización de la Dirección General de la Policía."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">autorización del Ministerio del Interior o del órgano autonómico competente</mark></span><span class=\"ref-norma\">Art.  43.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sólo podrá realizarse previa autorización del Ministerio del Interior o del órgano autonómico competente\"</span>Exige autorización previa del Ministerio del Interior o del órgano autonómico."}]},{"a":"Artículo 47","q":[{"i":"23-37","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de gestión de alarmas. Señale la opción incorrecta.","o":["Los servicios de gestión de alarmas, a cargo de operadores de seguridad, consistirán en la recepción, verificación no personal y, en su caso, transmisión de las señales de alarma, relativas a la seguridad y protección de personas y bienes a las Fuerzas y Cuerpos de Seguridad competentes.","Cuando los servicios se refirieran al análisis y monitorización de eventos de seguridad de la información y las comunicaciones, estarán sujetos a las especificaciones que reglamentariamente se determinen.","Los servicios de respuesta ante alarmas se prestarán por operadores de seguridad.","Las señales de alarma referidas a estos eventos deberán ser puestas, cuando corresponda, en conocimiento del órgano competente, por el propio usuario o por la empresa con la que haya contratado la seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los servicios de respuesta ante alarmas se prestarán por operadores de seguridad</mark></span><span class=\"ref-norma\">Art. 47 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de respuesta ante alarmas se prestarán por vigilantes de seguridad o, en su caso, por guardas rurales, y podrán comprender los siguientes servicios:\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-38","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de gestión de alarmas. Señale la opción incorrecta.","o":["Los servicios de gestión de alarmas, a cargo de operadores de seguridad, consistirán en la recepción, verificación no personal y, en su caso, transmisión de las señales de alarma, relativas a la seguridad y protección de personas y bienes a las Fuerzas y Cuerpos de Seguridad competentes.","Cuando los servicios se refirieran al análisis y monitorización de eventos de seguridad de la información y las comunicaciones, estarán sujetos a las especificaciones que reglamentariamente se determinen.","Los servicios de respuesta ante alarmas se prestarán por operadores de seguridad.","Las señales de alarma referidas a estos eventos deberán ser puestas, cuando corresponda, en conocimiento del órgano competente, por el propio usuario o por la empresa con la que haya contratado la seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los servicios de respuesta ante alarmas se prestarán por operadores de seguridad</mark></span><span class=\"ref-norma\">Art. 47 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de respuesta ante alarmas se prestarán por vigilantes de seguridad o, en su caso, por guardas rurales, y podrán comprender los siguientes servicios:\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1425","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de gestión de alarmas. Los servicios de gestión de alarmas, a cargo de operadores de seguridad, consistirán en la recepción, verificación no personal y, en su caso, transmisión de las señales de alarma, relativas a la seguridad y protección de personas y bienes, a:","o":["las Fuerzas y Cuerpos de Seguridad competentes.","los vigilantes de seguridad de la empresa.","los servicios de emergencia sanitaria.","los titulares de los establecimientos protegidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las Fuerzas y Cuerpos de Seguridad competentes</mark></span><span class=\"ref-norma\">Art.  47.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"transmisión de las señales de alarma, relativas a la seguridad y protección de personas y bienes a las Fuerzas y Cuerpos de Seguridad competentes\"</span>Transmiten a las Fuerzas y Cuerpos de Seguridad competentes."},{"i":"23-ia-1426","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de gestión de alarmas. Los servicios de respuesta ante alarmas se prestarán por:","o":["operadores de seguridad o vigilantes de seguridad, previo informe de la unidad policial competente.","vigilantes de seguridad exclusivamente.","técnicos acreditados o vigilantes de seguridad.","vigilantes de seguridad o, en su caso, por guardas rurales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">vigilantes de seguridad o, en su caso, por guardas rurales</mark></span><span class=\"ref-norma\">Art.  47.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de respuesta ante alarmas se prestarán por vigilantes de seguridad o, en su caso, por guardas rurales\"</span>Vigilantes de seguridad o, en su caso, guardas rurales."},{"i":"23-ia-1427","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de gestión de alarmas. Cuando los servicios se refirieran al análisis y monitorización de eventos de seguridad de la información y las comunicaciones, las señales de alarma referidas a estos eventos deberán ser puestas, cuando corresponda, en conocimiento del órgano competente, por:","o":["el operador de seguridad de la central de alarmas, sin perjuicio de lo previsto en la normativa vigente.","las Fuerzas y Cuerpos de Seguridad competentes.","el propio usuario o por la empresa con la que haya contratado la seguridad.","el director de seguridad de la empresa prestadora."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el propio usuario o por la empresa con la que haya contratado la seguridad</mark></span><span class=\"ref-norma\">Art.  47.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"por el propio usuario o por la empresa con la que haya contratado la seguridad\"</span>Las comunica el usuario o la empresa contratada."}]},{"a":"Artículo 66","q":[{"i":"23-39","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de la Administración General del Estado, ¿a quién le corresponde imponer las sanciones por infracciones graves en relación con los guardas rurales y centros de formación exclusivos para este personal?","o":["Al Director General de la Guardia Civil.","Al Ministerio del Interior.","Al Director General de la Policía.","Al Secretario de Estado de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Director General de la Guardia Civil</mark></span><span class=\"ref-norma\">Art. 66 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) Al Director General de la Guardia Civil, para imponer las sanciones por infracciones graves en relación con los guardas rurales y centros y cursos de formación exclusivos para este personal.\"</span>"},{"i":"23-44","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. En el ámbito de la Administración General del Estado, ¿a quién le corresponde imponer la sanción de extinción de las habilitaciones?","o":["Al Ministro del Interior.","Al Director General de la Policía.","Al Secretario de Estado de Seguridad.","Al Delegado del Gobierno en la Comunidad Autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Ministro del Interior</mark></span><span class=\"ref-norma\">Art. 66 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) Al Ministro del Interior, para imponer las sanciones de extinción de las autorizaciones, habilitaciones y declaraciones responsables.\"</span>"},{"i":"23-73","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de la Administración General del Estado, imponer las sanciones de extinción de las autorizaciones, habilitaciones y declaraciones responsables, le corresponderá:","o":["Al Ministro del Interior.","Al Director General de la Policía.","Al Secretario de Estado de Seguridad.","Al Delegado del Gobierno en la Comunidad Autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Ministro del Interior</mark></span><span class=\"ref-norma\">Art. 66 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) Al Ministro del Interior, para imponer las sanciones de extinción de las autorizaciones, habilitaciones y declaraciones responsables.\"</span>"},{"i":"23-74","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. ¿Qué recursos se podrán interponer contra las resoluciones sancionadoras de esta ley?","o":["Se podrán interponer los recursos previstos en la que se limite con contencioso administrativo.","Se podrán interponer los recursos previstos en la legislación de procedimiento administrativo y en la de la jurisdicción contencioso-administrativa.","Se podrán interponer los recursos previstos en la legislación de procedimiento administrativo.","Ninguna de las opciones anteriores es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se podrán interponer los recursos previstos en la legislación de procedimiento administrativo y en la de la jurisdicción contencioso-administrativa</mark></span><span class=\"ref-norma\">Art. 66 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Contra las resoluciones sancionadoras se podrán interponer los recursos previstos en la legislación de procedimiento administrativo y en la de la jurisdicción contenciosoadministrativa.\"</span>"},{"i":"23-141","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de la Administración General del Estado, la potestad sancionadora por infracciones leves en materia de seguridad privada corresponderá:","o":["Al Director General de la Policía.","A los Delegados y a los Subdelegados del Gobierno.","Al Secretario de Estado de Seguridad.","Al Director General de la Guardia Civil, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los Delegados y a los Subdelegados del Gobierno</mark></span><span class=\"ref-norma\">Art. 66.1 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"A los Delegados y a los Subdelegados del Gobierno, para imponer las sanciones por infracciones leves\"</span>"},{"i":"23-ia-1604","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de la Administración General del Estado, corresponde imponer las sanciones de extinción de las autorizaciones, habilitaciones y declaraciones responsables:","o":["al Secretario de Estado de Seguridad.","al Ministro del Interior.","al Director General de la Policía.","a los Delegados del Gobierno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Ministro del Interior</mark></span><span class=\"ref-norma\">Art.  66.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Al Ministro del Interior, para imponer las sanciones de extinción de las autorizaciones, habilitaciones y declaraciones responsables\"</span>Al Ministro del Interior."},{"i":"23-ia-1605","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de la Administración General del Estado, corresponde imponer las restantes sanciones por infracciones muy graves:","o":["al Secretario de Estado de Seguridad.","al Ministro del Interior.","al Director General de la Policía.","al Director General de la Guardia Civil."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Secretario de Estado de Seguridad</mark></span><span class=\"ref-norma\">Art.  66.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Al Secretario de Estado de Seguridad, para imponer las restantes sanciones por infracciones muy graves\"</span>Al Secretario de Estado de Seguridad."},{"i":"23-ia-1606","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de la Administración General del Estado, corresponde imponer las sanciones por infracciones graves:","o":["al Secretario de Estado de Seguridad.","al Director General de la Guardia Civil, en todo caso.","a los Delegados del Gobierno.","al Director General de la Policía."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al Director General de la Policía</mark></span><span class=\"ref-norma\">Art.  66.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Al Director General de la Policía, para imponer las sanciones por infracciones graves\"</span>Al Director General de la Policía."},{"i":"23-ia-1607","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. Cuando, en el curso de las inspecciones por parte de la Guardia Civil de los cursos para guardas rurales, impartidos por centros de formación no exclusivos de éstos, se detecten posibles infracciones, la sanción corresponderá:","o":["al Director General de la Guardia Civil.","al Secretario de Estado de Seguridad.","al Director General de la Policía.","al Subdelegado del Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Director General de la Policía</mark></span><span class=\"ref-norma\">Art.  66.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la sanción corresponderá al Director General de la Policía\"</span>Corresponde al Director General de la Policía."},{"i":"23-ia-1608","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. Corresponde al Director General de la Guardia Civil imponer las sanciones por infracciones graves en relación con:","o":["los vigilantes de explosivos y los centros de formación de éstos.","los guardas rurales y centros y cursos de formación exclusivos para este personal.","las armas y la custodia de las mismas por las empresas de seguridad, previo informe de la unidad policial competente.","los escoltas privados y las empresas de protección personal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los guardas rurales y centros y cursos de formación exclusivos para este personal</mark></span><span class=\"ref-norma\">Art.  66.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"para imponer las sanciones por infracciones graves en relación con los guardas rurales y centros y cursos de formación exclusivos para este personal\"</span>Guardas rurales y centros y cursos exclusivos para este personal."},{"i":"23-ia-1609","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. Corresponde imponer las sanciones por infracciones leves:","o":["a los Delegados y a los Subdelegados del Gobierno.","al Director General de la Policía.","al Secretario de Estado de Seguridad, sin perjuicio de lo previsto en la normativa vigente.","a los Jefes Superiores de Policía."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a los Delegados y a los Subdelegados del Gobierno</mark></span><span class=\"ref-norma\">Art.  66.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"A los Delegados y a los Subdelegados del Gobierno, para imponer las sanciones por infracciones leves\"</span>A los Delegados y Subdelegados del Gobierno."},{"i":"23-ia-1610","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. En el ámbito de las comunidades autónomas con competencia en materia de seguridad privada, la potestad sancionadora corresponderá:","o":["a los Consejeros competentes en materia de seguridad, en los términos que se determinen reglamentariamente.","a los Delegados del Gobierno en la comunidad.","al órgano que designe el Ministerio del Interior.","a los titulares de los órganos que se determinen en cada caso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a los titulares de los órganos que se determinen en cada caso</mark></span><span class=\"ref-norma\">Art.  66.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la potestad sancionadora corresponderá a los titulares de los órganos que se determinen en cada caso\"</span>A los titulares de los órganos que se determinen en cada caso."},{"i":"23-ia-1611","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencia sancionadora. Contra las resoluciones sancionadoras se podrán interponer:","o":["los recursos previstos en la Ley de Enjuiciamiento Criminal.","recursos de alzada ante el Ministro del Interior exclusivamente.","los recursos previstos en la legislación de procedimiento administrativo y en la de la jurisdicción contencioso-administrativa.","recurso de reposición, no siendo posible la vía contencioso-administrativa, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los recursos previstos en la legislación de procedimiento administrativo y en la de la jurisdicción contencioso-administrativa</mark></span><span class=\"ref-norma\">Art.  66.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se podrán interponer los recursos previstos en la legislación de procedimiento administrativo y en la de la jurisdicción contencioso-\"</span>Recursos administrativos y contencioso-administrativos."}]},{"a":"Artículo 38","q":[{"i":"23-41","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prestación de los servicios de seguridad privada. Los guardas rurales podrán desarrollar sus funciones sin necesidad de constituir o estar integrados en empresas de seguridad, prestando sus servicios directamente a los titulares de bienes y derechos que les puedan contratar, conforme a lo que se establezca reglamentariamente, cuando se trate de servicios de vigilancia y protección de: señale la INCORRECTA.","o":["Explotaciones agrícolas.","Fincas de caza, en cuanto a los distintos aspectos del régimen cinegético.","Zonas marítimas protegidas con fines pesqueros.","Establecimientos de acuicultura."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Establecimientos de acuicultura</mark></span><span class=\"ref-norma\">Art. 38.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"prestando sus servicios directamente a los titulares de bienes y derechos que les puedan contratar, conforme a lo que se establezca reglamentariamente, cuando se trate de servicios de vigilancia y protección de explotaciones agrícolas, fincas de caza, en cuanto a los distintos aspectos del régimen cinegético, y zonas marítimas protegidas con fines pesqueros\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-72","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cuál de las siguientes opciones sobre la forma de prestación de los servicios de seguridad privada es INCORRECTA?","o":["Los servicios de seguridad privada se prestarán únicamente por empresas de seguridad privada, despachos de detectives y personal de seguridad privada.","Los vigilantes de seguridad, vigilantes de explosivos, escoltas privados y jefes de seguridad desempeñarán sus funciones profesionales fuera de las empresas de seguridad que les tengan contratados.","Reglamentariamente se establecerán las condiciones y requisitos para la subcontratación de servicios de seguridad privada.","Los directores de seguridad de las empresas de seguridad privada y de las entidades obligadas a disponer de esta figura, conforme a lo dispuesto en el artículo 36, desempeñarán sus funciones integrados en las plantillas de dichas empresas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los vigilantes de seguridad, vigilantes de explosivos, escoltas privados y jefes de seguridad desempeñarán sus funciones profesionales fuera de las empresas de seguridad que les tengan contratados</mark></span><span class=\"ref-norma\">Art. 38 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los vigilantes de seguridad, vigilantes de explosivos, escoltas privados y jefes de seguridad desempeñarán sus funciones profesionales integrados en las empresas de seguridad que les tengan contratados.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1349","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prestación de los servicios de seguridad privada. Los vigilantes de seguridad, vigilantes de explosivos, escoltas privados y jefes de seguridad desempeñarán sus funciones profesionales:","o":["integrados en las empresas de seguridad que les tengan contratados.","directamente para los titulares de los bienes protegidos.","integrados en las empresas o entidades usuarias de seguridad.","a través de los despachos de seguridad que les presten servicios, salvo que la autoridad judicial disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">integrados en las empresas de seguridad que les tengan contratados</mark></span><span class=\"ref-norma\">Art.  38.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"desempeñarán sus funciones profesionales integrados en las empresas de seguridad que les tengan contratados\"</span>Integrados en las empresas de seguridad que les contratan."},{"i":"23-ia-1350","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prestación de los servicios de seguridad privada. Los guardas rurales podrán desarrollar sus funciones sin necesidad de constituir o estar integrados en empresas de seguridad, prestando sus servicios directamente a:","o":["las Administraciones públicas titulares de los terrenos, previa autorización, previo informe de la unidad policial competente.","las empresas titulares de explotaciones agrícolas exclusivamente.","los propietarios de las fincas con la autorización de la Guardia Civil.","los titulares de bienes y derechos que les puedan contratar, conforme a lo que se establezca reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los titulares de bienes y derechos que les puedan contratar, conforme a lo que se establezca reglamentariamente</mark></span><span class=\"ref-norma\">Art.  38.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"prestando sus servicios directamente a los titulares de bienes y derechos que les puedan contratar, conforme a lo que se establezca reglamentariamente\"</span>Prestan servicios directamente a los titulares de bienes y derechos que les contraten."},{"i":"23-ia-1351","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prestación de los servicios de seguridad privada. Los detectives privados ejercerán sus funciones profesionales:","o":["integrados en empresas de seguridad con autorización para investigación, sin perjuicio de lo previsto en la normativa vigente.","directamente ante los clientes que les contraten.","a través de los despachos de detectives para los que presten sus servicios.","a título individual o integrados en empresas de seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a través de los despachos de detectives para los que presten sus servicios</mark></span><span class=\"ref-norma\">Art.  38.7 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los detectives privados ejercerán sus funciones profesionales a través de los despachos de detectives para los que presten sus servicios\"</span>A través de los despachos de detectives."}]},{"a":"Artículo 72","q":[{"i":"23-46","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿De cuánto no excederá la cuantía de las multas coercitivas?","o":["De 6.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","De 3.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","De 4.000 euros, pero podrá aumentarse sucesivamente en el 75 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","De 2.000 euros, pero podrá aumentarse sucesivamente en el 75 por 100 de la cantidad anterior en casos de reiteración del incumplimiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De 6.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento</mark></span><span class=\"ref-norma\">Art. 72 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La cuantía de estas multas no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.\"</span>"},{"i":"23-62","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Multas coercitivas. La cuantía de las multas coercitivas no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en el:","o":["25 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","10 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","20 por 100 de la cantidad anterior en casos de reiteración del incumplimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento</mark></span><span class=\"ref-norma\">Art. 72 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La cuantía de estas multas no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.\"</span>"},{"i":"23-126","p":"Ley 5/2014 de 4 de Abril, de Seguridad Privada. Multas Coercitivas. La cuantía de estas multas no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en el _____ de la cantidad anterior en casos de reiteración del incumplimiento.","o":["50%","100%","25%","75%"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">50%</mark></span><span class=\"ref-norma\">Art. 72 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La cuantía de estas multas no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.\"</span>"},{"i":"23-142","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Multas coercitivas. Para lograr el cumplimiento de las resoluciones sancionadoras, las autoridades competentes podrán imponer, de acuerdo con lo establecido en la legislación de procedimiento administrativo:","o":["Multas coercitivas.","Multas accesorias.","Medidas cautelares de carácter definitivo.","Recargos de apremio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Multas coercitivas</mark></span><span class=\"ref-norma\">Art. 72.1 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"podrán imponer multas coercitivas, de acuerdo con lo establecido en la legislación de procedimiento administrativo\"</span>"},{"i":"23-ia-1624","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Multas coercitivas. Para lograr el cumplimiento de las resoluciones sancionadoras, las autoridades competentes podrán imponer multas coercitivas, de acuerdo con lo establecido en:","o":["el Reglamento de Seguridad Privada.","la legislación de procedimiento administrativo.","la normativa de las Fuerzas y Cuerpos de Seguridad.","la legislación de ejecución de sanciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la legislación de procedimiento administrativo</mark></span><span class=\"ref-norma\">Art.  72.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrán imponer multas coercitivas, de acuerdo con lo establecido en la legislación de procedimiento administrativo\"</span>Conforme a la legislación de procedimiento administrativo."},{"i":"23-ia-1625","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Multas coercitivas. La cuantía de las multas coercitivas no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en:","o":["el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento.","el 25 por 100 de la cantidad anterior en casos de reiteración del incumplimiento, en los términos que se determinen reglamentariamente.","el 50 por 100 de la sanción principal en casos de reincidencia.","el 100 por 100 de la cantidad anterior en casos de reiteración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento</mark></span><span class=\"ref-norma\">Art.  72.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no excederá de 6.000 euros, pero podrá aumentarse sucesivamente en el 50 por 100 de la cantidad anterior en casos de reiteración del incumplimiento\"</span>Hasta 6.000 euros, aumentables en el 50 por 100 de la anterior."},{"i":"23-ia-1626","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Multas coercitivas. Las multas coercitivas serán independientes de las sanciones pecuniarias que puedan imponerse y:","o":["alternativas a ellas.","subsidiarias de ellas.","complementarias solo en infracciones muy graves.","compatibles con ellas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">compatibles con ellas</mark></span><span class=\"ref-norma\">Art.  72.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las multas coercitivas serán independientes de las sanciones pecuniarias que puedan imponerse y compatibles con ellas\"</span>Independientes y compatibles."},{"i":"23-ia-1627","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Comercialización de productos. En la comercialización de productos provenientes de Estados miembros de la Unión Europea, del Espacio Económico Europeo o de cualquier tercer país con el que la Unión Europea tenga un acuerdo de asociación, se atenderá a los estándares previstos por:","o":["los organismos de normalización designados por el Ministerio del Interior en cada caso, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","la Comisión Europea, mediante certificación única para toda la Unión.","las entidades de certificación acreditadas que ofrezcan, a través de su administración pública competente, garantías técnicas profesionales y de independencia e imparcialidad equivalentes a las exigidas por la legislación española.","los laboratorios autorizados por la Dirección General de la Policía."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las entidades de certificación acreditadas que ofrezcan, a través de su administración pública competente, garantías técnicas profesionales y de independencia e imparcialidad equivalentes a las exigidas por la legislación española</mark></span><span class=\"ref-norma\">Disp. adicional 1.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se atenderá a los estándares previstos por las entidades de certificación acreditadas que ofrezcan, a través de su administración pública competente, garantías técnicas profesionales y de independencia e imparcialidad equivalentes a las exigidas por la legislación española\"</span>Estándares de entidades de certificación acreditadas con garantías equivalentes."},{"i":"23-ia-1628","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Contratación de servicios de seguridad privada por las administraciones públicas. Los órganos de contratación de las administraciones públicas podrán establecer condiciones especiales de ejecución de los contratos de servicios de seguridad relacionadas con:","o":["la formación del personal de seguridad adscrito a los servicios contratados.","el cumplimiento de las obligaciones laborales por parte de las empresas de seguridad privada contratistas.","la adopción de medidas de seguridad electrónica en los edificios públicos.","el cumplimiento de las obligaciones tributarias de las empresas contratistas, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el cumplimiento de las obligaciones laborales por parte de las empresas de seguridad privada contratistas</mark></span><span class=\"ref-norma\">Disp. adicional 2.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrán establecer condiciones especiales de ejecución de los contratos de servicios de seguridad relacionadas con el cumplimiento de las obligaciones laborales por parte de las empresas de seguridad privada contratistas\"</span>Con el cumplimiento de las obligaciones laborales de las contratistas."},{"i":"23-ia-1629","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Cooperación administrativa. Los órganos competentes en materia policial, tributaria, laboral y de seguridad social establecerán mecanismos de información, control e inspección conjunta en relación con las empresas de seguridad privada para evitar:","o":["el fraude y el intrusismo.","el fraude y la competencia desleal.","el intrusismo y el incumplimiento de contratos.","la competencia desleal y la economía sumergida."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el fraude y el intrusismo</mark></span><span class=\"ref-norma\">Disp. adicional 3.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"establecerán mecanismos de información, control e inspección conjunta en relación con las empresas de seguridad privada para evitar el fraude y el intrusismo\"</span>Para evitar el fraude y el intrusismo."},{"i":"23-ia-1630","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Habilitaciones profesionales anteriores a la entrada en vigor de esta ley. Las habilitaciones del personal de seguridad privada obtenidas antes de la entrada en vigor de la ley mantendrán su validez:","o":["hasta su convalidación en el plazo de un año.","previo canje por la tarjeta de identidad profesional.","durante dos años, tras los cuales deberán renovarse.","sin necesidad de convalidación o canje alguno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sin necesidad de convalidación o canje alguno</mark></span><span class=\"ref-norma\">Disp. transitoria 1.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"mantendrán su validez sin necesidad de convalidación o canje alguno\"</span>Sin convalidación ni canje."},{"i":"23-ia-1631","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Habilitaciones profesionales anteriores a la entrada en vigor de esta ley. Las habilitaciones correspondientes a los guardas particulares del campo se entenderán hechas a la nueva categoría de:","o":["guardas de caza.","vigilantes de seguridad.","guardas rurales.","guardapescas marítimos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">guardas rurales</mark></span><span class=\"ref-norma\">Disp. transitoria 1.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las habilitaciones correspondientes a los guardas particulares del campo se entenderán hechas a la nueva categoría de guardas rurales\"</span>A la categoría de guardas rurales."},{"i":"23-ia-1632","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Personal de centrales receptoras de alarmas. Quienes a la entrada en vigor de la ley estuvieran desempeñando su actividad en centrales receptoras de alarmas podrán continuar desarrollando sus funciones:","o":["previa obtención de la acreditación de operador de seguridad en un año.","sin necesidad de obtener ninguna acreditación específica.","previa superación de las pruebas de comprobación en seis meses.","hasta la renovación de su contrato con la central."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin necesidad de obtener ninguna acreditación específica</mark></span><span class=\"ref-norma\">Disp. transitoria 2.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrán continuar desarrollando sus funciones sin necesidad de obtener ninguna acreditación específica\"</span>Sin necesidad de acreditación específica."},{"i":"23-ia-1633","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Plazos de adecuación. Los plazos de adecuación, computados a partir de la entrada en vigor de la ley, son de dos años respecto a los requisitos nuevos de las empresas de seguridad privada y de los despachos de detectives y de:","o":["diez años para las medidas de seguridad electrónicas de las empresas de seguridad, de los establecimientos obligados y de las instalaciones de los usuarios no obligados.","cinco años para las medidas de seguridad electrónicas de las empresas de seguridad y de los establecimientos obligados, salvo que la autoridad judicial disponga otra cosa.","diez años para las medidas de seguridad física de las empresas de seguridad y de los establecimientos obligados.","tres años para las medidas de seguridad electrónicas de los establecimientos obligados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez años para las medidas de seguridad electrónicas de las empresas de seguridad, de los establecimientos obligados y de las instalaciones de los usuarios no obligados</mark></span><span class=\"ref-norma\">Disp. transitoria 4.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Diez años para las medidas de seguridad electrónicas de las empresas de seguridad, de los establecimientos obligados y de las instalaciones de los usuarios no obligados\"</span>Diez años para las medidas de seguridad electrónicas."},{"i":"23-ia-1635","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Plazos de adecuación. Las medidas de seguridad física instaladas con anterioridad a la entrada en vigor de la ley tendrán una validez indefinida, hasta el final de su vida útil; no obstante, deberán ser actualizadas en caso de:","o":["cambio de titularidad del establecimiento protegido.","resultar obsoletas a juicio de las Fuerzas y Cuerpos de Seguridad, previo informe de la unidad policial competente.","resultar afectadas por reformas estructurales de los sistemas de seguridad de los que formen parte.","transcurrir diez años desde la entrada en vigor de la ley."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">resultar afectadas por reformas estructurales de los sistemas de seguridad de los que formen parte</mark></span><span class=\"ref-norma\">Disp. transitoria 4.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"deberán ser actualizadas en caso de resultar afectadas por reformas estructurales de los sistemas de seguridad de los que formen parte\"</span>Si resultan afectadas por reformas estructurales de los sistemas."},{"i":"23-ia-1636","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividad de planificación y asesoramiento. Las empresas de seguridad autorizadas e inscritas únicamente para la actividad de planificación y asesoramiento de la Ley 23/1992 dispondrán de un plazo, desde la entrada en vigor de la ley, para solicitar autorización para cualquiera de las actividades de seguridad privada, excepto la investigación privada, de:","o":["seis meses, sin perjuicio de lo previsto en la normativa vigente.","tres meses.","un año.","dos meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres meses</mark></span><span class=\"ref-norma\">Disp. transitoria 5.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"dispondrán de un plazo de tres meses, desde la entrada en vigor de esta ley, para solicitar autorización\"</span>Tres meses."},{"i":"23-ia-1637","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividad de planificación y asesoramiento. Las empresas de seguridad que, transcurrido el plazo de tres meses, no hubieran solicitado la autorización para actividades de seguridad privada, serán:","o":["dadas de baja de oficio, cancelándose su inscripción en el Registro Nacional de Seguridad Privada y, en su caso, en el registro autonómico correspondiente.","sancionadas por infracción leve y dadas de baja de oficio, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","inscritas como empresas de actividades compatibles.","dadas de baja a solicitud de parte."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dadas de baja de oficio, cancelándose su inscripción en el Registro Nacional de Seguridad Privada y, en su caso, en el registro autonómico correspondiente</mark></span><span class=\"ref-norma\">Disp. transitoria 5.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"serán dadas de baja de oficio, cancelándose su inscripción en el Registro Nacional de Seguridad Privada y, en su caso, en el registro autonómico correspondiente\"</span>Baja de oficio y cancelación de la inscripción."},{"i":"23-ia-1638","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividad de planificación y asesoramiento. Las empresas de seguridad que, a la entrada en vigor de la ley, estuvieran autorizadas para planificación y asesoramiento y, además, para otra actividad, dispondrán de un plazo para adecuar los importes del seguro de responsabilidad civil u otra garantía financiera y del aval o seguro de caución de:","o":["tres meses, desde la entrada en vigor de la ley.","dos años, desde la entrada en vigor de la ley.","seis meses, desde la entrada en vigor de la ley.","un año, desde la entrada en vigor de la ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año, desde la entrada en vigor de la ley</mark></span><span class=\"ref-norma\">Disp. transitoria 5.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"dispondrán de un plazo de un año, desde la entrada en vigor de esta ley, para adecuar los respectivos importes del seguro de responsabilidad civil u otra garantía financiera, así como del aval o seguro de caución\"</span>Un año."},{"i":"23-ia-1639","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Derogación normativa. La Ley 5/2014 deroga la Ley 23/1992, de 30 de julio, de Seguridad Privada. El Reglamento de Seguridad Privada, aprobado por Real Decreto 2364/1994, y el resto de la normativa de desarrollo:","o":["quedan derogados con la entrada en vigor de la nueva ley.","mantienen su vigencia hasta la aprobación del nuevo reglamento, previo informe de la unidad policial competente.","mantendrán su vigencia en lo que no contravenga a la nueva ley.","mantienen su vigencia durante dos años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">mantendrán su vigencia en lo que no contravenga a la nueva ley</mark></span><span class=\"ref-norma\">Disp. derogatoria única · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"mantendrán su vigencia en lo que no contravenga a esta ley\"</span>Siguen vigentes en lo que no contravenga a la nueva ley."},{"i":"23-ia-1640","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Título competencial. La Ley de Seguridad Privada se dicta al amparo de la competencia exclusiva del Estado en materia de:","o":["seguridad ciudadana.","seguridad pública.","orden público.","defensa y Fuerzas Armadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seguridad pública</mark></span><span class=\"ref-norma\">Disp. final 1.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que atribuye al Estado la competencia exclusiva en materia de seguridad pública\"</span>Seguridad pública."},{"i":"23-ia-1641","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Desarrollo normativo. El Gobierno, a propuesta del Ministro del Interior, dictará las disposiciones reglamentarias precisas para el desarrollo de la ley. Se faculta asimismo al Gobierno para actualizar la cuantía de las multas, de acuerdo con:","o":["las variaciones del indicador público de renta de efectos múltiples.","las variaciones del índice de precios al consumo.","las variaciones del salario mínimo interprofesional, sin perjuicio de lo previsto en la normativa vigente.","los criterios que fije el Ministerio de Hacienda."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las variaciones del indicador público de renta de efectos múltiples</mark></span><span class=\"ref-norma\">Disp. final 3.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"para actualizar la cuantía de las multas, de acuerdo con las variaciones del indicador público de renta de efectos múltiples\"</span>Según el IPREM."},{"i":"23-ia-1642","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Entrada en vigor. La Ley de Seguridad Privada entró en vigor:","o":["al día siguiente de su publicación en el «Boletín Oficial del Estado».","a los tres meses de su publicación en el «Boletín Oficial del Estado».","a los veinte días de su publicación en el «Boletín Oficial del Estado».","a los dos meses de su publicación en el «Boletín Oficial del Estado»."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a los dos meses de su publicación en el «Boletín Oficial del Estado»</mark></span><span class=\"ref-norma\">Disp. final 4.ª · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Esta ley entrará en vigor a los dos meses de su publicación en el «Boletín Oficial del Estado»\"</span>A los dos meses de su publicación."}]},{"a":"Artículo 26","q":[{"i":"23-47","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Profesiones de seguridad privada: señale la INCORRECTA.","o":["Para habilitarse como vigilante de explosivos será necesario haber obtenido previamente la habilitación como vigilante de seguridad.","Para habilitarse como guarda de caza o pesca marítima será necesario haberlo hecho previamente como vigilante de seguridad.","Para la prestación de servicios en infraestructuras críticas y en aquellos que tengan el carácter de esenciales para la comunidad, así como en aquellos otros que excepcionalmente lo requieran en función de sus características específicas, se podrá incrementar reglamentariamente la exigencia formativa al personal de seguridad privada encargado de su realización.","Reglamentariamente se regulará la obtención por el personal de seguridad privada de habilitaciones adicionales a las ya adquiridas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Para habilitarse como guarda de caza o pesca marítima será necesario haberlo hecho previamente como vigilante de seguridad</mark></span><span class=\"ref-norma\">Art. 26 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Para habilitarse como guarda de caza o guardapesca marítimo será necesario haberlo hecho previamente como guarda rural.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-78","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿Cómo se regulará la obtención por el personal de seguridad privada de habilitaciones adicionales a las ya adquiridas?","o":["Mediante real decreto ley.","Mediante ley.","Por orden ministerial.","Reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Reglamentariamente</mark></span><span class=\"ref-norma\">Art. 26 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Reglamentariamente se regulará la obtención por el personal de seguridad privada de habilitaciones adicionales a las ya adquiridas.\"</span>"},{"i":"23-102","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Para habilitarse como vigilante de explosivos será necesario:","o":["Haber obtenido previamente la declaración responsable como vigilante de seguridad.","Haber obtenido previamente la habilitación como vigilante de seguridad.","Incrementar reglamentariamente la exigencia de su formación","Una habilitación adicional o la ya adquirida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Haber obtenido previamente la habilitación como vigilante de seguridad</mark></span><span class=\"ref-norma\">Art. 26 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Para habilitarse como vigilante de explosivos será necesario haber obtenido previamente la habilitación como vigilante de seguridad.\"</span>"},{"i":"23-106","p":"Ley de Seguridad Privada. Únicamente puede ejercer funciones de seguridad privada el personal de seguridad privada; que estará integrado, entre otros, por:","o":["Los vigilantes de seguridad y su especialidad de vigilantes de explosivos.","Los detectives privados.","Los guardas rurales y sus especialidades de guardas de caza y guardapescas marítimos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 26 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Únicamente puede ejercer funciones de seguridad privada el personal de seguridad privada, que estará integrado por los vigilantes de seguridad y su especialidad de vigilantes de explosivos, los escoltas privados, los guardas rurales y sus especialidades de guardas de caza y guardapescas marítimos, los jefes de seguridad, los directores de seguridad y los detectives privados.\"</span>"},{"i":"23-ia-1244","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Profesiones de seguridad privada. Únicamente puede ejercer funciones de seguridad privada el personal de seguridad privada, integrado por los vigilantes de seguridad y su especialidad de vigilantes de explosivos, los escoltas privados, los guardas rurales y sus especialidades de guardas de caza y guardapescas marítimos, los jefes de seguridad, los directores de seguridad y:","o":["los operadores de seguridad.","los detectives privados.","los instructores de tiro.","los ingenieros y técnicos de seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los detectives privados</mark></span><span class=\"ref-norma\">Art.  26.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"los jefes de seguridad, los directores de seguridad y los detectives privados\"</span>Cierran la lista los detectives privados."},{"i":"23-ia-1245","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Profesiones de seguridad privada. Para habilitarse como vigilante de explosivos será necesario haber obtenido previamente la habilitación como:","o":["vigilante de seguridad.","guarda rural.","escolta privado.","jefe de seguridad, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">vigilante de seguridad</mark></span><span class=\"ref-norma\">Art.  26.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Para habilitarse como vigilante de explosivos será necesario haber obtenido previamente la habilitación como vigilante de seguridad\"</span>Primero vigilante de seguridad."},{"i":"23-ia-1246","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Profesiones de seguridad privada. Para habilitarse como guarda de caza o guardapesca marítimo será necesario haberlo hecho previamente como:","o":["vigilante de seguridad.","vigilante de explosivos.","escolta privado.","guarda rural."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">guarda rural</mark></span><span class=\"ref-norma\">Art.  26.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Para habilitarse como guarda de caza o guardapesca marítimo será necesario haberlo hecho previamente como guarda rural\"</span>Primero guarda rural."}]},{"a":"Artículo 1","q":[{"i":"23-52","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Esta ley se dicta al amparo de lo dispuesto la Constitución, ¿a quién atribuye la competencia exclusiva en materia de seguridad pública?","o":["Al Estado y a las Comunidades Autónomas.","Al Estado.","A las Comunidades Autonómicas.","Ninguna de las opciones anteriores es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Estado</mark></span><span class=\"ref-norma\">Disposición final primera · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Esta ley se dicta al amparo de lo dispuesto en el artículo 149.1.29.ª de la Constitución, que atribuye al Estado la competencia exclusiva en materia de seguridad pública.\"</span>"},{"i":"23-99","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las actividades y servicios de seguridad privada tendrán la consideración respecto de la seguridad pública de:","o":["Complementarias.","Principales.","Subordinadas.","A y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y C son correctas</mark></span><span class=\"ref-norma\">Art. 1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública.\"</span>"},{"i":"23-ia-1013","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Objeto. Esta ley tiene por objeto regular la realización y la prestación por personas privadas, físicas o jurídicas, de actividades y servicios de seguridad privada, que son contratados, voluntaria u obligatoriamente, para la protección de personas y bienes. Todas estas actividades tienen la consideración de:","o":["complementarias y subordinadas respecto de la seguridad pública.","subsidiarias y colaboradoras respecto de la seguridad pública.","complementarias y coordinadas respecto de la seguridad pública.","auxiliares y subordinadas respecto de las Fuerzas y Cuerpos de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">complementarias y subordinadas respecto de la seguridad pública</mark></span><span class=\"ref-norma\">Art.  1.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública\"</span>Son complementarias y subordinadas respecto de la seguridad pública."},{"i":"23-ia-1014","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Objeto. La ley establece, en beneficio de la seguridad pública, el marco para la más eficiente __________ de los servicios de seguridad privada con los de las Fuerzas y Cuerpos de Seguridad, de los que son complementarios:","o":["colaboración, sin perjuicio de lo previsto en la normativa vigente.","integración","cooperación","coordinación"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">coordinación</mark></span><span class=\"ref-norma\">Art.  1.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"establece el marco para la más eficiente coordinación de los servicios de seguridad privada con los de las Fuerzas y Cuerpos de Seguridad, de los que son complementarios\"</span>Se trata de la más eficiente coordinación."},{"i":"23-ia-1205","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Desarrollo de actividades. Las empresas de seguridad privada únicamente podrán prestar servicios sobre las actividades de seguridad privada, excepto la de:","o":["investigación privada.","instalación y mantenimiento de sistemas de seguridad.","depósito y transporte de explosivos.","explotación de centrales receptoras de alarmas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">investigación privada</mark></span><span class=\"ref-norma\">Art.  17.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"excepto la contemplada en el párrafo h) del mismo\"</span>Se exceptúa la investigación privada, reservada a los despachos de detectives."}]},{"a":"Artículo 44","q":[{"i":"23-53","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los servicios de depósito de seguridad de explosivos, armas, cartuchería metálica, sustancias, materias, mercancías y cualesquiera objetos que por su peligrosidad precisen de vigilancia y protección especial estarán a cargo de vigilantes de explosivos y se prestarán obligatoriamente cuando:","o":["Precisen de vigilancia, cuidado y protección especial, de acuerdo con la normativa general de cada materia.","Así lo dispongan las autoridades competentes en atención a los antecedentes y circunstancias relacionadas con dichos objetos o sustancias.","Así lo disponga el Estado en atención a los antecedentes y circunstancias relacionadas con dichos objetos o sustancias.","Ninguna de las opciones anteriores es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Así lo dispongan las autoridades competentes en atención a los antecedentes y circunstancias relacionadas con dichos objetos o sustancias</mark></span><span class=\"ref-norma\">Art. 44 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los servicios de depósito de seguridad referidos a la actividad contemplada en el artículo 5.1.d), estarán a cargo de vigilantes de explosivos y se prestarán obligatoriamente cuando precisen de vigilancia, cuidado y protección especial, de acuerdo con la normativa específica de cada materia o así lo dispongan las autoridades competentes en atención a los antecedentes y circunstancias relacionadas con dichos objetos o sustancias.\"</span>"},{"i":"23-ia-1420","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de depósito de seguridad. Los servicios de depósito de seguridad referidos a monedas, billetes, títulos-valores, joyas, metales preciosos, antigüedades y obras de arte estarán a cargo de:","o":["vigilantes de explosivos.","vigilantes de seguridad.","escoltas privados.","guardas rurales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">vigilantes de seguridad</mark></span><span class=\"ref-norma\">Art.  44.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"estarán a cargo de vigilantes de seguridad y se prestarán obligatoriamente cuando los objetos en cuestión alcancen las cuantías que reglamentariamente se establezcan\"</span>Vigilantes de seguridad."},{"i":"23-ia-1421","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de depósito de seguridad. Los servicios de depósito de seguridad de explosivos, armas, cartuchería metálica y sustancias peligrosas estarán a cargo de:","o":["vigilantes de explosivos.","vigilantes de seguridad, previo informe de la unidad policial competente.","jefes de seguridad.","guardas rurales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">vigilantes de explosivos</mark></span><span class=\"ref-norma\">Art.  44.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"estarán a cargo de vigilantes de explosivos y se prestarán obligatoriamente cuando precisen de vigilancia, cuidado y protección especial\"</span>Vigilantes de explosivos."},{"i":"23-ia-1422","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de transporte de seguridad. Los servicios de transporte y distribución de objetos y sustancias de depósito se llevarán a cabo mediante vehículos acondicionados especialmente para cada tipo de transporte u otros elementos de seguridad específicos homologados, y consistirán en su traslado material y su protección durante el mismo, por:","o":["escoltas privados o vigilantes de seguridad, respectivamente, sin perjuicio de lo previsto en la normativa vigente.","vigilantes de seguridad exclusivamente.","vigilantes de explosivos y guardas rurales, respectivamente.","vigilantes de seguridad o vigilantes de explosivos, respectivamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">vigilantes de seguridad o vigilantes de explosivos, respectivamente</mark></span><span class=\"ref-norma\">Art.  45 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"por vigilantes de seguridad o vigilantes de explosivos, respectivamente\"</span>Vigilantes de seguridad o de explosivos, según el objeto."}]},{"a":"Artículo 6","q":[{"i":"23-55","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. Quedan fuera del ámbito de aplicación de esta ley, sin perjuicio de la normativa específica que pudiera resultar de aplicación, especialmente en lo que se refiere a la homologación de productos, las siguientes actividades: señale la opción INCORRECTA.","o":["La fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad.","La fabricación, comercialización, venta o entrega de equipos técnicos de seguridad electrónica, así como la instalación o mantenimiento de dichos equipos siempre que no estén conectados a centrales de alarma o centros de control o de videovigilancia.","La conexión a centrales receptoras de alarmas de sistemas de prevención o protección contra incendios o de alarmas de tipo técnico o asistencial, o de sistemas o servicios de control o mantenimiento.","La planificación, consultoría y asistencia en materia de actuaciones de seguridad privada, que consistirán en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a los riesgos humanos, así como en asesorar sobre la prestación de los servicios de seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La planificación, consultoría y asistencia en materia de actuaciones de seguridad privada, que consistirán en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a los riesgos humanos, así como en asesorar sobre la prestación de los servicios de seguridad</mark></span><span class=\"ref-norma\">Art. 6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) La planificación, consultoría y asesoramiento en materia de actividades de seguridad privada, que consistirá en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a todo tipo de riesgos, así como en auditorías sobre la prestación de los servicios de seguridad.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-66","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Quedan fuera del ámbito de aplicación de esta ley, sin perjuicio de la normativa específica que pudiera resultar de aplicación, especialmente en lo que se refiere a la homologación de productos, las siguientes actividades: señale la INCORRECTA:","o":["La fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad.","La fabricación, comercialización, venta o entrega de equipos técnicos de seguridad electrónica, así como la instalación o mantenimiento de dichos equipos siempre que no estén conectados a centrales de alarma o centros de control o de videovigilancia.","La conexión a centrales receptoras de alarmas de sistemas de prevención o protección contra incendios o de alarmas de tipo técnico o asistencial, o de sistemas o servicios de control o mantenimiento.","La planificación, consultoría y asistencia en materia de actuaciones de seguridad privada, que consistirán en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a los riesgos humanos, así como en asesorar sobre la prestación de los servicios de seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La planificación, consultoría y asistencia en materia de actuaciones de seguridad privada, que consistirán en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a los riesgos humanos, así como en asesorar sobre la prestación de los servicios de seguridad</mark></span><span class=\"ref-norma\">Art. 6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) La planificación, consultoría y asesoramiento en materia de actividades de seguridad privada, que consistirá en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a todo tipo de riesgos, así como en auditorías sobre la prestación de los servicios de seguridad.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-85","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Quedan fuera del ámbito de aplicación de esta ley, a no ser que impliquen la asunción o realización de servicios o funciones de seguridad privada, y se regirán por las normas sectoriales que les sean de aplicación en cada caso, los servicios y funciones de información o de control en los accesos a instalaciones, comprendiendo: señale la INCORRECTA.","o":["El cuidado y custodia de las llaves, la apertura y cierre de puertas.","La ayuda en el acceso de personas o vehículos.","La realización de funciones reservadas al personal de seguridad privada, como portar armas o medios de defensa.","La ejecución de tareas auxiliares o subordinadas de ayuda o socorro."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La realización de funciones reservadas al personal de seguridad privada, como portar armas o medios de defensa</mark></span><span class=\"ref-norma\">Art. 6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El personal no habilitado que preste los servicios o funciones comprendidos en el apartado anterior, en ningún caso podrá ejercer función alguna de las reservadas al personal de seguridad privada, ni portar ni usar armas ni medios de defensa, ni utilizar distintivos, uniformes o medios que puedan confundirse con los previstos para dicho personal.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-136","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. Quedan fuera del ámbito de aplicación de la ley, sin perjuicio de la normativa específica que pudiera resultar de aplicación, especialmente en lo que se refiere a la homologación de productos, las siguientes actividades:","o":["La instalación y mantenimiento de equipos de seguridad conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia, en los términos que determine la ley orgánica correspondiente.","La explotación de centrales para la conexión, recepción y verificación de las señales de alarma.","La fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad.","El depósito, custodia y recuento de monedas y billetes, títulos-valores, joyas y metales preciosos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad</mark></span><span class=\"ref-norma\">Art. 6.1 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"La fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad\"</span>"},{"i":"23-139","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Servicios de videovigilancia. La monitorización, grabación, tratamiento y registro de imágenes y sonidos por parte de los sistemas de videovigilancia estará sometida a lo previsto en la normativa en materia de protección de datos de carácter personal, y especialmente a los principios de:","o":["Proporcionalidad, necesidad e injerencia mínima.","Legalidad, idoneidad e intervención mínima.","Proporcionalidad, idoneidad y reserva profesional, salvo que el órgano competente acuerde otra cosa de forma motivada.","Proporcionalidad, idoneidad e intervención mínima."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Proporcionalidad, idoneidad e intervención mínima</mark></span><span class=\"ref-norma\">Art. 42.5 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"y especialmente a los principios de proporcionalidad, idoneidad e intervención mínima\"</span>"},{"i":"23-ia-1101","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. Quedan fuera del ámbito de aplicación de la Ley de Seguridad Privada, sin perjuicio de la normativa específica, entre otras actividades:","o":["la fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad.","la instalación o mantenimiento de sistemas de seguridad conectados a centrales receptoras de alarmas, en los términos que se determinen reglamentariamente.","la conexión a centrales receptoras de alarmas de sistemas de videovigilancia.","la explotación de centrales de recepción y verificación de señales de alarma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad</mark></span><span class=\"ref-norma\">Art.  6.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de cerrajería de seguridad\"</span>La cerrajería de seguridad queda fuera; la conexión a centrales de alarmas es actividad de seguridad privada."},{"i":"23-ia-1102","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. La fabricación, comercialización, venta o entrega de equipos técnicos de seguridad electrónica, así como su instalación o mantenimiento, quedan fuera del ámbito de la ley siempre que no estén conectados a:","o":["centrales de alarma de uso propio o a las Fuerzas y Cuerpos de Seguridad.","sistemas de control de acceso o de videovigilancia.","redes de comunicaciones o centros de control de la empresa.","centrales de alarma o centros de control o de videovigilancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">centrales de alarma o centros de control o de videovigilancia</mark></span><span class=\"ref-norma\">Art.  6.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"siempre que no estén conectados a centrales de alarma o centros de control o de videovigilancia\"</span>El límite es la conexión a centrales de alarma o centros de control o de videovigilancia."},{"i":"23-ia-1103","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. La planificación, consultoría y asesoramiento en materia de actividades de seguridad privada consistirá en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad referidos a la protección frente a todo tipo de riesgos, así como en:","o":["inspecciones sobre el cumplimiento de las medidas de seguridad.","informes periciales sobre los servicios de seguridad.","auditorías sobre la prestación de los servicios de seguridad.","certificaciones de los servicios de seguridad prestados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">auditorías sobre la prestación de los servicios de seguridad</mark></span><span class=\"ref-norma\">Art.  6.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como en auditorías sobre la prestación de los servicios de seguridad\"</span>También incluye las auditorías sobre la prestación de los servicios de seguridad."},{"i":"23-ia-1104","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. Los servicios y funciones de información o control en accesos, recepción, control de tránsito en zonas reservadas o comprobación del estado de calderas, bienes e instalaciones podrán prestarse o realizarse por empresas y personal de seguridad privada, siempre con carácter:","o":["principal o accesorio de las funciones de seguridad privada, previa comunicación al Ministerio del Interior, salvo que la autoridad judicial disponga otra cosa.","complementario o accesorio de las funciones de seguridad privada que se realicen y sin que constituyan el objeto principal del servicio.","complementario o principal, siempre que se realicen con personal habilitado.","accesorio, y únicamente cuando se presten en el interior de inmuebles privados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">complementario o accesorio de las funciones de seguridad privada que se realicen y sin que constituyan el objeto principal del servicio</mark></span><span class=\"ref-norma\">Art.  6.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"siempre con carácter complementario o accesorio de las funciones de seguridad privada que se realicen y sin que en ningún caso constituyan el objeto principal del servicio que se preste\"</span>Siempre con carácter complementario o accesorio, nunca como objeto principal."},{"i":"23-ia-1105","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. Entre los servicios y funciones que quedan fuera de la ley, a no ser que impliquen la asunción o realización de servicios o funciones de seguridad privada, están los de información o control en los accesos a instalaciones, comprendiendo el cuidado y custodia de las llaves, la apertura y cierre de puertas, realizados por:","o":["porteros, conserjes y demás personal auxiliar análogo.","porteros, vigilantes y demás personal auxiliar análogo.","conserjes, guardas rurales y demás personal auxiliar análogo.","porteros, controladores y personal de las empresas de seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">porteros, conserjes y demás personal auxiliar análogo</mark></span><span class=\"ref-norma\">Art.  6.2.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"por porteros, conserjes y demás personal auxiliar análogo\"</span>Se realizan por porteros, conserjes y personal auxiliar análogo."},{"i":"23-ia-1106","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. El personal no habilitado que preste servicios o funciones de información, control de accesos o recepción, en ningún caso podrá:","o":["portar medios de defensa, aunque no armas, previa autorización del Ministerio del Interior, previo informe de la unidad policial competente.","ejercer funciones de seguridad en el interior de los inmuebles donde preste servicio.","utilizar uniformes, aunque sí distintivos propios de su empresa.","ejercer función alguna de las reservadas al personal de seguridad privada, ni portar ni usar armas ni medios de defensa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ejercer función alguna de las reservadas al personal de seguridad privada, ni portar ni usar armas ni medios de defensa</mark></span><span class=\"ref-norma\">Art.  6.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en ningún caso podrá ejercer función alguna de las reservadas al personal de seguridad privada, ni portar ni usar armas ni medios de defensa, ni utilizar distintivos, uniformes o medios que puedan confundirse con los previstos para dicho personal\"</span>No puede ejercer funciones reservadas, ni armas ni medios de defensa, ni uniformes confundibles."},{"i":"23-ia-1107","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. Las empresas de seguridad privada que se dediquen a la instalación o mantenimiento de aparatos, dispositivos y sistemas de seguridad que no incluyan la conexión a centrales receptoras de alarmas o a centros de control o de videovigilancia, sólo están sometidas a la normativa de seguridad privada en lo que se refiere a:","o":["la totalidad de la normativa de seguridad privada aplicable a las empresas de instalación.","las actividades de seguridad informática que realicen.","las actividades y servicios de seguridad privada para las que se encontrasen autorizadas.","los requisitos de homologación de los equipos que instalen."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las actividades y servicios de seguridad privada para las que se encontrasen autorizadas</mark></span><span class=\"ref-norma\">Art.  6.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sólo están sometidas a la normativa de seguridad privada en lo que se refiere a las actividades y servicios de seguridad privada para las que se encontrasen autorizadas\"</span>Solo en lo referente a las actividades y servicios para los que estén autorizadas."},{"i":"23-ia-1108","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades compatibles. A las empresas, sean o no de seguridad privada, que se dediquen a las actividades de seguridad informática, por su incidencia directa en la seguridad de las entidades públicas y privadas, se les podrán imponer:","o":["por Orden del Ministro del Interior obligaciones de comunicación a las Fuerzas y Cuerpos de Seguridad.","reglamentariamente requisitos específicos para garantizar la calidad de los servicios que presten.","legalmente la obligación de inscribirse en el Registro Nacional de Seguridad Privada como empresas de seguridad.","reglamentariamente requisitos de habilitación para su personal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">reglamentariamente requisitos específicos para garantizar la calidad de los servicios que presten</mark></span><span class=\"ref-norma\">Art.  6.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se les podrán imponer reglamentariamente requisitos específicos para garantizar la calidad de los servicios que presten\"</span>Reglamentariamente se les pueden imponer requisitos específicos de calidad."}]},{"a":"Artículo 5","q":[{"i":"23-56","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades de seguridad privada. Señale la INCORRECTA:","o":["La vigilancia y protección de bienes, establecimientos, lugares y eventos, tanto públicos como privados, así como de las personas que pudieran encontrarse en los mismos.","El acompañamiento, defensa y protección de personas físicas determinadas, incluidas las que ostenten la condición legal de autoridad.","El depósito, custodia, recuento y clasificación de explosivos, armas, cartuchería metálica.","El depósito, custodia, recuento y clasificación de monedas y billetes, títulos-valores, joyas, metales preciosos, antigüedades, obras de arte u otros objetos que, por su valor económico, histórico o cultural, y expectativas que generen, puedan requerir vigilancia y protección especial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El depósito, custodia, recuento y clasificación de explosivos, armas, cartuchería metálica</mark></span><span class=\"ref-norma\">Art. 5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"d) El depósito y custodia de explosivos, armas, cartuchería metálica, sustancias, materias, mercancías y cualesquiera objetos que por su peligrosidad precisen de vigilancia y protección especial.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-97","p":"Ley 5/2014, de Seguridad Privada. Actividades compatibles. Quedan también fuera del ámbito de aplicación de esta ley; los siguientes servicios y funciones: Señale la incorrecta.","o":["La instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia.","Las tareas de recepción, comprobación de visitantes y orientación de los mismos, así como las de comprobación de entradas, documentos o carnés, en cualquier clase de edificios o inmuebles, y de cumplimiento de la normativa interna de los locales donde presten dicho servicio.","El control de tránsito en zonas reservadas o de circulación restringida en el interior de instalaciones en cumplimiento de la normativa interna de los mismos.","Las de comprobación y control del estado y funcionamiento de calderas, bienes e instalaciones en general, en cualquier clase de inmuebles, para garantizar su conservación y funcionamiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia</mark></span><span class=\"ref-norma\">Art. 5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"f) La instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-98","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las entidades públicas o privadas podrán constituir, previa autorización del ______ o del órgano autonómico competente, centrales receptoras de alarma de uso propio para la conexión, recepción, verificación y, en su caso, respuesta y transmisión de las señales de alarma que reciban de los sistemas de seguridad instalados en bienes inmuebles o muebles de su titularidad, sin que puedan dar, a través de las mismas, ningún tipo de servicio de seguridad a terceros.","o":["Ministerio de Justicia.","Ministerio de Defensa.","Ministerio del Interior.","Consejo de Ministros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las entidades públicas o privadas podrán constituir, previa autorización del Ministerio del Interior o del órgano autonómico competente, centrales receptoras de alarmas de uso propio para la conexión, recepción, verificación y, en su caso, respuesta y transmisión de las señales de alarma que reciban de los sistemas de seguridad instalados en bienes inmuebles o muebles de su titularidad, sin que puedan dar, a través de las mismas, ningún tipo de servicio de seguridad a terceros.\"</span>"},{"i":"23-100","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. No será una actividad de seguridad privada:","o":["La vigilancia y protección de bienes, establecimientos, lugares y eventos, tanto públicos como privados, así como de las personas que pudieran encontrarse en los mismos.","El acompañamiento, defensa y protección de personas físicas determinadas, incluidas las que ostenten la condición legal de autoridad.","La instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia.","La investigación privada en relación a personas, hechos o objetos perseguibles de oficio o a instancia de parte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La investigación privada en relación a personas, hechos o objetos perseguibles de oficio o a instancia de parte</mark></span><span class=\"ref-norma\">Art. 5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"h) La investigación privada en relación a personas, hechos o delitos sólo perseguibles a instancia de parte.\"</span>"},{"i":"23-ia-1028","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades de seguridad privada. Constituye actividad de seguridad privada el depósito, custodia, recuento y clasificación de monedas y billetes, títulos-valores, joyas, metales preciosos, antigüedades, obras de arte u otros objetos que, por su valor económico, histórico o cultural, y expectativas que generen, puedan requerir:","o":["custodia y traslado especial.","vigilancia y protección especial.","protección y seguro especial.","depósito y vigilancia permanente, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">vigilancia y protección especial</mark></span><span class=\"ref-norma\">Art.  5.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"puedan requerir vigilancia y protección especial\"</span>Requieren vigilancia y protección especial."},{"i":"23-ia-1029","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades de seguridad privada. Constituye actividad de seguridad privada la instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a:","o":["centrales receptoras de alarmas o a centros de control o de videovigilancia.","centrales receptoras de alarmas o a las dependencias de las Fuerzas y Cuerpos de Seguridad.","centros de control o de videovigilancia de titularidad pública.","centrales receptoras de alarmas de uso propio o ajeno, previa autorización."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">centrales receptoras de alarmas o a centros de control o de videovigilancia</mark></span><span class=\"ref-norma\">Art.  5.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia\"</span>Sistemas conectados a centrales receptoras de alarmas o a centros de control o de videovigilancia."},{"i":"23-ia-1030","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades de seguridad privada. Constituye actividad de seguridad privada la investigación privada en relación a personas, hechos o delitos:","o":["perseguibles de oficio o a instancia de parte.","leves y menos graves, perseguibles a instancia de parte.","sólo perseguibles a instancia del Ministerio Fiscal.","sólo perseguibles a instancia de parte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sólo perseguibles a instancia de parte</mark></span><span class=\"ref-norma\">Art.  5.1.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La investigación privada en relación a personas, hechos o delitos sólo perseguibles a instancia de parte\"</span>Solo delitos perseguibles a instancia de parte."},{"i":"23-ia-1031","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades de seguridad privada. Los servicios sobre las actividades de vigilancia y protección, protección de personas, depósito, transporte, instalación y mantenimiento y centrales de alarmas únicamente podrán prestarse por empresas de seguridad privada, sin perjuicio de las competencias de las Fuerzas y Cuerpos de Seguridad. Los despachos de detectives podrán prestar servicios sobre la investigación privada:","o":["con carácter preferente y compartido con las empresas de seguridad.","con carácter exclusivo, aunque no excluyente.","con carácter exclusivo y excluyente.","con carácter general y subordinado a las Fuerzas y Cuerpos de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con carácter exclusivo y excluyente</mark></span><span class=\"ref-norma\">Art.  5.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los despachos de detectives podrán prestar, con carácter exclusivo y excluyente, servicios sobre la actividad a la que se refiere el párrafo h) del apartado anterior\"</span>Los despachos de detectives actúan con carácter exclusivo y excluyente."},{"i":"23-ia-1032","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades de seguridad privada. Las entidades públicas o privadas podrán constituir, previa autorización del Ministerio del Interior o del órgano autonómico competente, centrales receptoras de alarmas de uso propio, sin que puedan dar, a través de las mismas:","o":["servicios de seguridad a terceros sin autorización de las Fuerzas y Cuerpos de Seguridad.","ningún tipo de servicio de seguridad a terceros.","servicios de verificación de alarmas a terceros.","ningún servicio de seguridad a las Administraciones públicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ningún tipo de servicio de seguridad a terceros</mark></span><span class=\"ref-norma\">Art.  5.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sin que puedan dar, a través de las mismas, ningún tipo de servicio de seguridad a terceros\"</span>Las centrales de uso propio no pueden prestar servicio a terceros."},{"i":"23-ia-1342","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Jefes de seguridad. La existencia del jefe de seguridad en las empresas de seguridad privada será obligatoria siempre que éstas se dediquen a todas o algunas de las actividades de vigilancia y protección, escolta, depósito, transporte y:","o":["instalación y mantenimiento de sistemas de seguridad, en los términos que se determinen reglamentariamente.","investigación privada.","explotación de centrales receptoras de alarmas.","depósito y custodia de explosivos y armas, entre otras de las letras a) a e)."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">depósito y custodia de explosivos y armas, entre otras de las letras a) a e)</mark></span><span class=\"ref-norma\">Art.  35.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"será obligatoria siempre que éstas se dediquen a todas o algunas de las actividades previstas en los párrafos a), b), c), d) y e) del artículo 5.1\"</span>Obligatorio para las actividades de las letras a), b), c), d) y e)."},{"i":"23-ia-1209","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Autorización administrativa. La autorización administrativa se suplirá por una declaración responsable cuando las empresas pretendan dedicarse exclusivamente a la actividad de:","o":["instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas.","vigilancia y protección de bienes, establecimientos, lugares y eventos.","depósito, custodia, recuento y clasificación de monedas, billetes y títulos-valores, sin perjuicio de lo previsto en la normativa vigente.","explotación de centrales para la conexión y verificación de señales de alarma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">instalación y mantenimiento de aparatos, equipos, dispositivos y sistemas de seguridad conectados a centrales receptoras de alarmas</mark></span><span class=\"ref-norma\">Art.  18.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando pretendan dedicarse exclusivamente a la actividad de seguridad privada contemplada en el artículo 5.1.f\"</span>Solo la instalación y mantenimiento (f) se sustituye por declaración responsable."}]},{"a":"Artículo 67","q":[{"i":"23-57","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Decomiso del material ___ en servicios de seguridad privada, será decomisado y se procederá a su destrucción si no fuera de lícito comercio, a su enajenación en otro caso, quedando en depósito la cantidad que se obtuviera para hacer frente a las responsabilidades administrativas o de otro orden en que se haya podido incurrir. Señala la INCORRECTA:","o":["Deteriorado","Prohibido","No homologado","Indebidamente utilizado"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Deteriorado</mark></span><span class=\"ref-norma\">Art. 67 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El material prohibido, no homologado o indebidamente utilizado en servicios de seguridad privada, será decomisado y se procederá a su destrucción si no fuera de lícito comercio, o a su enajenación en otro caso, quedando en depósito la cantidad que se obtuviera para hacer frente a las responsabilidades administrativas o de otro orden en que se haya podido incurrir.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-61","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prescripción de las sanciones. Las sanciones impuestas por infracciones leves prescribirán:","o":["Al año, a contar desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción.","A los 6 meses, a contar desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción.","A los 2 años, a contar desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción.","A los 3 años, a contar desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al año, a contar desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción</mark></span><span class=\"ref-norma\">Art. 68 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El plazo de prescripción comenzará a contarse desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción, si ésta no se hubiese comenzado a ejecutar, o desde que se quebrantase el cumplimiento de la misma, si hubiese comenzado, y se interrumpirá desde que se comience o se reanude la ejecución o cumplimiento.\"</span>"},{"i":"23-ia-1612","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Decomiso del material. El material prohibido, no homologado o indebidamente utilizado en servicios de seguridad privada será decomisado y se procederá a su destrucción si no fuera de lícito comercio, o a su enajenación en otro caso, quedando en depósito:","o":["la cantidad obtenida, que se ingresará en el Tesoro Público.","la cantidad que se obtuviera para hacer frente a las responsabilidades administrativas o de otro orden en que se haya podido incurrir.","el material, hasta la resolución del procedimiento sancionador.","la cantidad obtenida, que se entregará al propietario si no hay sanción, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la cantidad que se obtuviera para hacer frente a las responsabilidades administrativas o de otro orden en que se haya podido incurrir</mark></span><span class=\"ref-norma\">Art.  67 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"quedando en depósito la cantidad que se obtuviera para hacer frente a las responsabilidades administrativas o de otro orden en que se haya podido incurrir\"</span>Queda en depósito para hacer frente a responsabilidades administrativas o de otro orden."},{"i":"23-ia-1613","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prescripción de las sanciones. Las sanciones impuestas por infracciones leves, graves o muy graves prescribirán, respectivamente:","o":["al año, a los dos años y a los cuatro años.","a los seis meses, al año y a los dos años.","al año, a los dos años y a los tres años.","a los dos años, a los cuatro años y a los cinco años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al año, a los dos años y a los cuatro años</mark></span><span class=\"ref-norma\">Art.  68.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"prescribirán, respectivamente, al año, a los dos años y a los cuatro años\"</span>Leves, un año; graves, dos; muy graves, cuatro."},{"i":"23-ia-1614","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prescripción de las sanciones. El plazo de prescripción de las sanciones comenzará a contarse desde el día siguiente a aquel en que sea firme la resolución por la que se impone la sanción, si ésta no se hubiese comenzado a ejecutar, o desde que se quebrantase el cumplimiento de la misma, si hubiese comenzado, y se interrumpirá:","o":["desde que se notifique la resolución sancionadora, salvo que la autoridad judicial disponga otra cosa.","desde que se interponga recurso contra la sanción.","desde que se requiera el pago de la sanción.","desde que se comience o se reanude la ejecución o cumplimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">desde que se comience o se reanude la ejecución o cumplimiento</mark></span><span class=\"ref-norma\">Art.  68.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y se interrumpirá desde que se comience o se reanude la ejecución o cumplimiento\"</span>Se interrumpe al comenzar o reanudarse la ejecución."}]},{"a":"Artículo 2","q":[{"i":"23-69","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. Las acciones llevadas a cabo por los prestadores de servicios de seguridad privada para materializar las actividades de seguridad privada, se entiende por:","o":["Servicios de seguridad privada.","Instituciones de seguridad privada.","Medidas de seguridad privada.","Actividades de seguridad privada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Servicios de seguridad privada</mark></span><span class=\"ref-norma\">Art. 2.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Servicios de seguridad privada: las acciones llevadas a cabo por los prestadores de servicios de seguridad privada para materializar las actividades de seguridad privada\"</span>"},{"i":"23-89","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Disposiciones comunes. Definiciones. A los efectos de esta ley se entiende por aquel producto que reúne las especificaciones técnicas o criterios que recoge una norma técnica al efecto:","o":["Elemento, producto o servicio verificado.","Elemento, producto o servicio homologado.","Elemento, producto o servicio acreditado, certificado o verificado.","Elemento, producto o servicio certificado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Elemento, producto o servicio homologado</mark></span><span class=\"ref-norma\">Art. 2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Elemento, producto o servicio homologado: aquel que reúne las especificaciones técnicas o criterios que recoge una norma técnica al efecto.\"</span>"},{"i":"23-93","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las empresas de seguridad privada, los despachos de detectives y el personal habilitado para el ejercicio de funciones de seguridad privada reciben la denominación de:","o":["Prestadores de servicios de seguridad privada.","Actividades de seguridad privada.","Personal de seguridad privada.","Empresa de seguridad privada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Prestadores de servicios de seguridad privada</mark></span><span class=\"ref-norma\">Art. 2.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Prestadores de servicios de seguridad privada: las empresas de seguridad privada, los despachos de detectives y el personal habilitado para el ejercicio de funciones de seguridad privada\"</span>"},{"i":"23-127","p":"Ley 5/2014 de Seguridad Privada. A las acciones llevadas a cabo por los prestadores de servicios de seguridad privada para materializar las actividades de seguridad privada, se las denomina:","o":["Servicios de seguridad privada.","Accionados de seguridad privada.","Resciones de seguridad privada.","Acciones de seguridad privada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Servicios de seguridad privada</mark></span><span class=\"ref-norma\">Art. 2.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Servicios de seguridad privada: las acciones llevadas a cabo por los prestadores de servicios de seguridad privada para materializar las actividades de seguridad privada\"</span>"},{"i":"23-133","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. A los efectos de la ley, se entiende por funciones de seguridad privada:","o":["Los ámbitos de actuación material en que los prestadores de servicios llevan a cabo su acción empresarial y profesional.","Las facultades atribuidas al personal de seguridad privada.","Las acciones llevadas a cabo por los prestadores de servicios para materializar las actividades de seguridad privada.","Las disposiciones adoptadas para el cumplimiento de los fines de prevención o protección pretendidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las facultades atribuidas al personal de seguridad privada</mark></span><span class=\"ref-norma\">Art. 2.4 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"Funciones de seguridad privada: las facultades atribuidas al personal de seguridad privada\"</span>"},{"i":"23-134","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. A los efectos de la ley, se entiende por medidas de seguridad privada:","o":["Las disposiciones adoptadas para el cumplimiento de los fines de prevención o protección pretendidos.","Las facultades atribuidas al personal de seguridad privada para el cumplimiento de sus fines.","Las acciones llevadas a cabo por los prestadores de servicios para materializar las actividades de seguridad privada.","Los ámbitos de actuación material en que los prestadores de servicios llevan a cabo su acción profesional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las disposiciones adoptadas para el cumplimiento de los fines de prevención o protección pretendidos</mark></span><span class=\"ref-norma\">Art. 2.5 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"Medidas de seguridad privada: las disposiciones adoptadas para el cumplimiento de los fines de prevención o protección pretendidos\"</span>"},{"i":"23-ia-1015","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. Se entiende por seguridad privada el conjunto de actividades, servicios, funciones y medidas de seguridad adoptadas, de forma voluntaria u obligatoria, por personas físicas o jurídicas, públicas o privadas, realizadas o prestados por empresas de seguridad, despachos de detectives privados y personal de seguridad privada para:","o":["hacer frente a actos delictivos o riesgos fortuitos, o para realizar investigaciones sobre personas y bienes, en los términos que se determinen reglamentariamente.","prevenir actos deliberados o riesgos accidentales y realizar averiguaciones sobre personas y bienes.","hacer frente a actos deliberados o riesgos accidentales, o para realizar averiguaciones sobre personas y bienes.","hacer frente a amenazas deliberadas o riesgos accidentales, o para proteger las instalaciones y los bienes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">hacer frente a actos deliberados o riesgos accidentales, o para realizar averiguaciones sobre personas y bienes</mark></span><span class=\"ref-norma\">Art.  2.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"para hacer frente a actos deliberados o riesgos accidentales, o para realizar averiguaciones sobre personas y bienes\"</span>Frente a actos deliberados o riesgos accidentales, o para realizar averiguaciones."},{"i":"23-ia-1016","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. A los efectos de la Ley de Seguridad Privada, las actividades de seguridad privada son:","o":["las acciones llevadas a cabo por los prestadores de servicios de seguridad privada para materializar las actividades de seguridad privada, salvo que la autoridad judicial disponga otra cosa.","los ámbitos de actuación material en que los prestadores de servicios de seguridad privada llevan a cabo su acción empresarial y profesional.","las facultades atribuidas al personal de seguridad privada.","las disposiciones adoptadas para el cumplimiento de los fines de prevención o protección pretendidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los ámbitos de actuación material en que los prestadores de servicios de seguridad privada llevan a cabo su acción empresarial y profesional</mark></span><span class=\"ref-norma\">Art.  2.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Actividades de seguridad privada: los ámbitos de actuación material en que los prestadores de servicios de seguridad privada llevan a cabo su acción empresarial y profesional\"</span>Los otros enunciados definen servicios, funciones y medidas de seguridad."},{"i":"23-ia-1017","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. A los efectos de la Ley de Seguridad Privada, las funciones de seguridad privada son:","o":["las facultades atribuidas al personal de seguridad privada.","las acciones llevadas a cabo por los prestadores de servicios para materializar las actividades.","los ámbitos de actuación material en que los prestadores llevan a cabo su acción profesional.","las disposiciones adoptadas para el cumplimiento de los fines de prevención o protección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las facultades atribuidas al personal de seguridad privada</mark></span><span class=\"ref-norma\">Art.  2.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Funciones de seguridad privada: las facultades atribuidas al personal de seguridad privada\"</span>Son las facultades atribuidas al personal."},{"i":"23-ia-1018","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. Señale la opción que NO es un prestador de servicios de seguridad privada según la ley:","o":["Las empresas de seguridad privada.","Los despachos de detectives.","El personal habilitado para el ejercicio de funciones de seguridad privada.","Los centros de formación de personal de seguridad privada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los centros de formación de personal de seguridad privada</mark></span><span class=\"ref-norma\">Art.  2.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Prestadores de servicios de seguridad privada: las empresas de seguridad privada, los despachos de detectives y el personal habilitado para el ejercicio de funciones de seguridad privada\"</span>Los prestadores son empresas de seguridad, despachos de detectives y personal habilitado; los centros de formación no."},{"i":"23-ia-1019","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. El personal acreditado está formado por:","o":["profesores de centros de formación, ingenieros y técnicos de empresas de seguridad y detectives privados, previo informe de la unidad policial competente.","profesores de centros de formación y operadores de seguridad, con exclusión de ingenieros y técnicos.","profesores de centros de formación, ingenieros y técnicos que desarrollen las tareas que les asignan esta ley y operadores de seguridad.","ingenieros, técnicos y operadores de seguridad que presten servicios a empresas autorizadas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">profesores de centros de formación, ingenieros y técnicos que desarrollen las tareas que les asignan esta ley y operadores de seguridad</mark></span><span class=\"ref-norma\">Art.  2.9 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Personal acreditado: profesores de centros de formación, ingenieros y técnicos que desarrollen las tareas que les asignan esta ley y operadores de seguridad\"</span>El personal acreditado incluye profesores, ingenieros y técnicos y operadores de seguridad."},{"i":"23-ia-1020","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. Los centros de formación de aspirantes o de personal de seguridad privada son:","o":["establecimientos sometidos al régimen de autorización administrativa para impartir formación al personal de seguridad privada, sin perjuicio de lo previsto en la normativa vigente.","establecimientos sometidos al régimen de declaración responsable para impartir en sus locales formación al personal de seguridad privada.","establecimientos homologados para impartir formación al personal de seguridad privada.","centros sometidos a declaración responsable para impartir en cualquier lugar formación al personal de seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">establecimientos sometidos al régimen de declaración responsable para impartir en sus locales formación al personal de seguridad privada</mark></span><span class=\"ref-norma\">Art.  2.12 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"establecimientos sometidos al régimen de declaración responsable para impartir en sus locales formación al personal de seguridad privada\"</span>Están sometidos a declaración responsable."},{"i":"23-ia-1021","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. Un elemento, producto o servicio homologado es aquel que:","o":["reúne las especificaciones técnicas o criterios que recoge una norma técnica al efecto.","ha sido certificado por una entidad independiente reconocida por cualquier Estado miembro de la Unión Europea.","ha sido verificado por el Ministerio del Interior mediante inspección.","reúne los requisitos fijados reglamentariamente por la Administración competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">reúne las especificaciones técnicas o criterios que recoge una norma técnica al efecto</mark></span><span class=\"ref-norma\">Art.  2.13 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"aquel que reúne las especificaciones técnicas o criterios que recoge una norma técnica al efecto\"</span>Homologado = cumple las especificaciones técnicas de una norma técnica."},{"i":"23-ia-1022","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Definiciones. Un elemento, producto o servicio acreditado, certificado o verificado es aquel que lo ha sido por:","o":["una entidad pública, constituida a tal fin y reconocida por el Estado español, en los términos que se determinen reglamentariamente.","una entidad independiente, reconocida por el Ministerio del Interior.","un organismo de normalización reconocido por la Unión Europea.","una entidad independiente, constituida a tal fin y reconocida por cualquier Estado miembro de la Unión Europea."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una entidad independiente, constituida a tal fin y reconocida por cualquier Estado miembro de la Unión Europea</mark></span><span class=\"ref-norma\">Art.  2.14 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"aquel que lo ha sido por una entidad independiente, constituida a tal fin y reconocida por cualquier Estado miembro de la Unión Europea\"</span>La entidad debe ser independiente y reconocida por cualquier Estado miembro de la UE."}]},{"a":"Artículo 17","q":[{"i":"23-75","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Seguridad privada. Según su definición legal, señale la INCORRECTA:","o":["Es el conjunto de actividades, servicios, funciones y medidas de seguridad.","Se realizará o se prestará solamente por empresas de seguridad y despachos de detectives privados.","Se adoptará, de forma voluntaria u obligatoria, por personas físicas o jurídicas, públicas o privadas.","Su finalidad es hacer frente a actos deliberados o riesgos accidentales, o realizar averiguaciones sobre personas y bienes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se realizará o se prestará solamente por empresas de seguridad y despachos de detectives privados</mark></span><span class=\"ref-norma\">Art. 16 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"TÍTULO II Empresas de seguridad privada y despachos de detectives privados CAPÍTULO I Empresas de seguridad privada Artículo 17.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1206","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Desarrollo de actividades. Las empresas de seguridad privada podrán dedicarse a la formación, actualización y especialización del personal de seguridad privada, perteneciente o no a sus plantillas, en cuyo caso deberán:","o":["solicitar autorización a la Administración educativa.","contratar a profesores acreditados exclusivamente.","comunicarlo al Registro Nacional de Seguridad Privada.","crear centros de formación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">crear centros de formación</mark></span><span class=\"ref-norma\">Art.  17.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en cuyo caso deberán crear centros de formación\"</span>Deben crear centros de formación."},{"i":"23-ia-1207","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Desarrollo de actividades. Las empresas de seguridad privada podrán revestir:","o":["solo forma societaria, con capital mínimo fijado reglamentariamente.","forma societaria o de empresario individual, con requisitos reducidos en este último caso, previo informe de la unidad policial competente.","forma societaria o de empresario individual, debiendo cumplir, en ambos casos, la totalidad de condiciones y requisitos.","forma de sociedad mercantil o de cooperativa, con los mismos requisitos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">forma societaria o de empresario individual, debiendo cumplir, en ambos casos, la totalidad de condiciones y requisitos</mark></span><span class=\"ref-norma\">Art.  17.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrán revestir forma societaria o de empresario individual, debiendo cumplir, en ambos casos, la totalidad de condiciones y requisitos\"</span>Sociedad o empresario individual, con los mismos requisitos."}]},{"a":"Artículo 29","q":[{"i":"23-79","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los centros de formación del personal de seguridad privada requerirán, para su apertura y funcionamiento, de la presentación de la correspondiente declaración responsable ante el Ministerio del Interior u órgano autonómico competente, debiendo reunir, entre otros que reglamentariamente se establezcan, los siguientes requisitos:","o":["Acreditación, por cualquier título, del derecho de uso del inmueble.","Licencia municipal correspondiente.","Relación de profesores acreditados.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 29 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los centros de formación del personal de seguridad privada requerirán, para su apertura y funcionamiento, de la presentación de la correspondiente declaración responsable ante el Ministerio del Interior u órgano autonómico competente, debiendo reunir, entre otros que reglamentariamente se establezcan, los siguientes requisitos:\"</span>"},{"i":"23-120","p":"Ley 5/2014, de Seguridad Privada. La formación requerida para los vigilantes de seguridad consistirá en la obtención:","o":["De la certificación acreditativa correspondiente, expedida por un centro de formación de personal de seguridad privada que haya presentado la declaración responsable ante el Ministerio del Interior o el órgano autonómico competente.","De las correspondientes certificaciones de profesionalidad del vigilante de seguridad privada y guarda rural y marítimo, que establezca el Gobierno.","Del título de formación profesional que establezca el Gobierno.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span><span class=\"ref-norma\">Art. 29 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La formación requerida para el personal de seguridad privada consistirá:\"</span>"},{"i":"23-ia-1311","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. La formación requerida para los vigilantes de seguridad, vigilantes de explosivos, escoltas privados, guardas rurales, guardas de caza y guardapescas marítimos consistirá en la obtención de la certificación acreditativa expedida por un centro de formación de personal de seguridad privada que haya presentado:","o":["la solicitud de autorización ante el Ministerio de Educación.","la comunicación previa ante la Dirección General de la Policía, previo informe de la unidad policial competente.","la declaración responsable ante el Ministerio del Interior o el órgano autonómico competente.","la autorización administrativa ante el Ministerio del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la declaración responsable ante el Ministerio del Interior o el órgano autonómico competente</mark></span><span class=\"ref-norma\">Art.  29.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que haya presentado la declaración responsable ante el Ministerio del Interior o el órgano autonómico competente\"</span>El centro ha de haber presentado declaración responsable."},{"i":"23-ia-1312","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. Cuando la formación del vigilante de seguridad se acredite mediante certificado de profesionalidad o título de formación profesional, no se exigirá:","o":["la comprobación de la aptitud psicológica y capacidad física.","la prueba de comprobación de conocimientos y capacidad.","la acreditación de la ausencia de antecedentes penales.","la superación del curso de actualización."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la prueba de comprobación de conocimientos y capacidad</mark></span><span class=\"ref-norma\">Art.  29.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"En estos dos últimos casos no se exigirá la prueba de comprobación de conocimientos y capacidad\"</span>No se exige la prueba de comprobación de conocimientos y capacidad."},{"i":"23-ia-1313","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. La formación requerida para los jefes y directores de seguridad consistirá en la obtención bien de un título universitario oficial de grado en el ámbito de la seguridad, o bien del título del curso de dirección de seguridad, reconocido por:","o":["el Ministerio del Interior.","el Ministerio de Educación, Cultura y Deporte.","la Dirección General de la Policía.","el Ministerio de Empleo y Seguridad Social."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Ministerio del Interior</mark></span><span class=\"ref-norma\">Art.  29.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o bien del título del curso de dirección de seguridad, reconocido por el Ministerio del Interior\"</span>El título del curso es reconocido por el Ministerio del Interior."},{"i":"23-ia-1314","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. La formación requerida para los detectives privados consistirá en la obtención bien de un título universitario de grado en el ámbito de la investigación privada, o bien del título del curso de investigación privada, reconocido por:","o":["el Ministerio de Justicia.","la Dirección General de la Guardia Civil.","la Secretaría de Estado de Seguridad.","el Ministerio del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Ministerio del Interior</mark></span><span class=\"ref-norma\">Art.  29.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o bien del título del curso de investigación privada, reconocido por el Ministerio del Interior\"</span>Reconocido por el Ministerio del Interior."},{"i":"23-ia-1315","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. Cuando se trate de miembros de las Fuerzas y Cuerpos de Seguridad y de las Fuerzas Armadas se tendrá en cuenta el grado y experiencia profesionales que acrediten su cualificación, siendo exigible en todo caso:","o":["el curso de formación previa de vigilante de seguridad, sin perjuicio de lo previsto en la normativa vigente.","la prueba de aptitud psicológica.","la prueba de comprobación de conocimientos y capacidad.","la prueba de conocimientos de lengua castellana."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la prueba de comprobación de conocimientos y capacidad</mark></span><span class=\"ref-norma\">Art.  29.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"siendo exigible en todo caso la prueba de comprobación de conocimientos y capacidad\"</span>En todo caso, la prueba de comprobación de conocimientos y capacidad."},{"i":"23-ia-1316","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. La formación previa del personal que no posea la titulación correspondiente de formación profesional, o los certificados de profesionalidad, así como su actualización y especialización, se llevará a cabo en los centros de formación de seguridad privada que hayan presentado la declaración responsable y por:","o":["profesores habilitados como vigilantes de seguridad.","profesores acreditados por el Ministerio del Interior.","profesores acreditados por el Ministerio de Educación, en los términos que se determinen reglamentariamente.","instructores de tiro y profesores universitarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">profesores acreditados por el Ministerio del Interior</mark></span><span class=\"ref-norma\">Art.  29.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y por profesores acreditados por el citado Ministerio\"</span>Por profesores acreditados por el Ministerio del Interior."},{"i":"23-ia-1317","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. Señale el requisito que NO han de reunir los centros de formación del personal de seguridad privada para su apertura y funcionamiento:","o":["Disponer de un director de seguridad en plantilla.","Acreditación, por cualquier título, del derecho de uso del inmueble.","Licencia municipal correspondiente.","Relación de profesores acreditados e instalaciones adecuadas al cumplimiento de sus fines."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Disponer de un director de seguridad en plantilla</mark></span><span class=\"ref-norma\">Art.  29.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Acreditación, por cualquier título, del derecho de uso del inmueble. b) Licencia municipal correspondiente. c) Relación de profesores acreditados. d) Instalaciones adecuadas al cumplimiento de sus fines\"</span>No se exige director de seguridad."},{"i":"23-ia-1318","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. No podrán ser titulares ni desempeñar funciones de dirección ni de administración de centros de formación del personal de seguridad privada los miembros de las Fuerzas y Cuerpos de Seguridad que hayan ejercido en los mismos funciones de control en materia de seguridad privada en:","o":["los cinco años anteriores.","los tres años anteriores.","el año anterior.","los dos años anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los dos años anteriores</mark></span><span class=\"ref-norma\">Art.  29.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en materia de seguridad privada en los dos años anteriores\"</span>Los dos años anteriores."},{"i":"23-ia-1319","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Formación. El Ministerio del Interior elaborará los programas de formación previa y especializada correspondiente al personal de seguridad privada, en cuyo contenido se incluirán materias específicas de:","o":["protección de datos personales y secreto de las comunicaciones, salvo que la autoridad judicial disponga otra cosa.","primeros auxilios y prevención de riesgos laborales.","respeto a la diversidad y a la igualdad de trato y no discriminación.","uso de armas y técnicas de defensa personal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">respeto a la diversidad y a la igualdad de trato y no discriminación</mark></span><span class=\"ref-norma\">Art.  29.7 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se incluirán materias específicas de respeto a la diversidad y a la igualdad de trato y no discriminación\"</span>Incluyen respeto a la diversidad e igualdad de trato y no discriminación."},{"i":"23-ia-1320","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios de actuación. Señale la opción que NO es un principio básico de actuación del personal de seguridad privada:","o":["Legalidad e integridad.","Subordinación jerárquica.","Dignidad en el ejercicio de sus funciones y corrección en el trato con los ciudadanos.","Congruencia y proporcionalidad en el uso de las técnicas y medios de defensa y de investigación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Subordinación jerárquica</mark></span><span class=\"ref-norma\">Art.  30 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Legalidad. b) Integridad. c) Dignidad en el ejercicio de sus funciones. d) Corrección en el trato con los ciudadanos. e) Congruencia\"</span>No figura la subordinación jerárquica entre los principios básicos."},{"i":"23-ia-1321","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios de actuación. Entre los principios de actuación del personal de seguridad privada está la congruencia, aplicando medidas de seguridad y de investigación:","o":["proporcionadas y adecuadas a los riesgos.","necesarias y adecuadas a la gravedad de los hechos.","proporcionadas y suficientes para evitar el daño.","adecuadas y razonables en cada circunstancia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">proporcionadas y adecuadas a los riesgos</mark></span><span class=\"ref-norma\">Art.  30.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Congruencia, aplicando medidas de seguridad y de investigación proporcionadas y adecuadas a los riesgos\"</span>Medidas proporcionadas y adecuadas a los riesgos."},{"i":"23-ia-1322","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios de actuación. Entre los principios de actuación del personal de seguridad privada está la reserva profesional sobre:","o":["los datos de sus clientes y de los bienes protegidos.","las actuaciones de las Fuerzas y Cuerpos de Seguridad.","los procedimientos y medios utilizados en sus servicios, previo informe de la unidad policial competente.","los hechos que conozca en el ejercicio de sus funciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los hechos que conozca en el ejercicio de sus funciones</mark></span><span class=\"ref-norma\">Art.  30.g · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Reserva profesional sobre los hechos que conozca en el ejercicio de sus funciones\"</span>Reserva profesional sobre los hechos que conozca."},{"i":"23-ia-1323","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios de actuación. El personal de seguridad privada estará obligado a auxiliar y colaborar especialmente con las Fuerzas y Cuerpos de Seguridad, a facilitarles la información que resulte necesaria para el ejercicio de sus funciones, y a:","o":["ponerse a sus órdenes en cualquier circunstancia.","comunicarles las incidencias en el plazo de veinticuatro horas, sin perjuicio de lo previsto en la normativa vigente.","seguir sus instrucciones en relación con el servicio de seguridad privada que estuvieren prestando.","colaborar en las investigaciones que determinen sus mandos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seguir sus instrucciones en relación con el servicio de seguridad privada que estuvieren prestando</mark></span><span class=\"ref-norma\">Art.  30.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y a seguir sus instrucciones en relación con el servicio de seguridad privada que estuvieren prestando\"</span>Seguir sus instrucciones en relación con el servicio que estén prestando."}]},{"a":"Artículo 14","q":[{"i":"23-82","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Colaboración Profesional. La especial obligación de colaboración de las empresas de seguridad, los despachos de detectives y el personal de seguridad privada con las Fuerzas y Cuerpos de Seguridad se desarrollará con sujeción al ______ y se basará exclusivamente en la necesidad de asegurar el buen fin de las actuaciones tendentes a preservar la seguridad pública, garantizándose la debida reserva y confidencialidad cuando sea necesario.","o":["Principio de jerarquía.","Principio de responsabilidad.","Principio de cooperación leal.","Principio de legalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Principio de legalidad</mark></span><span class=\"ref-norma\">Art. 14 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La especial obligación de colaboración de las empresas de seguridad, los despachos de detectives y el personal de seguridad privada con las Fuerzas y Cuerpos de Seguridad se desarrollará con sujeción al principio de legalidad y se basará exclusivamente en la necesidad de asegurar el buen fin de las actuaciones tendentes a preservar la seguridad pública, garantizándose la debida reserva y confidencialidad cuando sea necesario.\"</span>"},{"i":"23-ia-1143","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Colaboración profesional. La especial obligación de colaboración de las empresas de seguridad, los despachos de detectives y el personal de seguridad privada con las Fuerzas y Cuerpos de Seguridad se desarrollará con sujeción al principio de legalidad y se basará exclusivamente en:","o":["la necesidad de garantizar la eficacia de las actuaciones de prevención del delito, en los términos que se determinen reglamentariamente.","el principio de reciprocidad entre la seguridad pública y la seguridad privada.","la necesidad de asegurar el buen fin de las actuaciones tendentes a preservar la seguridad pública.","el deber de auxilio a las Fuerzas y Cuerpos de Seguridad en situaciones de riesgo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la necesidad de asegurar el buen fin de las actuaciones tendentes a preservar la seguridad pública</mark></span><span class=\"ref-norma\">Art.  14.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se basará exclusivamente en la necesidad de asegurar el buen fin de las actuaciones tendentes a preservar la seguridad pública, garantizándose la debida reserva y confidencialidad cuando sea necesario\"</span>Se basa exclusivamente en asegurar el buen fin de las actuaciones tendentes a preservar la seguridad pública."},{"i":"23-ia-1144","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Colaboración profesional. Las empresas de seguridad, los despachos de detectives y el personal de seguridad privada deberán comunicar a las Fuerzas y Cuerpos de Seguridad competentes, tan pronto como sea posible, cualesquiera circunstancias o informaciones relevantes para la prevención, el mantenimiento o restablecimiento de la seguridad ciudadana, así como todo hecho delictivo del que tuviesen conocimiento, poniendo a su disposición:","o":["a los detenidos, así como las diligencias practicadas y los informes elaborados.","a los presuntos delincuentes, así como los instrumentos, efectos y pruebas relacionadas con los mismos.","a los presuntos delincuentes y los medios de seguridad utilizados en su detención.","los instrumentos, efectos y pruebas relacionados con los hechos, no así a los presuntos delincuentes, salvo que la autoridad judicial disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a los presuntos delincuentes, así como los instrumentos, efectos y pruebas relacionadas con los mismos</mark></span><span class=\"ref-norma\">Art.  14.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"poniendo a su disposición a los presuntos delincuentes, así como los instrumentos, efectos y pruebas relacionadas con los mismos\"</span>Ponen a disposición a los presuntos delincuentes y los instrumentos, efectos y pruebas."},{"i":"23-ia-1145","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Colaboración profesional. Si las informaciones que las Fuerzas y Cuerpos de Seguridad faciliten al personal de seguridad privada contuvieran datos de carácter personal, sólo podrán facilitarse:","o":["en caso de peligro real para la seguridad pública o para evitar la comisión de infracciones penales.","con autorización judicial o del Ministerio Fiscal.","en caso de peligro grave para las personas o bienes protegidos, previo informe de la unidad policial competente.","para la represión de infracciones penales o administrativas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en caso de peligro real para la seguridad pública o para evitar la comisión de infracciones penales</mark></span><span class=\"ref-norma\">Art.  14.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sólo podrán facilitarse en caso de peligro real para la seguridad pública o para evitar la comisión de infracciones penales\"</span>Solo en caso de peligro real para la seguridad pública o para evitar infracciones penales."},{"i":"23-ia-1146","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Acceso a la información por las Fuerzas y Cuerpos de Seguridad. Se autorizan las cesiones de datos necesarias para contribuir a la salvaguarda de la seguridad ciudadana, así como el acceso por parte de las Fuerzas y Cuerpos de Seguridad a los sistemas instalados por las empresas de seguridad privada que permitan la comprobación de las informaciones:","o":["en todo momento cuando así lo soliciten las Fuerzas y Cuerpos de Seguridad.","en tiempo real, previa autorización del Ministerio del Interior.","en diferido, cuando resulte necesario para la investigación de infracciones penales, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","en tiempo real cuando ello sea necesario para la prevención de un peligro real para la seguridad pública o para la represión de infracciones penales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en tiempo real cuando ello sea necesario para la prevención de un peligro real para la seguridad pública o para la represión de infracciones penales</mark></span><span class=\"ref-norma\">Art.  15.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que permitan la comprobación de las informaciones en tiempo real cuando ello sea necesario para la prevención de un peligro real para la seguridad pública o para la represión de infracciones penales\"</span>Acceso en tiempo real si es necesario para prevenir un peligro real o reprimir infracciones penales."},{"i":"23-ia-1147","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Acceso a la información por las Fuerzas y Cuerpos de Seguridad. La comunicación de buena fe de información a las Fuerzas y Cuerpos de Seguridad por las entidades y el personal de seguridad privada no constituirá vulneración de las restricciones sobre divulgación de información impuestas:","o":["por vía contractual, aunque sí de las impuestas por disposición legal.","por disposición legal o reglamentaria, pero sí de las impuestas contractualmente, salvo que la autoridad judicial disponga otra cosa.","por vía contractual o por cualquier disposición legal, reglamentaria o administrativa.","por el deber de secreto profesional del detective privado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por vía contractual o por cualquier disposición legal, reglamentaria o administrativa</mark></span><span class=\"ref-norma\">Art.  15.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no constituirá vulneración de las restricciones sobre divulgación de información impuestas por vía contractual o por cualquier disposición legal, reglamentaria o administrativa\"</span>No vulnera restricciones contractuales, legales, reglamentarias ni administrativas."},{"i":"23-ia-1201","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Coordinación y participación. El Ministerio del Interior o, en su caso, el órgano autonómico competente adoptará las medidas organizativas que resulten adecuadas para asegurar:","o":["la coordinación de los servicios de seguridad privada con los de las Fuerzas y Cuerpos de Seguridad.","la participación de los representantes del sector en la planificación de los servicios.","la colaboración de los servicios de seguridad privada con las policías locales.","el control de los servicios de seguridad privada por las Fuerzas y Cuerpos de Seguridad, en los términos que se determinen reglamentariamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la coordinación de los servicios de seguridad privada con los de las Fuerzas y Cuerpos de Seguridad</mark></span><span class=\"ref-norma\">Art.  16.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"adoptará las medidas organizativas que resulten adecuadas para asegurar la coordinación de los servicios de seguridad privada con los de las Fuerzas y Cuerpos de Seguridad\"</span>Las medidas organizativas aseguran la coordinación con las Fuerzas y Cuerpos de Seguridad."},{"i":"23-ia-1202","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Coordinación y participación. En el ámbito de las competencias de la Administración General del Estado se constituirán comisiones mixtas de seguridad privada, nacionales, autonómicas o provinciales, con el carácter de órganos:","o":["deliberantes y de coordinación entre las Fuerzas y Cuerpos de Seguridad y las empresas.","consultivos y de decisión entre las administraciones públicas y los representantes sindicales, salvo que la autoridad judicial disponga otra cosa.","de colaboración y control entre las administraciones públicas y las empresas de seguridad.","consultivos y de colaboración entre las administraciones públicas y los representantes del sector."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">consultivos y de colaboración entre las administraciones públicas y los representantes del sector</mark></span><span class=\"ref-norma\">Art.  16.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con el carácter de órganos consultivos y de colaboración entre las administraciones públicas y los representantes del sector\"</span>Las comisiones mixtas son órganos consultivos y de colaboración."},{"i":"23-ia-1203","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Coordinación y participación. La composición y funciones de las comisiones mixtas de seguridad privada, nacionales, autonómicas o provinciales, se determinarán:","o":["por orden del Ministro del Interior.","por acuerdo de las propias comisiones.","reglamentariamente.","por resolución de la Secretaría de Estado de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">reglamentariamente</mark></span><span class=\"ref-norma\">Art.  16.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Su composición y funciones se determinarán reglamentariamente\"</span>Se determinan reglamentariamente."},{"i":"23-ia-1204","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Coordinación y participación. En las comunidades autónomas que tengan asumidas las competencias en materia de seguridad privada también podrán existir órganos consultivos en materia de seguridad privada, con la composición y funcionamiento:","o":["que establezca el Ministerio del Interior.","que en cada caso se determine.","que fije la Comisión Nacional de Seguridad Privada.","que acuerde la Junta de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">que en cada caso se determine</mark></span><span class=\"ref-norma\">Art.  16.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con la composición y funcionamiento que en cada caso se determine\"</span>Con la composición y funcionamiento que en cada caso se determine."}]},{"a":"Artículo 13","q":[{"i":"23-86","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Las Comunidades Autónomas que, con arreglo a sus estatutos de autonomía, tengan competencia para la protección de personas y bienes y para el mantenimiento del orden público, ejecutarán la legislación del Estado sobre las siguientes materias:","o":["La autorización de las empresas de seguridad privada y de sus delegaciones, así como la recepción de la declaración responsable para la apertura de los despachos de detectives privados y de sus sucursales, cuando, en ambos casos, tengan su domicilio en la comunidad autónoma y su ámbito de actuación se limite a su territorio.","La autorización de las actividades y servicios de seguridad privada que se realicen en la comunidad autónoma cuando requieran de la misma o de control previo.","La inspección y sanción de las actividades y servicios de seguridad privada que se realicen en la comunidad autónoma, así como de quienes los presten o utilicen y la inspección y sanción de los despachos de detectives privados y de sus sucursales que realicen su actividad en la comunidad autónoma.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span><span class=\"ref-norma\">Art. 13 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las comunidades autónomas que, con arreglo a sus estatutos de autonomía, tengan competencia para la protección de personas y bienes y para el mantenimiento del orden público, ejecutarán la legislación del Estado sobre las siguientes materias:\"</span>"},{"i":"23-ia-1139","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de las comunidades autónomas. Las comunidades autónomas que, con arreglo a sus estatutos de autonomía, tengan competencia para la protección de personas y bienes y para el mantenimiento del orden público, respecto de la legislación del Estado en materia de seguridad privada:","o":["la desarrollarán legislativamente en el ámbito de su territorio.","la ejecutarán si disponen de cuerpo de policía propia.","la ejecutarán en las materias que la ley enumera.","podrán dictar normas con rango de ley en todas las materias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la ejecutarán en las materias que la ley enumera</mark></span><span class=\"ref-norma\">Art.  13.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"ejecutarán la legislación del Estado sobre las siguientes materias\"</span>Ejecutan la legislación del Estado."},{"i":"23-ia-1140","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de las comunidades autónomas. Las comunidades autónomas con competencia autorizarán las empresas de seguridad privada y de sus delegaciones, así como recibirán la declaración responsable para la apertura de los despachos de detectives privados y de sus sucursales, cuando en ambos casos:","o":["tengan su domicilio en la comunidad autónoma, aunque su ámbito de actuación sea nacional.","tengan su domicilio en la comunidad autónoma y su ámbito de actuación esté limitado a su territorio.","su ámbito de actuación esté limitado a su territorio, aunque tengan domicilio en otra comunidad, previo informe de la unidad policial competente.","tengan su domicilio y desarrollen su actividad en dos o más comunidades autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tengan su domicilio en la comunidad autónoma y su ámbito de actuación esté limitado a su territorio</mark></span><span class=\"ref-norma\">Art.  13.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando, en ambos casos, tengan su domicilio en la comunidad autónoma y su ámbito de actuación esté limitado a su territorio\"</span>Se exige domicilio en la comunidad y ámbito de actuación limitado a su territorio."},{"i":"23-ia-1141","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de las comunidades autónomas. Corresponde a las comunidades autónomas con competencia la coordinación de los servicios de seguridad e investigación privadas prestados en la comunidad autónoma con los de:","o":["la policía autonómica y las policías locales.","las Fuerzas y Cuerpos de Seguridad del Estado.","las Juntas de Seguridad autonómicas.","las policías locales exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la policía autonómica y las policías locales</mark></span><span class=\"ref-norma\">Art.  13.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con los de la policía autonómica y las policías locales\"</span>Coordinan con la policía autonómica y las policías locales."},{"i":"23-ia-1142","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de las comunidades autónomas. Las comunidades autónomas que, en virtud de sus estatutos, hayan asumido competencia ejecutiva en materia de seguridad privada cuando así lo establezca la legislación del Estado, la ejercerán si:","o":["disponen de cuerpo de policía propia o han obtenido la delegación del Ministerio del Interior, sin perjuicio de lo previsto en la normativa vigente.","cuentan con policía autonómica integral y con Junta de Seguridad propia.","establecen fórmulas de colaboración con la Guardia Civil en materia de armas.","disponen de cuerpo de policía propia o establecen fórmulas de colaboración con el Cuerpo Nacional de Policía."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">disponen de cuerpo de policía propia o establecen fórmulas de colaboración con el Cuerpo Nacional de Policía</mark></span><span class=\"ref-norma\">Art.  13.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la ejercerán si disponen de cuerpo de policía propia o establecen fórmulas de colaboración con el Cuerpo Nacional de Policía\"</span>Si tienen policía propia o fórmulas de colaboración con el Cuerpo Nacional de Policía."}]},{"a":"Artículo 31","q":[{"i":"23-90","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. ¿A quién le corresponde ejercer funciones de vigilancia y protección de personas y bienes en fincas rústicas, así como en las instalaciones agrícolas, industriales o comerciales que se encuentren en ellas?","o":["A los escoltas privados.","A los vigilantes de seguridad.","A los guardas rurales.","A los operarios de seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los guardas rurales</mark></span><span class=\"ref-norma\">Art. 34 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los guardas rurales ejercerán funciones de vigilancia y protección de personas y bienes en fincas rústicas, así como en las instalaciones agrícolas, industriales o comerciales que se encuentren en ellas.\"</span>"},{"i":"23-101","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Escoltas Privados. Los Guardas Rurales ejercerán funciones de _____ y protección de personas y bienes en fincas rústicas, así como en las instalaciones agrícolas, industriales o comerciales que se encuentren en ellas.","o":["Mantenimiento.","Defensa.","Vigilancia.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Vigilancia</mark></span><span class=\"ref-norma\">Art. 34 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los guardas rurales ejercerán funciones de vigilancia y protección de personas y bienes en fincas rústicas, así como en las instalaciones agrícolas, industriales o comerciales que se encuentren en ellas.\"</span>"},{"i":"23-121","p":"Ley 5/2014, de Seguridad Privada. Se considerarán agresiones y desobediencias a agentes de la autoridad las que se cometan contra el personal de seguridad privada cuando: Señale la opción incorrecta.","o":["Cuando desarrolla actividades de seguridad privada en cooperación con las Fuerzas y Cuerpos de Seguridad.","Esté debidamente identificado.","Cuando desarrolla actividades de seguridad privada bajo el mando de las Fuerzas y Cuerpos de Seguridad.","Cuando se encuentren debidamente uniformados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando se encuentren debidamente uniformados</mark></span><span class=\"ref-norma\">Art. 31 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Se considerarán agresiones y desobediencias a agentes de la autoridad las que se cometan contra el personal de seguridad privada, debidamente identificado, cuando desarrolle actividades de seguridad privada en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1324","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Protección jurídica de agente de la autoridad. Se considerarán agresiones y desobediencias a agentes de la autoridad las que se cometan contra el personal de seguridad privada, debidamente identificado, cuando desarrolle actividades de seguridad privada:","o":["en el ejercicio de sus funciones, en cualquier circunstancia.","en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad.","en cooperación con las Fuerzas y Cuerpos de Seguridad, con independencia de quién ejerza el mando.","en lugares públicos y bajo la supervisión de las Fuerzas y Cuerpos de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad</mark></span><span class=\"ref-norma\">Art.  31 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando desarrolle actividades de seguridad privada en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad\"</span>La protección de agente de la autoridad exige cooperación y mando de las Fuerzas y Cuerpos."},{"i":"23-ia-1325","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. Los vigilantes de seguridad podrán efectuar controles de identidad, de objetos personales, paquetería, mercancías o vehículos en el acceso o en el interior de inmuebles o propiedades donde presten servicio, sin que, en ningún caso, puedan:","o":["retener la documentación personal, pero sí impedir el acceso a dichos inmuebles o propiedades.","exigir la identificación a los particulares, pero sí inspeccionar sus vehículos, en los términos que se determinen reglamentariamente.","impedir el acceso, pero sí retener la documentación personal.","inspeccionar el interior de los vehículos ni impedir el acceso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">retener la documentación personal, pero sí impedir el acceso a dichos inmuebles o propiedades</mark></span><span class=\"ref-norma\">Art.  32.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sin que, en ningún caso, puedan retener la documentación personal, pero sí impedir el acceso a dichos inmuebles o propiedades\"</span>No pueden retener la documentación, pero sí impedir el acceso."},{"i":"23-ia-1326","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. La negativa a exhibir la identificación o a permitir el control de los objetos personales, de paquetería, mercancía o del vehículo facultará al vigilante de seguridad para:","o":["retener a los particulares hasta la llegada de las Fuerzas y Cuerpos de Seguridad.","registrar los objetos personales sin consentimiento.","solicitar la intervención de las Fuerzas y Cuerpos de Seguridad, sin poder impedir el acceso, salvo que la autoridad judicial disponga otra cosa.","impedir a los particulares el acceso o para ordenarles el abandono del inmueble o propiedad objeto de su protección."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">impedir a los particulares el acceso o para ordenarles el abandono del inmueble o propiedad objeto de su protección</mark></span><span class=\"ref-norma\">Art.  32.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"facultará para impedir a los particulares el acceso o para ordenarles el abandono del inmueble o propiedad objeto de su protección\"</span>Puede impedir el acceso u ordenar el abandono."},{"i":"23-ia-1327","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. Los vigilantes de seguridad deben evitar la comisión de actos delictivos o infracciones administrativas en relación con el objeto de su protección, debiendo oponerse a los mismos e intervenir cuando presenciaren la comisión de algún tipo de infracción o fuere precisa su ayuda por razones:","o":["de seguridad o de urgencia.","humanitarias o de necesidad.","humanitarias o de urgencia.","de seguridad pública o de peligro inminente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">humanitarias o de urgencia</mark></span><span class=\"ref-norma\">Art.  32.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o fuere precisa su ayuda por razones humanitarias o de urgencia\"</span>Razones humanitarias o de urgencia."},{"i":"23-ia-1328","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. Los vigilantes de seguridad, en relación con el objeto de su protección o de su actuación, podrán detener y poner inmediatamente a disposición de las Fuerzas y Cuerpos de Seguridad competentes a los delincuentes y los instrumentos, efectos y pruebas de los delitos, así como denunciar a quienes cometan infracciones administrativas. No podrán proceder:","o":["a la identificación de aquéllos, salvo que se resistan a la detención.","al interrogatorio de aquéllos, si bien no se considerará como tal la anotación de sus datos personales para su comunicación a las autoridades.","al registro de aquéllos, aunque sí a la anotación de sus datos personales.","al interrogatorio de aquéllos, incluida la anotación de sus datos personales, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al interrogatorio de aquéllos, si bien no se considerará como tal la anotación de sus datos personales para su comunicación a las autoridades</mark></span><span class=\"ref-norma\">Art.  32.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No podrán proceder al interrogatorio de aquéllos, si bien no se considerará como tal la anotación de sus datos personales para su comunicación a las autoridades\"</span>No pueden interrogar; anotar los datos personales no se considera interrogatorio."},{"i":"23-ia-1329","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. Los vigilantes de seguridad podrán proteger el almacenamiento, recuento, clasificación, transporte y dispensado de dinero, obras de arte y antigüedades, valores y otros objetos valiosos, así como:","o":["el manipulado de efectivo y demás procesos inherentes a la ejecución de estos servicios.","la custodia de armas y explosivos de titularidad de la empresa.","el acompañamiento de las personas que transporten dichos objetos, en los términos que se determinen reglamentariamente.","la instalación de los sistemas de seguridad de los depósitos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el manipulado de efectivo y demás procesos inherentes a la ejecución de estos servicios</mark></span><span class=\"ref-norma\">Art.  32.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como el manipulado de efectivo y demás procesos inherentes a la ejecución de estos servicios\"</span>También el manipulado de efectivo y procesos inherentes."},{"i":"23-ia-1330","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. En relación con el funcionamiento de centrales receptoras de alarmas, los vigilantes de seguridad llevarán a cabo la prestación de servicios de:","o":["recepción y verificación no personal de las señales de alarma, exclusivamente.","verificación remota y transmisión a las Fuerzas y Cuerpos de Seguridad, exclusivamente.","mantenimiento de los sistemas conectados a la central.","verificación personal y respuesta de las señales de alarmas que se produzcan."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">verificación personal y respuesta de las señales de alarmas que se produzcan</mark></span><span class=\"ref-norma\">Art.  32.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la prestación de servicios de verificación personal y respuesta de las señales de alarmas que se produzcan\"</span>Verificación personal y respuesta."},{"i":"23-ia-1331","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. Los vigilantes de seguridad se dedicarán exclusivamente a las funciones de seguridad propias, no pudiendo:","o":["simultanearlas con las de escolta privado.","prestarlas fuera de los inmuebles cuya vigilancia tengan encomendada.","simultanearlas con otras no directamente relacionadas con aquéllas.","realizar funciones de control de accesos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">simultanearlas con otras no directamente relacionadas con aquéllas</mark></span><span class=\"ref-norma\">Art.  32.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no pudiendo simultanearlas con otras no directamente relacionadas con aquéllas\"</span>No pueden simultanearlas con otras no relacionadas."},{"i":"23-ia-1332","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Vigilantes de seguridad. Corresponde a los vigilantes de explosivos, que deberán estar integrados en empresas de seguridad, la función de protección del almacenamiento, transporte y demás procesos inherentes a la ejecución de estos servicios, en relación con:","o":["explosivos, armas y cartuchería metálica exclusivamente.","explosivos u otros objetos o sustancias peligrosas que reglamentariamente se determinen.","explosivos y sustancias químicas, previa autorización de la Guardia Civil, salvo que la autoridad judicial disponga otra cosa.","cualquier objeto o sustancia que precise vigilancia y protección especial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">explosivos u otros objetos o sustancias peligrosas que reglamentariamente se determinen</mark></span><span class=\"ref-norma\">Art.  32.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en relación con explosivos u otros objetos o sustancias peligrosas que reglamentariamente se determinen\"</span>Explosivos u otros objetos o sustancias peligrosas que se determinen reglamentariamente."},{"i":"23-ia-1333","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Escoltas privados. Son funciones de los escoltas privados el acompañamiento, defensa y protección de personas determinadas, o de grupos concretos de personas, impidiendo que sean objeto de:","o":["agresiones o actos delictivos.","agresiones o infracciones administrativas.","actos delictivos o situaciones de riesgo.","amenazas o coacciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">agresiones o actos delictivos</mark></span><span class=\"ref-norma\">Art.  33.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"impidiendo que sean objeto de agresiones o actos delictivos\"</span>Impiden agresiones o actos delictivos."},{"i":"23-ia-1334","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Escoltas privados. En el desempeño de sus funciones, los escoltas no podrán realizar identificaciones o detenciones, ni impedir o restringir la libre circulación, salvo que resultare imprescindible como consecuencia de:","o":["un delito flagrante en las inmediaciones del lugar de protección, previo informe de la unidad policial competente.","una orden de las Fuerzas y Cuerpos de Seguridad presentes.","una situación de peligro inminente para terceras personas.","una agresión o de un intento manifiesto de agresión a la persona o personas protegidas o a los propios escoltas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una agresión o de un intento manifiesto de agresión a la persona o personas protegidas o a los propios escoltas</mark></span><span class=\"ref-norma\">Art.  33.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"salvo que resultare imprescindible como consecuencia de una agresión o de un intento manifiesto de agresión a la persona o personas protegidas o a los propios escoltas\"</span>Solo ante agresión o intento manifiesto de agresión a protegidos o a los escoltas."},{"i":"23-ia-1335","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Escoltas privados. Para el cumplimiento de sus funciones será aplicable a los escoltas privados lo determinado para los vigilantes de seguridad, salvo lo referente a:","o":["el armamento.","la formación.","la uniformidad.","los medios de defensa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la uniformidad</mark></span><span class=\"ref-norma\">Art.  33.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"salvo lo referente a la uniformidad\"</span>Se exceptúa la uniformidad."},{"i":"23-ia-1336","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Guardas rurales y sus especialidades. Los guardas rurales ejercerán funciones de vigilancia y protección de personas y bienes en fincas rústicas, así como en las instalaciones agrícolas, industriales o comerciales que se encuentren en ellas. Se atendrán al régimen general establecido para los vigilantes de seguridad, con la especificidad de que no podrán desempeñar:","o":["las funciones de verificación de alarmas.","las funciones de protección del almacenamiento, recuento, clasificación, transporte y dispensado de dinero y valores.","los controles de identidad en el acceso a las fincas, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","las funciones de detención de delincuentes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las funciones de protección del almacenamiento, recuento, clasificación, transporte y dispensado de dinero y valores</mark></span><span class=\"ref-norma\">Art.  34.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con la especificidad de que no podrán desempeñar las funciones contempladas en el artículo 32.1.e)\"</span>No pueden proteger dinero, valores y objetos valiosos (art. 32.1.e)."},{"i":"23-ia-1337","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Guardas rurales y sus especialidades. A los guardas de caza corresponde desempeñar las funciones de los guardas rurales y, además, las de vigilancia y protección:","o":["en las fincas de caza en cuanto a los distintos aspectos del régimen cinegético y espacios de pesca fluvial.","en los cotos de caza y pesca, y en las zonas marítimas con fines pesqueros, salvo que la autoridad judicial disponga otra cosa.","en los parques nacionales y espacios naturales protegidos.","en las fincas rústicas y en los establecimientos de acuicultura."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en las fincas de caza en cuanto a los distintos aspectos del régimen cinegético y espacios de pesca fluvial</mark></span><span class=\"ref-norma\">Art.  34.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"además, las de vigilancia y protección en las fincas de caza en cuanto a los distintos aspectos del régimen cinegético y espacios de pesca fluvial\"</span>Fincas de caza (régimen cinegético) y espacios de pesca fluvial."},{"i":"23-ia-1338","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Guardas rurales y sus especialidades. Corresponde a los guardapescas marítimos desempeñar las funciones de los guardas rurales y, además, las de vigilancia y protección de:","o":["las embarcaciones pesqueras y los puertos deportivos.","los espacios de pesca fluvial y los cotos de pesca.","las lonjas pesqueras y los establecimientos de acuicultura, previo informe de la unidad policial competente.","los establecimientos de acuicultura y zonas marítimas con fines pesqueros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los establecimientos de acuicultura y zonas marítimas con fines pesqueros</mark></span><span class=\"ref-norma\">Art.  34.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"además, las de vigilancia y protección de los establecimientos de acuicultura y zonas marítimas con fines pesqueros\"</span>Establecimientos de acuicultura y zonas marítimas con fines pesqueros."},{"i":"23-ia-1339","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Guardas rurales y sus especialidades. Los guardas de caza y los guardapescas marítimos podrán proceder a la retirada u ocupación de las piezas cobradas y los medios de caza y pesca, incluidas armas, cuando aquéllos hubieran sido utilizados para cometer una infracción, procediendo a:","o":["su depósito en las dependencias de la empresa de seguridad.","su entrega, en el plazo de veinticuatro horas, a la autoridad judicial.","su entrega inmediata a las Fuerzas y Cuerpos de Seguridad competentes.","su custodia hasta que lo ordene el Ministerio del Interior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su entrega inmediata a las Fuerzas y Cuerpos de Seguridad competentes</mark></span><span class=\"ref-norma\">Art.  34.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"procediendo a su entrega inmediata a las Fuerzas y Cuerpos de Seguridad competentes\"</span>Se entregan de inmediato a las Fuerzas y Cuerpos de Seguridad."}]},{"a":"Artículo 28","q":[{"i":"23-92","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los nacionales de otros Estados miembros de la Unión Europea o de Estados parte en el Acuerdo sobre el Espacio Económico Europeo, cuya habilitación o cualificación profesional haya sido obtenida en alguno de dichos Estados para el desempeño de funciones de seguridad privada en el mismo, podrán prestar servicios en España, siempre que, previa comprobación por el Ministerio del Interior, se acredite que cumplen los siguientes requisitos: señale la INCORRECTA.","o":["Poseer alguna titulación, habilitación o certificación expedida por las autoridades competentes de cualquier Estado miembro o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo que le autorice para el ejercicio de funciones de seguridad privada en el mismo.","Acreditar los conocimientos, formación y aptitudes equivalentes a los exigidos en España para el ejercicio de las profesiones relacionadas con la seguridad privada.","Haber residido en España durante los cinco años anteriores.","No haber sido sancionado en los dos o cuatro años anteriores por infracción grave o muy grave, respectivamente, en materia de seguridad privada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Haber residido en España durante los cinco años anteriores</mark></span><span class=\"ref-norma\">Art. 28.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Acreditar los conocimientos, formación y aptitudes equivalentes a los exigidos en España para el ejercicio de las profesiones relacionadas con la seguridad privada\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1301","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Para obtener la habilitación profesional, los aspirantes deben tener la nacionalidad de un Estado miembro de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo, o ser nacional de un tercer Estado que:","o":["tenga suscrito con España un convenio internacional en el que cada parte reconozca el acceso al ejercicio de estas actividades a los nacionales de la otra.","mantenga relaciones diplomáticas con España y reconozca la reciprocidad en el acceso a estas actividades, en los términos que se determinen reglamentariamente.","tenga suscrito con la Unión Europea un convenio de cooperación en materia de seguridad privada.","tenga suscrito con España un convenio de doble nacionalidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tenga suscrito con España un convenio internacional en el que cada parte reconozca el acceso al ejercicio de estas actividades a los nacionales de la otra</mark></span><span class=\"ref-norma\">Art.  28.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o ser nacional de un tercer Estado que tenga suscrito con España un convenio internacional en el que cada parte reconozca el acceso al ejercicio de estas actividades a los nacionales de la otra\"</span>Requiere convenio internacional con España con reconocimiento recíproco."},{"i":"23-ia-1302","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los aspirantes a la habilitación profesional no deben haber sido sancionados en los dos o cuatro años anteriores por infracción grave o muy grave, respectivamente, en materia de:","o":["seguridad ciudadana.","tráfico y seguridad vial.","protección de datos.","seguridad privada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seguridad privada</mark></span><span class=\"ref-norma\">Art.  28.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No haber sido sancionado en los dos o cuatro años anteriores por infracción grave o muy grave, respectivamente, en materia de seguridad privada\"</span>Dos años por graves y cuatro por muy graves, en materia de seguridad privada."},{"i":"23-ia-1303","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los aspirantes a la habilitación profesional no deben haber sido separados del servicio en las Fuerzas y Cuerpos de Seguridad o en las Fuerzas Armadas españolas o del país de su nacionalidad o procedencia en:","o":["los cinco años anteriores.","los tres años anteriores.","los dos años anteriores.","el año anterior."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los dos años anteriores</mark></span><span class=\"ref-norma\">Art.  28.1.g · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o del país de su nacionalidad o procedencia en los dos años anteriores\"</span>El plazo es de dos años."},{"i":"23-ia-1304","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los aspirantes a la habilitación profesional no deben haber sido condenados por intromisión ilegítima en el ámbito de protección del derecho al honor, a la intimidad personal y familiar o a la propia imagen, vulneración del secreto de las comunicaciones o de otros derechos fundamentales en:","o":["los dos años anteriores a la solicitud.","los cinco años anteriores a la solicitud.","los diez años anteriores a la solicitud.","los cuatro años anteriores a la solicitud."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los cinco años anteriores a la solicitud</mark></span><span class=\"ref-norma\">Art.  28.1.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en los cinco años anteriores a la solicitud\"</span>El plazo es de cinco años anteriores a la solicitud."},{"i":"23-ia-1305","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Entre los requisitos generales para obtener la habilitación profesional está carecer de antecedentes penales por delitos:","o":["dolosos.","graves.","dolosos o imprudentes.","contra el patrimonio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dolosos</mark></span><span class=\"ref-norma\">Art.  28.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Carecer de antecedentes penales por delitos dolosos\"</span>Delitos dolosos."},{"i":"23-ia-1306","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. La pérdida de alguno de los requisitos generales para la habilitación producirá la extinción de la habilitación y:","o":["la suspensión de la habilitación durante dos años.","la retirada de la tarjeta de identidad profesional y de la licencia de armas.","la imposición de una sanción por infracción grave.","la cancelación de oficio de la inscripción en el Registro Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la cancelación de oficio de la inscripción en el Registro Nacional</mark></span><span class=\"ref-norma\">Art.  28.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"producirá la extinción de la habilitación y la cancelación de oficio de la inscripción en el Registro Nacional\"</span>Se extingue la habilitación y se cancela de oficio la inscripción."},{"i":"23-ia-1307","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los funcionarios públicos en activo y demás personal al servicio de las administraciones públicas podrán habilitarse, pero no podrán ejercer funciones propias del personal de seguridad privada, excepto cuando:","o":["desempeñen la función de jefe de seguridad en una empresa de seguridad, salvo que la autoridad judicial disponga otra cosa.","se encuentren en situación de excedencia voluntaria.","desempeñen la función de director de seguridad en el propio centro a que pertenezcan.","presten servicios como vigilantes en dependencias públicas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">desempeñen la función de director de seguridad en el propio centro a que pertenezcan</mark></span><span class=\"ref-norma\">Art.  28.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"excepto cuando desempeñen la función de director de seguridad en el propio centro a que pertenezcan\"</span>Solo pueden ser director de seguridad en el propio centro al que pertenezcan."},{"i":"23-ia-1308","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los miembros de las Fuerzas y Cuerpos de Seguridad podrán ejercer funciones propias del personal de seguridad privada cuando pasen a una situación administrativa distinta a la de servicio activo, siempre que en los dos años anteriores no hayan desempeñado:","o":["funciones de investigación criminal o de policía judicial en materia de seguridad privada, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","funciones de control de las entidades, servicios o actuaciones de seguridad, vigilancia o investigación privadas, ni de su personal o medios.","funciones de mando en unidades de seguridad ciudadana.","funciones de inspección sobre las empresas de seguridad privada de su demarcación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">funciones de control de las entidades, servicios o actuaciones de seguridad, vigilancia o investigación privadas, ni de su personal o medios</mark></span><span class=\"ref-norma\">Art.  28.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"siempre que en los dos años anteriores no hayan desempeñado funciones de control de las entidades, servicios o actuaciones de seguridad, vigilancia o investigación privadas, ni de su personal o medios\"</span>No haber ejercido control sobre entidades, servicios, personal o medios de seguridad privada en los dos años anteriores."},{"i":"23-ia-1309","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los nacionales de otros Estados miembros de la Unión Europea que pretendan prestar servicios en España deberán, entre otros requisitos, tener:","o":["conocimientos de lengua castellana suficientes para el normal desempeño de las funciones de seguridad privada.","residencia legal en España durante, al menos, un año.","conocimientos de lengua castellana equivalentes a los exigidos en la enseñanza obligatoria, en los términos que se determinen reglamentariamente.","conocimientos de la lengua cooficial de la comunidad autónoma donde presten servicio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">conocimientos de lengua castellana suficientes para el normal desempeño de las funciones de seguridad privada</mark></span><span class=\"ref-norma\">Art.  28.5.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Tener conocimientos de lengua castellana suficientes para el normal desempeño de las funciones de seguridad privada\"</span>Se exige un conocimiento suficiente de la lengua castellana."},{"i":"23-ia-1310","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. La carencia o insuficiencia de conocimientos o aptitudes necesarios para el ejercicio en España de funciones de seguridad privada por parte de los nacionales de Estados miembros de la Unión Europea podrá suplirse por aplicación de:","o":["las pruebas de aptitud que establezca el Ministerio del Interior en cada convocatoria, salvo que la autoridad judicial disponga otra cosa.","los períodos de prácticas que determine el centro de formación.","los cursos de adaptación impartidos por las Fuerzas y Cuerpos de Seguridad.","las medidas compensatorias previstas en la normativa vigente sobre reconocimiento de cualificaciones profesionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las medidas compensatorias previstas en la normativa vigente sobre reconocimiento de cualificaciones profesionales</mark></span><span class=\"ref-norma\">Art.  28.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrá suplirse por aplicación de las medidas compensatorias previstas en la normativa vigente sobre reconocimiento de cualificaciones profesionales\"</span>Se suple con medidas compensatorias de la normativa de reconocimiento de cualificaciones."}]},{"a":"Artículo 36","q":[{"i":"23-95","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La identificación, análisis y evaluación de situaciones de riesgo que puedan afectar a la vida e integridad de las personas y al patrimonio, será una función de:","o":["Los Jefes de seguridad.","Los escoltas privados.","Vigilantes de seguridad.","Los Directores de seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los Directores de seguridad</mark></span><span class=\"ref-norma\">Art. 36.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La identificación, análisis y evaluación de situaciones de riesgo que puedan afectar a la vida e integridad de las personas y al patrimonio\"</span>"},{"i":"23-123","p":"Ley 5/2014, de Seguridad Privada. ¿Cuándo los usuarios de seguridad privada situarán al frente de la seguridad integral de la entidad, empresa o grupo empresarial a un director de seguridad?","o":["Cuando así lo exija la normativa de desarrollo de la Ley de seguridad privada por la dimensión de su servicio de seguridad.","Cuando se acuerde por decisión judicial, en atención a las medidas de seguridad y al grado de concentración de riesgo.","Cuando lo prevea una disposición general.","Todas las opciones anteriores son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando así lo exija la normativa de desarrollo de la Ley de seguridad privada por la dimensión de su servicio de seguridad</mark></span><span class=\"ref-norma\">Art. 36 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los usuarios de seguridad privada situarán al frente de la seguridad integral de la entidad, empresa o grupo empresarial a un director de seguridad cuando así lo exija la normativa de desarrollo de esta ley por la dimensión de su servicio de seguridad; cuando se acuerde por decisión gubernativa, en atención a las medidas de seguridad y al grado de concentración de riesgo, o cuando lo prevea una disposición especial.\"</span>"},{"i":"23-124","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada, en relación con la empresa o entidad en la que presten sus servicios, corresponde a los directores de seguridad el ejercicio de las siguientes funciones:","o":["La garantía de la colaboración de los servicios de seguridad con los de las correspondientes dependencias de las Fuerzas y Cuerpos de Seguridad.","La trayectoria de la documentación de la normativa de seguridad privada aplicada.","La responsabilidad sobre la custodia y el tratamiento de armas de seguridad de la empresa a la que pertenezca, de acuerdo con la normativa de armas y con lo que reglamentariamente se determine.","La comprobación de que los sistemas de seguridad privada instalados y las empresas de seguridad privada contratadas, cumplen con las exigencias de homologación de los organismos competentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La comprobación de que los sistemas de seguridad privada instalados y las empresas de seguridad privada contratadas, cumplen con las exigencias de homologación de los organismos competentes</mark></span><span class=\"ref-norma\">Art. 36 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"f) La comprobación de que los sistemas de seguridad privada instalados y las empresas de seguridad privada contratadas, cumplen con las exigencias de homologación de los organismos competentes.\"</span>"},{"i":"23-ia-1343","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Directores de seguridad. Los usuarios de seguridad privada situarán al frente de la seguridad integral de la entidad, empresa o grupo empresarial a un director de seguridad cuando así lo exija la normativa de desarrollo por la dimensión de su servicio de seguridad; cuando se acuerde por decisión gubernativa, en atención a las medidas de seguridad y al grado de concentración de riesgo, o cuando:","o":["lo soliciten las Fuerzas y Cuerpos de Seguridad.","lo acuerde la comisión mixta de seguridad privada.","lo prevea una disposición especial.","lo determine el contrato con la empresa de seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">lo prevea una disposición especial</mark></span><span class=\"ref-norma\">Art.  36.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o cuando lo prevea una disposición especial\"</span>O cuando lo prevea una disposición especial."},{"i":"23-ia-1344","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Directores de seguridad. En las empresas de seguridad el director de seguridad podrá:","o":["sustituir al jefe de seguridad en todo caso.","compatibilizar sus funciones con las de jefe de seguridad.","desempeñar sus funciones sin estar integrado en plantilla, salvo que la autoridad judicial disponga otra cosa.","ejercer funciones de detective privado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">compatibilizar sus funciones con las de jefe de seguridad</mark></span><span class=\"ref-norma\">Art.  36.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"En las empresas de seguridad el director de seguridad podrá compatibilizar sus funciones con las de jefe de seguridad\"</span>Puede compatibilizar con las de jefe de seguridad."},{"i":"23-ia-1345","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Directores de seguridad. Cuando una empresa de seguridad preste servicio a un usuario que cuente con su propio director de seguridad, las funciones de análisis de riesgos, organización, propuesta de sistemas y coordinación encomendadas a los jefes de seguridad serán asumidas por:","o":["dicho director de seguridad.","el jefe de seguridad de la empresa, bajo supervisión del director.","el responsable del servicio designado por el usuario.","el director de seguridad de la empresa prestadora."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dicho director de seguridad</mark></span><span class=\"ref-norma\">Art.  36.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"serán asumidas por dicho director de seguridad\"</span>Las asume el director de seguridad del usuario."},{"i":"23-ia-1346","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Detectives privados. Los detectives privados se encargarán de la ejecución personal de los servicios de investigación privada, mediante la realización de averiguaciones en relación con:","o":["personas, bienes y hechos delictivos privados.","hechos delictivos y conductas privadas.","personas y bienes en el ámbito privado.","personas, hechos y conductas privadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">personas, hechos y conductas privadas</mark></span><span class=\"ref-norma\">Art.  37.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"mediante la realización de averiguaciones en relación con personas, hechos y conductas privadas\"</span>Personas, hechos y conductas privadas."},{"i":"23-ia-1347","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Detectives privados. En el ejercicio de sus funciones, los detectives privados vendrán obligados a confeccionar los informes de investigación relativos a los asuntos que tuvieren encargados, asegurar la necesaria colaboración con las Fuerzas y Cuerpos de Seguridad y:","o":["entregar copia de sus informes a las Fuerzas y Cuerpos de Seguridad.","comunicar los informes al Ministerio del Interior en el plazo de diez días, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente.","ratificar el contenido de sus informes de investigación ante las autoridades judiciales o policiales cuando fueren requeridos para ello.","ratificar los informes ante notario cuando lo solicite el cliente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ratificar el contenido de sus informes de investigación ante las autoridades judiciales o policiales cuando fueren requeridos para ello</mark></span><span class=\"ref-norma\">Art.  37.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Ratificar el contenido de sus informes de investigación ante las autoridades judiciales o policiales cuando fueren requeridos para ello\"</span>Ratifican sus informes ante las autoridades judiciales o policiales cuando se les requiera."},{"i":"23-ia-1348","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Detectives privados. El ejercicio de las funciones correspondientes a los detectives privados no será compatible con:","o":["las funciones de director de seguridad, aunque sí con las de jefe de seguridad.","las funciones del resto del personal de seguridad privada, ni con funciones propias del personal al servicio de cualquier Administración Pública.","otras profesiones, salvo la de abogado.","las funciones del personal de seguridad privada, pero sí con las de personal al servicio de la Administración, en los términos que se determinen reglamentariamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las funciones del resto del personal de seguridad privada, ni con funciones propias del personal al servicio de cualquier Administración Pública</mark></span><span class=\"ref-norma\">Art.  37.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no será compatible con las funciones del resto del personal de seguridad privada, ni con funciones propias del personal al servicio de cualquier Administración Pública\"</span>Incompatible con el resto del personal de seguridad privada y con el personal al servicio de las Administraciones."}]},{"a":"Artículo 3","q":[{"i":"23-96","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ámbito de aplicación. Las disposiciones de esta Ley son de aplicación: Señale la correcta.","o":["A la fabricación, comercialización, venta, entrega, instalación o mantenimiento de elementos o productos de seguridad y de contratación de seguridad.","A las empresas de seguridad privada, al personal de seguridad privada, a los despachos de detectives, a los servicios de seguridad privada, a las medidas de seguridad y a los contratos celebrados en este ámbito.","A las centrales receptoras de alarmas de sistemas de prevención o protección contra incendios o de alarmas de tipo técnico o asistencial, o de sistemas o servicios de control o mantenimiento.","A la planificación, consultoría y asesoramiento en materia de actividades de seguridad privada, que consistirá en la elaboración de estudios e informes de seguridad, análisis de riesgos y planes de seguridad integrales, a la protección frente a todo tipo de riesgos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A las empresas de seguridad privada, al personal de seguridad privada, a los despachos de detectives, a los servicios de seguridad privada, a las medidas de seguridad y a los contratos celebrados en este ámbito</mark></span><span class=\"ref-norma\">Art. 3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las disposiciones de esta ley son de aplicación a las empresas de seguridad privada, al personal de seguridad privada, a los despachos de detectives, a los servicios de seguridad privada, a las medidas de seguridad y a los contratos celebrados en éste ámbito.\"</span>"},{"i":"23-135","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ámbito de aplicación. El régimen sancionador y las medidas provisionales, así como el ejercicio de las facultades de inspección, serán también aplicables a aquellas empresas y personal que presten servicios o ejerzan funciones de seguridad privada:","o":["Sin estar inscritas en el Registro Nacional de Seguridad Privada, aunque cuenten con autorización administrativa o declaración responsable, sin perjuicio de lo que establezcan los tratados internacionales.","Habiendo presentado declaración responsable, pero sin haber comunicado los contratos al Ministerio del Interior.","Sin estar autorizadas, aunque estén habilitados o acreditados para el ejercicio legal de los mismos.","Sin estar autorizadas o haber presentado declaración responsable, o sin estar habilitados o acreditados para el ejercicio legal de los mismos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sin estar autorizadas o haber presentado declaración responsable, o sin estar habilitados o acreditados para el ejercicio legal de los mismos</mark></span><span class=\"ref-norma\">Art. 3.3 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"serán también aplicables a aquellas empresas y personal que presten servicios o ejerzan funciones de seguridad privada sin estar autorizadas o haber presentado declaración responsable, o sin estar habilitados o acreditados para el ejercicio legal de los mismos\"</span>"},{"i":"23-ia-1023","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ámbito de aplicación. Las disposiciones de la ley se aplicarán igualmente, en la medida que resulte pertinente en cada caso, a los establecimientos obligados a disponer de medidas de seguridad, a los usuarios de los servicios de seguridad privada, a los ingenieros y técnicos de las empresas de seguridad, a los operadores de seguridad, a los profesores de centros de formación, a las empresas prestadoras de servicios de seguridad informática y a:","o":["las centrales receptoras de alarmas de uso propio y a las entidades de certificación, salvo que la autoridad judicial disponga otra cosa.","las empresas de servicios de seguridad no habilitadas y a los centros de formación.","las centrales receptoras de alarmas de uso propio y a los centros de formación de personal de seguridad privada.","los despachos de detectives y a las centrales receptoras de alarmas ajenas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las centrales receptoras de alarmas de uso propio y a los centros de formación de personal de seguridad privada</mark></span><span class=\"ref-norma\">Art.  3.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a las centrales receptoras de alarmas de uso propio y a los centros de formación de personal de seguridad privada\"</span>Cierran la lista las centrales de alarmas de uso propio y los centros de formación."},{"i":"23-ia-1024","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Ámbito de aplicación. El régimen sancionador y las medidas provisionales, así como el ejercicio de las facultades de inspección, serán también aplicables a aquellas empresas y personal que presten servicios o ejerzan funciones de seguridad privada:","o":["sin estar inscritas en el Registro Nacional de Seguridad Privada o sin haber comunicado su actividad.","sin estar autorizadas o haber presentado declaración responsable, o sin estar habilitados o acreditados.","sin estar autorizadas o sin haber obtenido la homologación de sus medios.","sin la debida autorización, aunque estén habilitados o acreditados para el ejercicio legal de los mismos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin estar autorizadas o haber presentado declaración responsable, o sin estar habilitados o acreditados</mark></span><span class=\"ref-norma\">Art.  3.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que presten servicios o ejerzan funciones de seguridad privada sin estar autorizadas o haber presentado declaración responsable, o sin estar habilitados o acreditados para el ejercicio legal de los mismos\"</span>Alcanza al intrusismo: sin autorización o declaración responsable, o sin habilitación o acreditación."},{"i":"23-ia-1025","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Fines. Entre los fines de la seguridad privada está satisfacer las necesidades legítimas de seguridad o de información de los usuarios de seguridad privada, velando por:","o":["la indemnidad o privacidad de las personas o bienes cuya seguridad o investigación se le encomiende.","la integridad y confidencialidad de las personas o bienes cuya seguridad se le encomiende.","la indemnidad o privacidad de las personas o bienes frente a cualquier vulneración de derechos, previo informe de la unidad policial competente.","la seguridad jurídica de las personas o bienes cuya protección se le encomiende."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la indemnidad o privacidad de las personas o bienes cuya seguridad o investigación se le encomiende</mark></span><span class=\"ref-norma\">Art.  4.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"velando por la indemnidad o privacidad de las personas o bienes cuya seguridad o investigación se le encomiende\"</span>Debe velar por la indemnidad o privacidad de personas o bienes."},{"i":"23-ia-1026","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Fines. La seguridad privada tiene como fin complementar el __________ de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública:","o":["ejercicio, sin perjuicio de lo previsto en la normativa vigente.","mandato","control","monopolio"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">monopolio</mark></span><span class=\"ref-norma\">Art.  4.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Complementar el monopolio de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública\"</span>Complementa el monopolio de la seguridad que corresponde al Estado."},{"i":"23-ia-1027","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Fines. Señale cuál NO es un fin de la seguridad privada:","o":["Contribuir a garantizar la seguridad pública, a prevenir infracciones y a aportar información a los procedimientos relacionados con sus actuaciones e investigaciones.","Complementar el monopolio de la seguridad que corresponde al Estado, integrando funcionalmente sus medios y capacidades como un recurso externo de la seguridad pública.","Sustituir al Estado en la prevención de las infracciones de mayor gravedad.","Satisfacer las necesidades legítimas de seguridad o de información de los usuarios de seguridad privada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sustituir al Estado en la prevención de las infracciones de mayor gravedad</mark></span><span class=\"ref-norma\">Art.  4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La seguridad privada tiene como fines: a) Satisfacer las necesidades legítimas de seguridad o de información de los usuarios de seguridad privada\"</span>La seguridad privada complementa, no sustituye, a la seguridad pública."}]},{"a":"Artículo 11","q":[{"i":"23-103","p":"Seguridad pública y privada. Ley 5/2014. Registro nacional y autonómico de seguridad privada. Señale la INCORRECTA.","o":["Mediante ley se regula la organización y funcionamiento del Registro Nacional de Seguridad Privada.","Las autoridades responsables del Registro Nacional y de los registros autonómicos establecerán los mecanismos de colaboración y reciprocidad necesarios para permitir su interconexión e interoperabilidad.","Los órganos competentes de las mencionadas comunidades autónomas deberán comunicar al Registro Nacional de Seguridad Privada los datos de las inscripciones.","Dichos registros serán públicos exclusivamente en cuanto a los asientos referentes a la denominación o razón social, domicilio, número de identificación fiscal y actividades en relación con las cuales estén autorizadas o hayan presentado la declaración responsable por empresas de seguridad privada, despachos de detectives, centros de formación del personal de seguridad privada y centros de control de alarmas de uso propio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mediante ley se regula la organización y funcionamiento del Registro Nacional de Seguridad Privada</mark></span><span class=\"ref-norma\">Art. 11 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Reglamentariamente se regulará la organización y funcionamiento del Registro Nacional de Seguridad Privada.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-108","p":"Ley 5/2014, de Seguridad Privada. Serán objeto de inscripción de oficio en el Registro Nacional de Seguridad Privada del Ministerio del Interior: Señale la opción incorrecta.","o":["El personal de seguridad privada.","Los particulares contratantes de servicios.","Los despachos de detectives privados.","Las empresas de seguridad privada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los particulares contratantes de servicios</mark></span><span class=\"ref-norma\">Art. 11.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"el personal de seguridad privada, las empresas de seguridad privada y los despachos de detectives privados, así como delegaciones y sucursales, los centros de formación del personal de seguridad privada y las centrales receptoras de alarma de uso propio\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-131","p":"La Ley 5/2014, de 4 de abril, de Seguridad Privada. Registro nacional de Seguridad Privada y registros Autonómicos. Serán objeto de inscripción de oficio en el Registro Nacional de Seguridad Privada del:","o":["Dirección General de la Policía.","Dirección General de la Guardia Civil.","Ministerio del Interior.","Ministerio de Defensa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 11 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Registro Nacional de Seguridad Privada y registros autonómicos.\"</span>"},{"i":"23-ia-1128","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Registro Nacional de Seguridad Privada. En el Registro Nacional de Seguridad Privada del Ministerio del Interior se inscribirán de oficio, entre otros, el personal de seguridad privada, las empresas de seguridad privada y los despachos de detectives privados, así como delegaciones y sucursales, los centros de formación y las centrales receptoras de alarma de uso propio, cuando:","o":["su ámbito de actuación exceda del territorio de una comunidad autónoma, en los términos que se determinen reglamentariamente.","no sean objeto de inscripción en los registros de las comunidades autónomas.","así lo soliciten sus titulares ante el Ministerio del Interior.","tengan su domicilio fuera del territorio de las comunidades autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no sean objeto de inscripción en los registros de las comunidades autónomas</mark></span><span class=\"ref-norma\">Art.  11.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando no sean objeto de inscripción en los registros de las comunidades autónomas\"</span>Se inscriben en el Registro Nacional cuando no lo sean en los autonómicos."},{"i":"23-ia-1129","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Registro Nacional de Seguridad Privada. Igualmente, se inscribirán en el Registro Nacional de Seguridad Privada las sanciones impuestas en materia de seguridad privada, las comunicaciones de los contratos y sus modificaciones y cuantos datos sean necesarios para las actuaciones de control y gestión, cuando se refieran a servicios que se presten:","o":["en un ámbito territorial distinto al de una comunidad autónoma con competencia en materia de seguridad privada.","en el territorio de más de dos comunidades autónomas.","en el ámbito territorial propio de una comunidad autónoma con competencia en la materia, salvo que la autoridad judicial disponga otra cosa.","por empresas con domicilio fuera del territorio nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en un ámbito territorial distinto al de una comunidad autónoma con competencia en materia de seguridad privada</mark></span><span class=\"ref-norma\">Art.  11.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuando tales sanciones, comunicaciones y datos se refieran a servicios de seguridad privada que se presten en un ámbito territorial distinto al de una comunidad autónoma con competencia en materia de seguridad privada\"</span>Servicios en un ámbito distinto al de una comunidad autónoma con competencia."},{"i":"23-ia-1130","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Registro Nacional de Seguridad Privada. Los órganos competentes de las comunidades autónomas con competencia en la materia deberán comunicar al Registro Nacional de Seguridad Privada los datos de las inscripciones y anotaciones que efectúen sobre las empresas de seguridad privada que inscriban, así como sus:","o":["sanciones y cancelaciones.","altas y bajas.","modificaciones y resoluciones sancionadoras.","modificaciones y cancelaciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">modificaciones y cancelaciones</mark></span><span class=\"ref-norma\">Art.  11.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como sus modificaciones y cancelaciones\"</span>Deben comunicar también las modificaciones y cancelaciones."},{"i":"23-ia-1131","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Registro Nacional de Seguridad Privada. En los registros, nacional y autonómicos, se anotarán también los datos de las empresas que realicen actividades de:","o":["planificación y consultoría de seguridad, de acuerdo con la legislación autonómica.","fabricación e instalación de equipos de seguridad, previa solicitud.","seguridad informática, de acuerdo con lo que reglamentariamente se determine.","formación de personal de seguridad privada, de acuerdo con lo que se determine por orden."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seguridad informática, de acuerdo con lo que reglamentariamente se determine</mark></span><span class=\"ref-norma\">Art.  11.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se anotarán también los datos de las empresas que realicen actividades de seguridad informática, de acuerdo con lo que reglamentariamente se determine\"</span>Se anotan las empresas de seguridad informática."},{"i":"23-ia-1132","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Registro Nacional de Seguridad Privada. Los registros de seguridad privada serán públicos exclusivamente en cuanto a los asientos referentes a la denominación o razón social, domicilio, número de identificación fiscal y:","o":["ámbito territorial en el que presten sus servicios y número de empleados, previo informe de la unidad policial competente.","actividades en relación con las cuales estén autorizadas o hayan presentado la declaración responsable.","fecha de inscripción y personal habilitado de la empresa.","sanciones firmes impuestas y actividades autorizadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">actividades en relación con las cuales estén autorizadas o hayan presentado la declaración responsable</mark></span><span class=\"ref-norma\">Art.  11.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"domicilio, número de identificación fiscal y actividades en relación con las cuales estén autorizadas o hayan presentado la declaración responsable\"</span>Son públicos solo los datos identificativos y las actividades autorizadas o declaradas."},{"i":"23-ia-1133","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de la Administración General del Estado. Corresponde a la Administración General del Estado, a través del Ministerio del Interior y, en su caso, de las Delegaciones y Subdelegaciones del Gobierno, la autorización o recepción de la declaración responsable, inspección y sanción de las empresas de seguridad privada y de sus delegaciones:","o":["cuya competencia no haya sido asumida por las comunidades autónomas.","con ámbito de actuación superior al de una comunidad autónoma, sin perjuicio de lo previsto en la normativa vigente.","inscritas en el Registro Nacional de Seguridad Privada.","que presten servicios a las Administraciones públicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuya competencia no haya sido asumida por las comunidades autónomas</mark></span><span class=\"ref-norma\">Art.  12.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuya competencia no haya sido asumida por las comunidades autónomas\"</span>Solo cuando la competencia no haya sido asumida por las comunidades autónomas."},{"i":"23-ia-1134","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de la Administración General del Estado. Corresponde a la Administración General del Estado la habilitación e inhabilitación del personal de seguridad privada, y la determinación del armamento, documentación, uniformidad, distintivos y medios de defensa de dicho personal, así como la acreditación, en todo caso, de:","o":["los profesores de los centros de formación y de los operadores de seguridad.","los directores de seguridad y de los jefes de seguridad.","los ingenieros y técnicos de las empresas de seguridad y de los detectives privados, en los términos que se determinen reglamentariamente.","los ingenieros y técnicos de las empresas de seguridad y de los operadores de seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los ingenieros y técnicos de las empresas de seguridad y de los operadores de seguridad</mark></span><span class=\"ref-norma\">Art.  12.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como la acreditación, en todo caso, de los ingenieros y técnicos de las empresas de seguridad y de los operadores de seguridad\"</span>Acredita siempre a ingenieros y técnicos y a operadores de seguridad."},{"i":"23-ia-1135","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de la Administración General del Estado. Corresponde a la Administración General del Estado la recepción de la declaración responsable, inspección y sanción de los centros de formación del personal de seguridad privada cuya competencia no haya sido asumida por las comunidades autónomas, así como la acreditación, en todo caso, de:","o":["sus instalaciones.","sus programas de formación.","su profesorado.","sus aspirantes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su profesorado</mark></span><span class=\"ref-norma\">Art.  12.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como la acreditación, en todo caso, de su profesorado\"</span>Se acredita siempre a su profesorado."},{"i":"23-ia-1136","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de la Administración General del Estado. Corresponde a la Administración General del Estado la coordinación de los servicios de seguridad e investigación privadas con:","o":["los de las policías autonómicas y locales.","los de las Fuerzas y Cuerpos de Seguridad del Estado.","los de las Juntas Locales de Seguridad.","los de las Delegaciones y Subdelegaciones del Gobierno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los de las Fuerzas y Cuerpos de Seguridad del Estado</mark></span><span class=\"ref-norma\">Art.  12.1.k · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La coordinación de los servicios de seguridad e investigación privadas con los de las Fuerzas y Cuerpos de Seguridad del Estado\"</span>Coordina con las Fuerzas y Cuerpos de Seguridad del Estado."},{"i":"23-ia-1137","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de la Administración General del Estado. En el ámbito de las competencias de la Administración General del Estado, corresponde a la Dirección General de la Policía:","o":["el control de las empresas, entidades y servicios privados de seguridad, vigilancia e investigación, de su personal, medios y actuaciones.","el ejercicio de sus competencias en materia de armas sobre las empresas y el personal de seguridad privada, salvo que la autoridad judicial disponga otra cosa.","el control de los guardas rurales y sus especialidades.","el control de las empresas de seguridad con sede en comunidades autónomas con policía propia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el control de las empresas, entidades y servicios privados de seguridad, vigilancia e investigación, de su personal, medios y actuaciones</mark></span><span class=\"ref-norma\">Art.  12.2.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Corresponde a la Dirección General de la Policía el control de las empresas, entidades y servicios privados de seguridad, vigilancia e investigación, de su personal, medios y actuaciones\"</span>La Policía controla empresas, servicios, personal, medios y actuaciones."},{"i":"23-ia-1138","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Competencias de la Administración General del Estado. Corresponde a la Dirección General de la Guardia Civil el ejercicio de sus competencias en materia de armas sobre las empresas y el personal de seguridad privada, así como el control de:","o":["los vigilantes de explosivos y los escoltas privados.","los detectives privados y sus despachos.","los operadores de seguridad y sus centrales.","los guardas rurales y sus especialidades."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los guardas rurales y sus especialidades</mark></span><span class=\"ref-norma\">Art.  12.2.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"así como el control de los guardas rurales y sus especialidades\"</span>La Guardia Civil controla a los guardas rurales y sus especialidades."}]},{"a":"Artículo 8","q":[{"i":"23-105","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Señale la INCORRECTA.","o":["El secretario de estado de seguridad prohibirá la utilización en los servicios de seguridad privada de determinados medios materiales o técnicos cuando pudieran causar daños o perjuicios a terceros.","Los prestadores de servicios de seguridad privada colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de seguridad.","Los servicios y funciones de seguridad privada se prestarán con respeto a la Constitución.","El personal de seguridad privada tendrán prohibido comunicar a terceros, salvo a las autoridades judiciales y policiales para el ejercicio de sus respectivas funciones, cualquier información que conozcan por el desarrollo de sus servicios."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El secretario de estado de seguridad prohibirá la utilización en los servicios de seguridad privada de determinados medios materiales o técnicos cuando pudieran causar daños o perjuicios a terceros</mark></span><span class=\"ref-norma\">Art. 8 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El Ministro del Interior o, en su caso, el titular del órgano autonómico competente prohibirá la utilización en los servicios de seguridad privada de determinados medios materiales o técnicos cuando pudieran causar daños o perjuicios a terceros o poner en peligro la seguridad ciudadana.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-129","p":"Ley 5/2014, de Seguridad Privada. Los prestadores de servicios de seguridad privada:","o":["Colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de Seguridad, con sujeción a lo que éstas puedan disponer en relación con la ejecución material de sus actividades.","Colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de Seguridad, con sujeción a lo que éstas puedan disponer en relación con la gestión de sus actividades.","Colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de Seguridad, sin sujeción a lo que éstas puedan disponer en relación con la ejecución material de sus actividades.","Colaborarán, en caso de emergencia, con las Fuerzas y Cuerpos de Seguridad, con sujeción a lo que éstas puedan disponer en relación con la ejecución material de sus actividades."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de Seguridad, con sujeción a lo que éstas puedan disponer en relación con la ejecución material de sus actividades</mark></span><span class=\"ref-norma\">Art. 8 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los prestadores de servicios de seguridad privada colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de Seguridad, con sujeción a lo que éstas puedan disponer en relación con la ejecución material de sus actividades.\"</span>"},{"i":"23-ia-1112","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Los servicios y funciones de seguridad privada se prestarán con respeto a la Constitución, a lo dispuesto en la ley, especialmente en lo referente a los principios de actuación, y al:","o":["Estatuto de los Trabajadores.","resto del ordenamiento jurídico.","Código Penal y la Ley de Enjuiciamiento Criminal.","régimen de las Fuerzas y Cuerpos de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">resto del ordenamiento jurídico</mark></span><span class=\"ref-norma\">Art.  8.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y al resto del ordenamiento jurídico\"</span>Han de respetar el resto del ordenamiento jurídico."},{"i":"23-ia-1113","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Los prestadores de servicios de seguridad privada colaborarán, en todo momento y lugar, con las Fuerzas y Cuerpos de Seguridad, con sujeción a lo que éstas puedan disponer en relación con:","o":["la ejecución material de sus actividades.","la planificación operativa de sus servicios.","la comunicación de las incidencias detectadas.","el ejercicio de las funciones de investigación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la ejecución material de sus actividades</mark></span><span class=\"ref-norma\">Art.  8.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"con sujeción a lo que éstas puedan disponer en relación con la ejecución material de sus actividades\"</span>La sujeción se refiere a la ejecución material de sus actividades."},{"i":"23-ia-1114","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Las empresas de seguridad, los despachos de detectives y el personal de seguridad privada tendrán especial obligación de auxiliar y colaborar, en todo momento, con las Fuerzas y Cuerpos de Seguridad en el ejercicio de sus funciones, de prestarles su colaboración y de:","o":["informar de sus actuaciones, en relación con los servicios que presten en lugares públicos.","seguir sus instrucciones en cualquier servicio, con independencia de su relación con la seguridad pública, salvo que la autoridad judicial disponga otra cosa.","atender sus requerimientos, salvo cuando afecten al secreto profesional.","seguir sus instrucciones, en relación con los servicios que presten que afecten a la seguridad pública o al ámbito de sus competencias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seguir sus instrucciones, en relación con los servicios que presten que afecten a la seguridad pública o al ámbito de sus competencias</mark></span><span class=\"ref-norma\">Art.  8.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"de seguir sus instrucciones, en relación con los servicios que presten que afecten a la seguridad pública o al ámbito de sus competencias\"</span>Deben seguir sus instrucciones en los servicios que afecten a la seguridad pública o a sus competencias."},{"i":"23-ia-1115","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Las empresas, los despachos y el personal de seguridad privada, mientras estén ejerciendo los servicios y funciones que les son propios, no podrán intervenir ni interferir en:","o":["las actuaciones de las Fuerzas y Cuerpos de Seguridad, salvo requerimiento expreso.","la celebración de espectáculos públicos, ni en el desarrollo de conflictos laborales.","la celebración de reuniones y manifestaciones, ni en el desarrollo de conflictos políticos o laborales.","las reuniones y manifestaciones, salvo que se desarrollen en establecimientos de su titularidad, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la celebración de reuniones y manifestaciones, ni en el desarrollo de conflictos políticos o laborales</mark></span><span class=\"ref-norma\">Art.  8.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No podrán intervenir ni interferir, mientras estén ejerciendo los servicios y funciones que les son propios, en la celebración de reuniones y manifestaciones, ni en el desarrollo de conflictos políticos o laborales\"</span>No pueden interferir en reuniones y manifestaciones ni en conflictos políticos o laborales."},{"i":"23-ia-1116","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. El personal de seguridad privada no podrá ejercer ningún tipo de control sobre opiniones políticas, sindicales o religiosas, o sobre la expresión de tales opiniones, ni proceder al tratamiento, automatizado o no, de datos relacionados con:","o":["la ideología, afiliación sindical, religión o vida privada.","la ideología, afiliación sindical, religión o creencias.","la afiliación política, sindical o religiosa y el origen racial.","la ideología, la salud y las creencias de los usuarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la ideología, afiliación sindical, religión o creencias</mark></span><span class=\"ref-norma\">Art.  8.4.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"ni proceder al tratamiento, automatizado o no, de datos relacionados con la ideología, afiliación sindical, religión o creencias\"</span>Datos de ideología, afiliación sindical, religión o creencias."},{"i":"23-ia-1117","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Las empresas, los despachos y el personal de seguridad privada tendrán prohibido comunicar a terceros cualquier información que conozcan en el desarrollo de sus servicios sobre sus clientes, salvo a:","o":["las autoridades judiciales y policiales para el ejercicio de sus respectivas funciones.","las autoridades administrativas competentes en materia de seguridad privada.","las autoridades judiciales y al Ministerio Fiscal en el ejercicio de sus funciones, sin perjuicio de lo previsto en la normativa vigente.","las Fuerzas y Cuerpos de Seguridad, siempre que medie requerimiento escrito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las autoridades judiciales y policiales para el ejercicio de sus respectivas funciones</mark></span><span class=\"ref-norma\">Art.  8.4.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"salvo a las autoridades judiciales y policiales para el ejercicio de sus respectivas funciones\"</span>La excepción es para autoridades judiciales y policiales."},{"i":"23-ia-1118","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. El Ministro del Interior o, en su caso, el titular del órgano autonómico competente prohibirá la utilización en los servicios de seguridad privada de determinados medios materiales o técnicos cuando pudieran causar daños o perjuicios a terceros o poner en peligro:","o":["la seguridad pública.","el orden público.","la integridad de los usuarios.","la seguridad ciudadana."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la seguridad ciudadana</mark></span><span class=\"ref-norma\">Art.  8.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"o poner en peligro la seguridad ciudadana\"</span>La prohibición procede si ponen en peligro la seguridad ciudadana."},{"i":"23-ia-1119","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Principios rectores. Cuando el personal de seguridad privada desempeñe sus funciones en entidades en las que se presten servicios esenciales, habrá de atenerse, en el ejercicio del derecho de huelga, a:","o":["lo que acuerden las empresas de seguridad con los representantes sindicales.","lo que disponga el Ministerio del Interior en cada caso.","lo que respecto de dichas entidades disponga la legislación vigente.","lo que fije el convenio colectivo aplicable."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">lo que respecto de dichas entidades disponga la legislación vigente</mark></span><span class=\"ref-norma\">Art.  8.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"habrán de atenerse, en el ejercicio del derecho de huelga, a lo que respecto de dichas entidades disponga la legislación vigente\"</span>Se atienen a la legislación vigente aplicable a dichas entidades."}]},{"a":"Artículo 65","q":[{"i":"23-114","p":"Ley 5/2014, de Seguridad Privada. Las sanciones previstas en esta ley podrán aplicarse de forma:","o":["Alternativa o acumulativa.","Directa o indirecta.","Absoluta o parcial.","Individual o colectiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Alternativa o acumulativa</mark></span><span class=\"ref-norma\">Art. 65 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Las sanciones previstas en esta ley podrán aplicarse de forma alternativa o acumulativa.\"</span>"},{"i":"23-ia-1602","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Aplicación de las sanciones. Las sanciones previstas en la Ley de Seguridad Privada podrán aplicarse de forma:","o":["exclusivamente acumulativa.","alternativa, nunca acumulativa.","sucesiva y gradual.","alternativa o acumulativa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">alternativa o acumulativa</mark></span><span class=\"ref-norma\">Art.  65.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrán aplicarse de forma alternativa o acumulativa\"</span>Alternativa o acumulativa."},{"i":"23-ia-1603","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Aplicación de las sanciones. La aplicación de sanciones pecuniarias tenderá a evitar que:","o":["la cuantía de la sanción exceda de la capacidad económica del infractor, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa.","la sanción impuesta resulte desproporcionada con el perjuicio causado.","la comisión de las infracciones tipificadas no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas.","la reincidencia en la infracción quede sin sanción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la comisión de las infracciones tipificadas no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas</mark></span><span class=\"ref-norma\">Art.  65.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"tenderá a evitar que la comisión de las infracciones tipificadas no resulte más beneficiosa para el infractor que el cumplimiento de las normas infringidas\"</span>Evitar que infringir resulte más beneficioso que cumplir."}]},{"a":"Artículo 25","q":[{"i":"23-116","p":"Ley 5/2014, de Seguridad Privada. Cuando para la realización de un servicio se recurra a la subcontratación entre despachos de detectives privados:","o":["Se cometerá una falta muy grave, sancionada con la suspensión temporal de la declaración responsable de ambos despachos por un plazo de entre seis meses y un año.","Se contempla como excepción a la regla general prevista en el art. 23.1.","Subsistirá la obligación de formularse por escrito un contrato por cada servicio de investigación que les sea encargado, comunicando su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente en la forma que reglamentariamente se determine.","Todas las opciones anteriores son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Subsistirá la obligación de formularse por escrito un contrato por cada servicio de investigación que les sea encargado, comunicando su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente en la forma que reglamentariamente se determine</mark></span><span class=\"ref-norma\">Art. 25 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"a) Formalizar por escrito un contrato por cada servicio de investigación que les sea encargado, comunicando su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente en la forma que reglamentariamente se determine.\"</span>"},{"i":"23-117","p":"Ley 5/2014, de Seguridad Privada. ¿Con qué periodicidad los despachos de detectives privados y sus sucursales deberán presentar al Ministerio del Interior o, en su caso, al órgano autonómico competente, una memoria de actividades?","o":["Anualmente.","Trimestralmente.","Semestralmente.","Mensualmente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Anualmente</mark></span><span class=\"ref-norma\">Art. 25 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"i) Presentar al Ministerio del Interior o, en su caso, al órgano autonómico competente, una memoria anual de actividades del año precedente, con la información que se determine reglamentariamente, que no podrá contener datos de carácter personal sobre contratantes o investigados.\"</span>"},{"i":"23-118","p":"Ley 5/2014, de Seguridad Privada. Los despachos de detectives privados y sus sucursales deberán llevar un libro-registro con el formato que reglamentariamente se determine, en el que se anotará cada servicio de investigación:","o":["Contratado o realizado.","Realizado o subcontratado.","Contratado o subcontratado.","Realizado, contratado o subcontratado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Contratado o subcontratado</mark></span><span class=\"ref-norma\">Art. 25 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"b) Llevar un libro-registro, con el formato que reglamentariamente se determine, en el que se anotará cada servicio de investigación contratado o subcontratado.\"</span>"},{"i":"23-ia-1241","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. Los despachos de detectives privados y sus sucursales deben formalizar por escrito un contrato por cada servicio de investigación que les sea encargado, comunicando su celebración al Ministerio del Interior o al órgano autonómico competente. Dicha obligación subsistirá igualmente en los casos de:","o":["subcontratación entre despachos.","contratación con las Administraciones públicas.","investigaciones urgentes.","servicios de duración inferior a un mes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">subcontratación entre despachos</mark></span><span class=\"ref-norma\">Art.  25.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Dicha obligación subsistirá igualmente en los casos de subcontratación entre despachos\"</span>También en los casos de subcontratación entre despachos."},{"i":"23-ia-1242","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. En caso de cierre del despacho de detectives por cualquier causa, deberá depositarse la documentación profesional sobre contratos, informes de investigación y libros-registros en:","o":["las dependencias de la Guardia Civil más próximas al domicilio del despacho, salvo que la autoridad judicial disponga otra cosa.","el Registro Nacional de Seguridad Privada.","el juzgado decano de la localidad donde radicaba el despacho.","las dependencias del Cuerpo Nacional de Policía o, en su caso, del cuerpo de policía autonómico competente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las dependencias del Cuerpo Nacional de Policía o, en su caso, del cuerpo de policía autonómico competente</mark></span><span class=\"ref-norma\">Art.  25.1.j · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en las dependencias del Cuerpo Nacional de Policía o, en su caso, del cuerpo de policía autonómico competente\"</span>Se deposita en el Cuerpo Nacional de Policía o en el cuerpo de policía autonómico competente."},{"i":"23-ia-1243","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Obligaciones generales. Los titulares de despachos de detectives responderán civilmente de las acciones u omisiones en que, durante la ejecución de sus servicios, incurran:","o":["los detectives privados dependientes, pero no los asociados.","los colaboradores externos del despacho.","los detectives privados dependientes o asociados.","los detectives dependientes y los administrativos del despacho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los detectives privados dependientes o asociados</mark></span><span class=\"ref-norma\">Art.  25.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Los titulares de despachos de detectives responderán civilmente de las acciones u omisiones en que, durante la ejecución de sus servicios, incurran los detectives privados dependientes o asociados\"</span>Responden de dependientes o asociados."}]},{"a":"Artículo 27","q":[{"i":"23-119","p":"Ley 5/2014, de Seguridad Privada. ¿A qué personal de seguridad privada no habilitará la Dirección General de la Policía?","o":["A los escoltas privados.","A los directores de seguridad.","A los guardas rurales.","A los detectives privados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los guardas rurales</mark></span><span class=\"ref-norma\">Art. 27 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La habilitación de todo el personal de seguridad privada corresponderá a la Dirección General de la Policía, excepto la de los guardas rurales y sus especialidades que corresponderá a la Dirección General de la Guardia Civil.\"</span>"},{"i":"23-ia-1247","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Habilitación profesional. A quienes soliciten la habilitación, previa comprobación de que reúnen los requisitos necesarios, se les expedirá la tarjeta de identidad profesional, que constituirá:","o":["el documento de identificación del personal de seguridad privada, que sustituye al documento nacional de identidad, sin perjuicio de lo previsto en la normativa vigente.","el documento privado de acreditación del personal de seguridad privada ante sus clientes.","el documento público de acreditación del personal de seguridad privada mientras se encuentra en el ejercicio de sus funciones profesionales.","el documento público que habilita para el uso de armas en el ejercicio profesional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el documento público de acreditación del personal de seguridad privada mientras se encuentra en el ejercicio de sus funciones profesionales</mark></span><span class=\"ref-norma\">Art.  27.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La tarjeta de identidad profesional constituirá el documento público de acreditación del personal de seguridad privada mientras se encuentra en el ejercicio de sus funciones profesionales\"</span>Es el documento público de acreditación en el ejercicio de sus funciones."},{"i":"23-ia-1248","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Habilitación profesional. La habilitación de todo el personal de seguridad privada corresponderá a la Dirección General de la Policía, excepto la de los guardas rurales y sus especialidades que corresponderá a:","o":["la Secretaría de Estado de Seguridad.","la Dirección General de la Guardia Civil.","la Delegación del Gobierno correspondiente.","la Dirección General de Tráfico."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Dirección General de la Guardia Civil</mark></span><span class=\"ref-norma\">Art.  27.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"excepto la de los guardas rurales y sus especialidades que corresponderá a la Dirección General de la Guardia Civil\"</span>Los guardas rurales los habilita la Dirección General de la Guardia Civil."}]},{"a":"Artículo 35","q":[{"i":"23-122","p":"Ley 5/2014, de Seguridad Privada. En el ámbito de la empresa de seguridad en cuya plantilla están integrados, corresponde a los jefes de seguridad el ejercicio de las siguientes funciones: Señale la opción incorrecta.","o":["El análisis de situaciones de riesgo y la planificación y programación de las actuaciones previstas para la implantación y realización de los servicios de seguridad privada.","La organización, dirección e inspección del personal y servicios de seguridad privada.","El control de la formación permanente del personal de seguridad de su dependencia, y la propuesta de la adopción de las medidas o iniciativas adecuadas para el cumplimiento de dicha finalidad.","La propuesta de los sistemas de seguridad que resulten pertinentes, y el control de su funcionamiento y mantenimiento, pudiendo validarlos definitivamente, pudiendo, en su caso, ser revocado posteriormente por parte de la Administración."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La propuesta de los sistemas de seguridad que resulten pertinentes, y el control de su funcionamiento y mantenimiento, pudiendo validarlos definitivamente, pudiendo, en su caso, ser revocado posteriormente por parte de la Administración</mark></span><span class=\"ref-norma\">Art. 35 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"c) La propuesta de los sistemas de seguridad que resulten pertinentes, y el control de su funcionamiento y mantenimiento, pudiendo validarlos provisionalmente hasta tanto se produzca la inspección y autorización, en su caso, por parte de la Administración.\"</span>Es la opción incorrecta: altera el texto de la ley."},{"i":"23-ia-1340","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Jefes de seguridad. Señale la función que NO corresponde a los jefes de seguridad en el ámbito de la empresa de seguridad en cuya plantilla están integrados:","o":["El análisis de situaciones de riesgo y la planificación y programación de las actuaciones precisas para la implantación de los servicios.","La comunicación a las Fuerzas y Cuerpos de Seguridad de los hechos delictivos conocidos por los vigilantes de la empresa.","La organización, dirección e inspección del personal y servicios de seguridad privada.","La supervisión de la observancia de la normativa de seguridad privada aplicable."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La comunicación a las Fuerzas y Cuerpos de Seguridad de los hechos delictivos conocidos por los vigilantes de la empresa</mark></span><span class=\"ref-norma\">Art.  35.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"El análisis de situaciones de riesgo y la planificación y programación de las actuaciones precisas para la implantación y realización de los servicios de seguridad privada\"</span>La comunicación de hechos delictivos es función del director de seguridad."},{"i":"23-ia-1341","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Jefes de seguridad. Corresponde a los jefes de seguridad la responsabilidad sobre la custodia y el traslado de armas de titularidad de la empresa a la que pertenezca, de acuerdo con:","o":["la normativa de armas y con lo que reglamentariamente se determine.","las instrucciones de la Intervención de Armas de la Guardia Civil, sin perjuicio de lo previsto en la normativa vigente.","el reglamento de seguridad privada exclusivamente.","las normas internas de la empresa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la normativa de armas y con lo que reglamentariamente se determine</mark></span><span class=\"ref-norma\">Art.  35.1.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"de acuerdo con la normativa de armas y con lo que reglamentariamente se determine\"</span>Conforme a la normativa de armas y lo que se determine reglamentariamente."}]},{"a":"Artículo 9","q":[{"i":"23-125","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. De acuerdo con lo que reglamentariamente se determine, los contratos de prestación de los distintos servicios de seguridad privada deberán, en todo caso:","o":["Formularse por escrito y comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente con anterioridad a la iniciación de los mismos.","Formularse verbalmente o por escrito y comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente con anterioridad a la iniciación de los mismos.","Formularse por escrito y comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente una vez iniciados los mismos.","Formularse por escrito y comunicarse su celebración únicamente a la Delegación del Gobierno correspondiente con anterioridad a la iniciación de los mismos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Formularse por escrito y comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente con anterioridad a la iniciación de los mismos</mark></span><span class=\"ref-norma\">Art. 9 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"De acuerdo con lo que reglamentariamente se determine, los contratos de prestación de los distintos servicios de seguridad privada deberán, en todo caso, formalizarse por escrito y comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente con antelación a la iniciación de los mismos.\"</span>"},{"i":"23-138","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Contratación y comunicación de servicios. No podrá prestarse ningún tipo de servicio de seguridad privada que no haya sido:","o":["Previamente contratado y, en su caso, autorizado.","Previamente comunicado a las Fuerzas y Cuerpos de Seguridad y, en su caso, inscrito.","Previamente contratado por escrito y comunicado al Registro Nacional de Seguridad Privada.","Autorizado por el Ministerio del Interior y comunicado a la comunidad autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Previamente contratado y, en su caso, autorizado</mark></span><span class=\"ref-norma\">Art. 9.1 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"No podrá prestarse ningún tipo de servicio de seguridad privada que no haya sido previamente contratado y, en su caso, autorizado\"</span>"},{"i":"23-ia-1120","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Contratación y comunicación de servicios. No podrá prestarse ningún tipo de servicio de seguridad privada que no haya sido:","o":["previamente contratado y comunicado a las Fuerzas y Cuerpos de Seguridad.","previamente contratado y, en su caso, autorizado.","previamente comunicado y, en su caso, inscrito.","contratado por escrito y autorizado por el Ministerio del Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">previamente contratado y, en su caso, autorizado</mark></span><span class=\"ref-norma\">Art.  9.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"No podrá prestarse ningún tipo de servicio de seguridad privada que no haya sido previamente contratado y, en su caso, autorizado\"</span>Debe estar previamente contratado y, en su caso, autorizado."},{"i":"23-ia-1121","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Contratación y comunicación de servicios. Los contratos de prestación de los distintos servicios de seguridad privada deberán, en todo caso, formalizarse por escrito y comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente:","o":["con antelación a la iniciación de los mismos.","en el plazo de diez días desde su firma.","dentro de los cinco días siguientes a la iniciación de los servicios.","en el plazo de un mes desde la iniciación de los mismos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con antelación a la iniciación de los mismos</mark></span><span class=\"ref-norma\">Art.  9.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"comunicarse su celebración al Ministerio del Interior o, en su caso, al órgano autonómico competente con antelación a la iniciación de los mismos\"</span>La comunicación es previa a la iniciación de los servicios."},{"i":"23-ia-1122","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Contratación y comunicación de servicios. La comunicación de contratos de servicios de investigación privada contendrá exclusivamente los datos necesarios para identificar a las partes contratantes, excluidos:","o":["los de carácter económico.","los relativos al objeto de la investigación.","los de domicilio y contacto.","los de carácter personal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los de carácter personal</mark></span><span class=\"ref-norma\">Art.  9.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"excluidos los de carácter personal\"</span>Se excluyen los datos de carácter personal."},{"i":"23-ia-1123","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prohibiciones. Señale la opción que NO es una prohibición general de la Ley de Seguridad Privada:","o":["La prestación o publicidad de servicios de seguridad privada por quienes carezcan de autorización o declaración responsable.","El ejercicio de funciones de seguridad privada por personas físicas carentes de habilitación o acreditación profesional.","La contratación de servicios de seguridad privada por parte de las Administraciones públicas.","La prestación de servicios de seguridad privada incumpliendo los requisitos o condiciones legales de prestación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La contratación de servicios de seguridad privada por parte de las Administraciones públicas</mark></span><span class=\"ref-norma\">Art.  10.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La prestación o publicidad de servicios de seguridad privada por parte de personas, físicas o jurídicas, carentes de la correspondiente autorización o sin haber presentado declaración responsable\"</span>Las prohibiciones no alcanzan a la contratación por las Administraciones públicas."},{"i":"23-ia-1124","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prohibiciones. Está prohibido el empleo o utilización, en servicios de seguridad privada, de medios o medidas de seguridad no homologadas cuando sea preceptivo, o de medidas o medios personales, materiales o técnicos de forma tal que atenten contra el derecho:","o":["al honor, a la intimidad personal o familiar, a la propia imagen o a la inviolabilidad del domicilio, en los términos que se determinen reglamentariamente.","al honor, a la intimidad personal o familiar o a la propia imagen o al secreto de las comunicaciones.","a la intimidad, a la libertad de circulación o al secreto de las comunicaciones.","al honor, a la libertad ideológica o a la propia imagen."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al honor, a la intimidad personal o familiar o a la propia imagen o al secreto de las comunicaciones</mark></span><span class=\"ref-norma\">Art.  10.1.d · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"atenten contra el derecho al honor, a la intimidad personal o familiar o a la propia imagen o al secreto de las comunicaciones\"</span>Honor, intimidad personal o familiar, propia imagen y secreto de las comunicaciones."},{"i":"23-ia-1125","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prohibiciones. Los despachos de detectives y los detectives privados no podrán celebrar contratos que tengan por objeto la investigación de delitos:","o":["perseguibles de oficio.","perseguibles a instancia de parte.","graves o menos graves.","contra el patrimonio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">perseguibles de oficio</mark></span><span class=\"ref-norma\">Art.  10.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no podrán celebrar contratos que tengan por objeto la investigación de delitos perseguibles de oficio\"</span>No pueden investigar delitos perseguibles de oficio."},{"i":"23-ia-1126","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prohibiciones. Si un detective privado conociera un hecho de un delito perseguible de oficio, deberá:","o":["denunciarlo en el plazo de cuarenta y ocho horas ante el Ministerio Fiscal.","comunicarlo al Ministerio del Interior, que lo pondrá en conocimiento de la autoridad judicial, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","continuar la investigación y entregar el informe final a las Fuerzas y Cuerpos de Seguridad.","denunciar inmediatamente ante la autoridad competente cualquier hecho de esta naturaleza y poner a su disposición toda la información e instrumentos obtenidos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">denunciar inmediatamente ante la autoridad competente cualquier hecho de esta naturaleza y poner a su disposición toda la información e instrumentos obtenidos</mark></span><span class=\"ref-norma\">Art.  10.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"debiendo denunciar inmediatamente ante la autoridad competente cualquier hecho de esta naturaleza que llegara a su conocimiento, y poniendo a su disposición toda la información y los instrumentos que pudieran haber obtenido hasta ese momento\"</span>Deben denunciar inmediatamente y poner a disposición lo obtenido."},{"i":"23-ia-1127","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Prohibiciones. Las empresas de seguridad no podrán realizar los servicios de investigación privada propios de los despachos de detectives privados, y éstos no podrán:","o":["contratar servicios con empresas de seguridad privada, sin perjuicio de lo previsto en la normativa vigente.","prestar servicios de seguridad informática.","prestar servicios propios de las empresas de seguridad privada.","colaborar con las empresas de seguridad privada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">prestar servicios propios de las empresas de seguridad privada</mark></span><span class=\"ref-norma\">Art.  10.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y éstos no podrán prestar servicios propios de las empresas de seguridad privada\"</span>La incompatibilidad es recíproca."}]},{"a":"Artículo 23","q":[{"i":"23-130","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Cuando el Consejo de Ministros, con arreglo a lo dispuesto en la normativa sobre inversiones extranjeras, suspenda el régimen de liberalización de los movimientos de capital, la autorización previa de inversiones de capital extranjero en empresas de seguridad privada:","o":["Podrá exigir informe previo del Ministerio de Economía y Hacienda.","Exigirá, en todo caso, informe previo del Ministerio del Interior.","Podrá exigir informe previo del Ministerio del Interior.","Exigirá, en todo caso, informe previo del Ministerio de Economía y Hacienda."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Exigirá, en todo caso, informe previo del Ministerio del Interior</mark></span><span class=\"ref-norma\">Art. 23 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Cuando el Consejo de Ministros, con arreglo a lo dispuesto en la normativa sobre inversiones extranjeras, suspenda el régimen de liberalización de los movimientos de capital, la autorización previa de inversiones de capital extranjero en empresas de seguridad privada exigirá, en todo caso, informe previo del Ministerio del Interior.\"</span>"},{"i":"23-ia-1233","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Consideración de sector específico. Las empresas de seguridad privada tienen la consideración de sector económico con regulación específica en materia de:","o":["derecho de establecimiento.","libre prestación de servicios.","contratación pública.","inversiones nacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">derecho de establecimiento</mark></span><span class=\"ref-norma\">Art.  23.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"tienen la consideración de sector económico con regulación específica en materia de derecho de establecimiento\"</span>Regulación específica en materia de derecho de establecimiento."},{"i":"23-ia-1234","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Consideración de sector específico. Cuando el Consejo de Ministros suspenda el régimen de liberalización de los movimientos de capital, la autorización previa de inversiones de capital extranjero en empresas de seguridad privada exigirá, en todo caso:","o":["informe previo del Ministerio de Economía.","autorización previa del Consejo de Ministros.","comunicación posterior al Registro Nacional de Seguridad Privada.","informe previo del Ministerio del Interior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">informe previo del Ministerio del Interior</mark></span><span class=\"ref-norma\">Art.  23.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"exigirá, en todo caso, informe previo del Ministerio del Interior\"</span>Informe previo del Ministerio del Interior."},{"i":"23-ia-1235","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Consideración de sector específico. Las limitaciones en materia de inversiones de capital extranjero no son de aplicación a:","o":["las personas físicas ni jurídicas de la Unión Europea o del Espacio Económico Europeo.","las empresas con capital extranjero inferior al cincuenta por ciento.","las personas físicas nacionales de los Estados miembros de la Unión Europea ni a las empresas constituidas conforme a la legislación de un Estado miembro con sede o centro de actividad principal en la Unión Europea.","las personas jurídicas constituidas en España, cualquiera que sea el origen del capital, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las personas físicas nacionales de los Estados miembros de la Unión Europea ni a las empresas constituidas conforme a la legislación de un Estado miembro con sede o centro de actividad principal en la Unión Europea</mark></span><span class=\"ref-norma\">Art.  23.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no son de aplicación a las personas físicas nacionales de los Estados miembros de la Unión Europea ni a las empresas constituidas de conformidad con la legislación de un Estado miembro y cuya sede social, administración central o centro de actividad principal se encuentre dentro de la Unión Europea\"</span>Exentas las personas físicas nacionales de la UE y las empresas con sede o actividad principal en la UE."},{"i":"23-ia-1236","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Apertura de despachos de detectives privados. Podrán abrir despachos de detectives privados y, en su caso, sucursales, las personas físicas habilitadas como tales y las personas jurídicas constituidas exclusivamente por detectives privados habilitados, que únicamente podrán desarrollar:","o":["las actividades de investigación y las compatibles.","la actividad de investigación privada.","las actividades de seguridad privada, salvo la de transporte.","la actividad de investigación y la de planificación y asesoramiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la actividad de investigación privada</mark></span><span class=\"ref-norma\">Art.  24.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que únicamente podrán desarrollar la actividad mencionada en el artículo 5.1.h\"</span>Solo investigación privada."},{"i":"23-ia-1237","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Apertura de despachos de detectives privados. Los despachos de detectives privados se inscribirán de oficio en el Registro Nacional de Seguridad Privada o, en su caso, en el registro de la comunidad autónoma competente, previa presentación de:","o":["declaración responsable.","autorización administrativa.","comunicación previa.","solicitud de habilitación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">declaración responsable</mark></span><span class=\"ref-norma\">Art.  24.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"previa presentación de declaración responsable en la forma que reglamentariamente se determine\"</span>Se rige por declaración responsable, no por autorización."},{"i":"23-ia-1238","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Apertura de despachos de detectives privados. Los despachos de detectives deben fijar un domicilio como sede física del despacho en el que se desarrollará la actividad, se llevará el libro-registro y se encontrará:","o":["el archivo de los informes de investigación y de las grabaciones obtenidas.","el registro de clientes y el archivo de las comunicaciones con las Fuerzas y Cuerpos de Seguridad.","el archivo de los contratos y de la documentación contable.","el archivo de los expedientes de contratación y de los informes de investigación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el archivo de los expedientes de contratación y de los informes de investigación</mark></span><span class=\"ref-norma\">Art.  24.2.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se encontrará el archivo de los expedientes de contratación y de los informes de investigación\"</span>En la sede se guarda el archivo de los expedientes de contratación y de los informes de investigación."},{"i":"23-ia-1239","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Apertura de despachos de detectives privados. La validez de la declaración responsable necesaria para la apertura de los despachos de detectives y de sus sucursales será:","o":["de cinco años.","de tres años, renovable.","indefinida.","de diez años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">indefinida</mark></span><span class=\"ref-norma\">Art.  24.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La validez de la declaración responsable necesaria para la apertura de los despachos de detectives y de sus sucursales será indefinida\"</span>Es indefinida."},{"i":"23-ia-1240","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Apertura de despachos de detectives privados. El incumplimiento sobrevenido de los requisitos exigidos para la apertura de los despachos de detectives producirá:","o":["la suspensión de la actividad y la apertura de un expediente sancionador.","el cierre de los mismos y la cancelación de oficio de su inscripción.","la extinción de la habilitación de su titular.","la cancelación de la inscripción, previa audiencia del titular."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el cierre de los mismos y la cancelación de oficio de su inscripción</mark></span><span class=\"ref-norma\">Art.  24.5 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"producirá el cierre de los mismos y la cancelación de oficio de su inscripción\"</span>Cierre del despacho y cancelación de oficio de su inscripción."}]},{"a":"Artículo 7","q":[{"i":"23-137","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades excluidas. Queda fuera del ámbito de aplicación de la ley la obtención por uno mismo de información o datos, así como la contratación de servicios de recepción, recopilación, análisis, comunicación o suministro de información libre obrante en:","o":["Registros públicos de acceso reservado a las Fuerzas y Cuerpos de Seguridad.","Fuentes o registros de acceso público.","Fuentes o registros de las Administraciones públicas, previa autorización.","Archivos de entidades privadas, con consentimiento de sus titulares."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Fuentes o registros de acceso público</mark></span><span class=\"ref-norma\">Art. 7.2 · Ley 5/2014 de Seguridad Privada</span> <span class=\"ref-concepto\">\"información libre obrante en fuentes o registros de acceso público\"</span>"},{"i":"23-ia-1109","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades excluidas. No están sujetas a la Ley de Seguridad Privada las actuaciones de autoprotección, entendidas como el conjunto de cautelas o diligencias que se ejecuten por sí y para sí mismos de forma directa los interesados, y cuya práctica o aplicación:","o":["no conlleve contraprestación alguna ni suponga algún tipo de servicio de seguridad privada prestado a terceros.","no conlleve contraprestación económica, aunque suponga servicios de seguridad prestados a terceros, sin perjuicio de lo previsto en la normativa vigente.","no requiera la utilización de medios técnicos ni suponga contraprestación alguna.","no suponga coste para el interesado ni intervención de empresas de seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no conlleve contraprestación alguna ni suponga algún tipo de servicio de seguridad privada prestado a terceros</mark></span><span class=\"ref-norma\">Art.  7.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"cuya práctica o aplicación no conlleve contraprestación alguna ni suponga algún tipo de servicio de seguridad privada prestado a terceros\"</span>Sin contraprestación y sin servicio de seguridad a terceros."},{"i":"23-ia-1110","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades excluidas. Cuando los interesados que realicen actuaciones de autoprotección tengan el carácter de empresas o entidades de cualquier tipo, en ningún caso:","o":["podrán realizar actuaciones de autoprotección sin comunicarlo al Ministerio del Interior.","utilizarán a sus empleados para tareas de vigilancia sin haber obtenido la correspondiente autorización, en los términos que se determinen reglamentariamente.","podrán contratar servicios de autoprotección con empresas de seguridad privada.","utilizarán a sus empleados para el desarrollo de las funciones previstas en la ley, reservadas a las empresas y el personal de seguridad privada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">utilizarán a sus empleados para el desarrollo de las funciones previstas en la ley, reservadas a las empresas y el personal de seguridad privada</mark></span><span class=\"ref-norma\">Art.  7.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en ningún caso utilizarán a sus empleados para el desarrollo de las funciones previstas en la presente ley, reservadas a las empresas y el personal de seguridad privada\"</span>No pueden usar a sus empleados para funciones reservadas a empresas y personal de seguridad privada."},{"i":"23-ia-1111","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Actividades excluidas. Queda fuera del ámbito de aplicación de la ley la obtención por uno mismo de información o datos, así como la contratación de servicios de recepción, recopilación, análisis, comunicación o suministro de información libre obrante en:","o":["fuentes o registros de las Administraciones públicas.","registros públicos y privados de acceso reservado.","fuentes o registros de acceso público.","archivos y ficheros de entidades privadas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">fuentes o registros de acceso público</mark></span><span class=\"ref-norma\">Art.  7.2 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"información libre obrante en fuentes o registros de acceso público\"</span>Se trata de información libre en fuentes o registros de acceso público."}]},{"a":"General / Seguridad Privada","q":[{"i":"23-ia-1001","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. En el preámbulo de la Ley de Seguridad Privada se afirma que la existencia de la seguridad privada se configura como una medida de anticipación y __________ frente a posibles riesgos, peligros o delitos:","o":["prevención","protección, en los términos que se determinen reglamentariamente.","disuasión","reacción"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">prevención</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"la existencia de la seguridad privada se configura como una medida de anticipación y prevención frente a posibles riesgos, peligros o delitos\"</span>Es una medida de anticipación y prevención."},{"i":"23-ia-1002","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La proyección de la Administración del Estado sobre la prestación de servicios de seguridad por entidades privadas se basa en que forman parte del núcleo esencial de la competencia exclusiva en materia de __________ atribuida al Estado por la Constitución:","o":["orden público","seguridad ciudadana","protección civil","seguridad pública"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">seguridad pública</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"forman parte del núcleo esencial de la competencia exclusiva en materia de seguridad pública atribuida al Estado\"</span>La competencia exclusiva del Estado es en materia de seguridad pública."},{"i":"23-ia-1003","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Según el preámbulo de la Ley de Seguridad Privada, el conjunto de los cambios propuestos profundiza en el actual modelo español de seguridad privada, que es:","o":["complementaria, subsidiaria, colaboradora y supervisada por la seguridad pública.","autónoma, complementaria, colaboradora y controlada por la seguridad pública.","complementaria, subordinada, colaboradora y controlada por la seguridad pública.","complementaria, subordinada, cooperante y dirigida por la seguridad pública."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">complementaria, subordinada, colaboradora y controlada por la seguridad pública</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"(complementaria, subordinada, colaboradora y controlada por la seguridad pública)\"</span>El modelo es complementario, subordinado, colaborador y controlado por la seguridad pública."},{"i":"23-ia-1004","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La Ley de Seguridad Privada pasa de poner el acento en el principio de la subordinación a desarrollar más eficazmente el principio de complementariedad a través de otros que lo desarrollan, como los de:","o":["colaboración o de coordinación.","cooperación o de corresponsabilidad.","cooperación o de subsidiariedad.","corresponsabilidad o de jerarquía, salvo que la autoridad judicial disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cooperación o de corresponsabilidad</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"los de cooperación o de corresponsabilidad\"</span>Los principios que desarrollan la complementariedad son cooperación y corresponsabilidad."},{"i":"23-ia-1005","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La reforma en profundidad de la regulación legal de la seguridad privada pivota sobre dos ejes. En primer lugar, sobre la base irrenunciable de la preeminencia de la seguridad __________ sobre la seguridad privada:","o":["pública","ciudadana","nacional","institucional"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">pública</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"sobre la base irrenunciable de la preeminencia de la seguridad pública sobre la seguridad privada\"</span>La base irrenunciable es la preeminencia de la seguridad pública."},{"i":"23-ia-1006","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. En materia de reparto competencial, la Ley de Seguridad Privada afianza la competencia exclusiva del Estado en materia normativa y sitúa en la órbita ejecutiva las competencias de:","o":["las corporaciones locales.","las Delegaciones del Gobierno.","las Juntas de Seguridad.","las comunidades autónomas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las comunidades autónomas</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se afianza la competencia exclusiva del Estado en materia normativa y se sitúan en la órbita ejecutiva las competencias de las comunidades autónomas\"</span>Las competencias ejecutivas quedan en la órbita de las comunidades autónomas."},{"i":"23-ia-1007","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La Ley de Seguridad Privada está dotada de sistematicidad normativa a lo largo de sus:","o":["seis títulos.","ocho títulos.","siete títulos.","cinco títulos y un título preliminar."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">siete títulos</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"dotada de sistematicidad normativa a lo largo de sus siete títulos\"</span>La ley se estructura en siete títulos."},{"i":"23-ia-1008","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. En la regulación de la seguridad de la información y las comunicaciones, la Ley de Seguridad Privada la configura por primera vez no como actividad específica de seguridad privada, sino como actividad:","o":["complementaria, reservada a las empresas de seguridad privada.","compatible, que podrá ser desarrollada tanto por empresas de seguridad como por las que no lo sean.","compatible, reservada a las empresas de seguridad con autorización administrativa, previo informe de la unidad policial competente.","subordinada, que solo podrá ser desarrollada por empresas de seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">compatible, que podrá ser desarrollada tanto por empresas de seguridad como por las que no lo sean</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"no como actividad específica de seguridad privada, sino como actividad compatible que podrá ser desarrollada tanto por empresas de seguridad como por las que no lo sean\"</span>Es una actividad compatible que pueden realizar empresas de seguridad o no."},{"i":"23-ia-1009","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. En el preámbulo de la Ley de Seguridad Privada se reconoce a los operadores de seguridad la condición de personal:","o":["acreditado.","habilitado.","autorizado.","colaborador."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">acreditado</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"se reconoce a los operadores de seguridad la condición de personal acreditado\"</span>Los operadores de seguridad son personal acreditado."},{"i":"23-ia-1010","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Los registros de empresas de seguridad y de despachos de detectives se unifican, según el preámbulo de la ley, en el nuevo:","o":["Registro Central de Seguridad Privada.","Registro Único de Empresas de Seguridad.","Registro General de Seguridad Privada.","Registro Nacional de Seguridad Privada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Registro Nacional de Seguridad Privada</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que se unifican en el nuevo Registro Nacional de Seguridad Privada\"</span>Se unifican en el Registro Nacional de Seguridad Privada."},{"i":"23-ia-1011","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La ley sustituye el sistema más gravoso de la autorización administrativa por el de la declaración responsable para los centros de formación de personal de seguridad privada, los despachos de detectives privados y:","o":["las empresas de vigilancia y protección.","las empresas de depósito y transporte de seguridad.","las empresas de instalación y mantenimiento.","las centrales receptoras de alarmas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las empresas de instalación y mantenimiento</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"los despachos de detectives privados y las empresas de instalación y mantenimiento\"</span>También pasan a declaración responsable las empresas de instalación y mantenimiento."},{"i":"23-ia-1012","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. La ley modifica el nombre de los guardas particulares del campo, para configurarlos, más adecuadamente, como:","o":["guardas forestales.","guardas rurales.","vigilantes rurales.","guardas de campo y caza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">guardas rurales</mark></span><span class=\"ref-norma\">Preámbulo · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"para configurarlos, más adecuadamente, como guardas rurales\"</span>Pasan a denominarse guardas rurales."}]},{"a":"Artículo 18","q":[{"i":"23-ia-1208","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Autorización administrativa. Para la prestación de servicios de seguridad privada, las empresas de seguridad privada deberán obtener autorización administrativa y serán inscritas:","o":["a instancia de parte en el Registro Nacional.","de oficio en el registro correspondiente.","de oficio, previo pago de la tasa correspondiente.","a solicitud de la empresa, en el plazo de un mes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de oficio en el registro correspondiente</mark></span><span class=\"ref-norma\">Art.  18.1 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"deberán obtener autorización administrativa y serán inscritas de oficio en el registro correspondiente\"</span>Se inscriben de oficio."},{"i":"23-ia-1210","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Autorización administrativa. La validez de la autorización o de la declaración responsable de las empresas de seguridad privada será:","o":["de cinco años, renovable.","de diez años, prorrogable por períodos iguales.","de tres años, renovable previa inspección.","indefinida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">indefinida</mark></span><span class=\"ref-norma\">Art.  18.3 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"La validez de la autorización o de la declaración responsable será indefinida\"</span>Es indefinida."},{"i":"23-ia-1211","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Las empresas de seguridad privada deberán estar legalmente constituidas e inscritas en el registro mercantil o en el registro público correspondiente y tener por objeto exclusivo todas o alguna de las actividades de seguridad privada, excepto la investigación privada. No obstante, en dicho objeto podrán incluir:","o":["cualquier actividad empresarial de carácter complementario, previa autorización.","las actividades de investigación privada, siempre que cuenten con detectives habilitados, en los términos que se determinen reglamentariamente.","las actividades que resulten imprescindibles para el cumplimiento de las actividades de seguridad autorizadas, así como las compatibles.","las actividades compatibles, pero no las imprescindibles para las de seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las actividades que resulten imprescindibles para el cumplimiento de las actividades de seguridad autorizadas, así como las compatibles</mark></span><span class=\"ref-norma\">Art.  19.1.a · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"podrán incluir las actividades que resulten imprescindibles para el cumplimiento de las actividades de seguridad autorizadas, así como las compatibles contempladas en el artículo 6\"</span>Pueden incluir las imprescindibles para las actividades autorizadas y las compatibles."},{"i":"23-ia-1212","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Entre los requisitos generales de las empresas de seguridad privada está tener la nacionalidad de:","o":["un Estado miembro de la Unión Europea, exclusivamente.","un Estado miembro de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo.","un Estado miembro de la Unión Europea o de cualquier Estado con convenio con España, salvo que la autoridad judicial disponga otra cosa.","España o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un Estado miembro de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo</mark></span><span class=\"ref-norma\">Art.  19.1.b · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"Tener la nacionalidad de un Estado miembro de la Unión Europea o de un Estado parte en el Acuerdo sobre el Espacio Económico Europeo\"</span>UE o Estado parte en el Acuerdo sobre el Espacio Económico Europeo."},{"i":"23-ia-1213","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Los ingenieros y técnicos de las empresas de seguridad privada y los operadores de seguridad deberán disponer de la correspondiente acreditación expedida por el Ministerio del Interior, que se limitará a comprobar:","o":["la honorabilidad del solicitante y la carencia de antecedentes penales.","la aptitud psicológica y la formación técnica del solicitante, previo informe de la unidad policial competente.","la capacidad física y la carencia de antecedentes penales.","la honorabilidad y la experiencia profesional del solicitante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la honorabilidad del solicitante y la carencia de antecedentes penales</mark></span><span class=\"ref-norma\">Art.  19.1.c · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que se limitará a comprobar la honorabilidad del solicitante y la carencia de antecedentes penales, en los términos que reglamentariamente se establezca\"</span>Se limita a la honorabilidad y la carencia de antecedentes penales."},{"i":"23-ia-1214","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Entre los requisitos generales de las empresas de seguridad privada está suscribir un contrato de seguro de responsabilidad civil o constituir otras garantías financieras:","o":["por el importe mínimo que fije cada año el Ministerio del Interior.","en la cuantía que se determine en la autorización administrativa.","con una entidad aseguradora autorizada por la Dirección General de Seguros.","en la cuantía y con las condiciones que se determinen reglamentariamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en la cuantía y con las condiciones que se determinen reglamentariamente</mark></span><span class=\"ref-norma\">Art.  19.1.e · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en la cuantía y con las condiciones que se determinen reglamentariamente\"</span>Cuantía y condiciones reglamentarias."},{"i":"23-ia-1215","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Las empresas de seguridad privada deben constituir el aval o seguro de caución que se determine reglamentariamente a disposición de las autoridades españolas, para atender exclusivamente:","o":["las responsabilidades civiles frente a terceros derivadas de los servicios prestados, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","las responsabilidades laborales con el personal de seguridad privada.","las responsabilidades administrativas por infracciones a la normativa de seguridad privada que se deriven del funcionamiento de la empresa.","las responsabilidades penales y administrativas de sus representantes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las responsabilidades administrativas por infracciones a la normativa de seguridad privada que se deriven del funcionamiento de la empresa</mark></span><span class=\"ref-norma\">Art.  19.1.f · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"para atender exclusivamente las responsabilidades administrativas por infracciones a la normativa de seguridad privada que se deriven del funcionamiento de la empresa\"</span>Atiende exclusivamente las responsabilidades administrativas por infracciones."},{"i":"23-ia-1216","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Las empresas de seguridad privada no deben haber sido condenadas mediante sentencia firme por intromisión ilegítima en el ámbito de protección del derecho al honor, a la intimidad personal y familiar o a la propia imagen, vulneración del secreto de las comunicaciones o de otros derechos fundamentales en:","o":["los dos años anteriores a la solicitud.","los cinco años anteriores a la solicitud.","los diez años anteriores a la solicitud, salvo que la autoridad judicial disponga otra cosa.","los tres años anteriores a la solicitud."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los cinco años anteriores a la solicitud</mark></span><span class=\"ref-norma\">Art.  19.1.h · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"en los cinco años anteriores a la solicitud\"</span>El plazo es de cinco años anteriores a la solicitud."},{"i":"23-ia-1217","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Para la contratación de servicios de seguridad privada en los sectores estratégicos definidos en la legislación de protección de infraestructuras críticas, las empresas de seguridad privada deberán contar, con carácter previo a su prestación, con:","o":["una certificación emitida por una entidad de certificación acreditada.","una autorización especial del Ministerio del Interior.","una inspección favorable de las Fuerzas y Cuerpos de Seguridad, previo informe de la unidad policial competente.","un informe de la Comisión Nacional de Seguridad Privada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una certificación emitida por una entidad de certificación acreditada</mark></span><span class=\"ref-norma\">Art.  19.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"deberán contar, con carácter previo a su prestación, con una certificación emitida por una entidad de certificación acreditada\"</span>Certificación de una entidad de certificación acreditada."},{"i":"23-ia-1218","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. La certificación exigida a las empresas de seguridad para prestar servicios en sectores estratégicos garantizará, como mínimo, el cumplimiento de la normativa:","o":["administrativa, laboral, de prevención de riesgos y mercantil.","laboral, de Seguridad Social, tributaria y de protección de datos, sin perjuicio de lo previsto en la normativa vigente.","administrativa, de Seguridad Social y de seguridad privada.","administrativa, laboral, de Seguridad Social y tributaria que les sea de aplicación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">administrativa, laboral, de Seguridad Social y tributaria que les sea de aplicación</mark></span><span class=\"ref-norma\">Art.  19.4 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"que garantice, como mínimo, el cumplimiento de la normativa administrativa, laboral, de Seguridad Social y tributaria que les sea de aplicación\"</span>Normativa administrativa, laboral, de Seguridad Social y tributaria."},{"i":"23-ia-1219","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. Las empresas de seguridad privada no españolas, autorizadas con arreglo a la normativa de un Estado miembro de la Unión Europea o parte en el Acuerdo sobre el Espacio Económico Europeo, habrán de inscribirse:","o":["voluntariamente en el Registro Nacional de Seguridad Privada.","obligatoriamente en el Registro Nacional, en todo caso.","obligatoriamente en el Registro Nacional de Seguridad Privada o, en su caso, en el registro autonómico correspondiente.","en el registro de la comunidad autónoma donde presten servicios, en todo caso, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">obligatoriamente en el Registro Nacional de Seguridad Privada o, en su caso, en el registro autonómico correspondiente</mark></span><span class=\"ref-norma\">Art.  19.6 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"habrán de inscribirse obligatoriamente en el Registro Nacional de Seguridad Privada del Ministerio del Interior o, cuando tengan su domicilio en una comunidad autónoma con competencias en materia de seguridad privada y su ámbito de actuación limitado a dicho territorio, en el registro autonómico correspondiente\"</span>La inscripción es obligatoria en el Registro Nacional o, si procede, en el autonómico."},{"i":"23-ia-1220","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. A las empresas de seguridad privada que tengan por objeto exclusivo la instalación o mantenimiento de sistemas con conexión a centrales receptoras de alarma se las podrá eximir de alguno de los requisitos generales, excepto los relativos a:","o":["las medidas de seguridad y el aval o seguro de caución.","el contrato de seguro de responsabilidad civil y el aval o seguro de caución.","la nacionalidad y el contrato de seguro de responsabilidad civil, salvo que la autoridad judicial disponga otra cosa.","los medios humanos y financieros adecuados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el contrato de seguro de responsabilidad civil y el aval o seguro de caución</mark></span><span class=\"ref-norma\">Art.  19.7 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"excepto los contemplados en los párrafos e) y f) del apartado 1\"</span>Se exceptúan el seguro de responsabilidad civil y el aval o seguro de caución."},{"i":"23-ia-1221","p":"Ley 5/2014, de 4 de abril, de Seguridad Privada. Requisitos generales. El incumplimiento sobrevenido de los requisitos generales de las empresas de seguridad privada dará lugar a la extinción de la autorización o al cierre de la empresa, en el caso de presentación de declaración responsable, y, en ambos casos, a:","o":["la cancelación de oficio de la inscripción de la empresa de seguridad en el registro correspondiente.","la suspensión de la actividad hasta que subsane el incumplimiento.","la imposición de una sanción por infracción grave.","la comunicación del incumplimiento a las Fuerzas y Cuerpos de Seguridad, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la cancelación de oficio de la inscripción de la empresa de seguridad en el registro correspondiente</mark></span><span class=\"ref-norma\">Art.  19.8 · Ley 5/2014, de 4 de abril, de Seguridad Privada</span><span class=\"ref-concepto\">\"y, en ambos casos, a la cancelación de oficio de la inscripción de la empresa de seguridad en el registro correspondiente\"</span>En ambos casos se cancela de oficio la inscripción."}]}];
